window.__BOOK__={"meta":{"title_fr":"Le Petit Prince","title_zh":"小王子","author_fr":"Antoine de Saint-Exupéry","author_zh":"安托万·德·圣埃克苏佩里","voice":"fr-FR-DeniseNeural (edge-tts)","ipa_note":"音标为宽式音位转写（法语近似发音，不标重音、不处理联诵），仅供参考。","n_chapters":28,"n_paras":783,"n_sents":1653,"audio_paras":783},"chapters":[{"id":"ch00","title_fr":"À Léon Werth","title_zh":"献词","paras":[{"id":"ch00p00","audio":true,"sents":[{"fr":"À Léon Werth.","zh":"致莱昂·韦尔","t":[100,1962]},{"fr":"Je demande aux enfants de m'excuser de dédier ce livre à une grande personne.","zh":"我请求孩子们原谅我将这本书献给一个伟大的人。","t":[1962,6538]},{"fr":"J'ai une excuse sérieuse : cette grande personne est le meilleur ami que j'ai au monde.","zh":"我有严肃的借口：这位伟大的人是我在这个世界上最好的朋友。","t":[6538,11725]},{"fr":"J'ai une autre excuse : cette grande personne peut tout comprendre, même les livres pour enfants.","zh":"我还有另一个借口：这位伟大的人能理解一切，甚至儿童书籍。","t":[11725,17450]},{"fr":"J'ai une troisième excuse : cette grande personne habite la France où elle a faim et froid.","zh":"我还有一个借口：这位伟大的人住在法国，那里她饥寒交迫。","t":[17450,22900]},{"fr":"Elle a besoin d'être consolée.","zh":"她需要安慰。","t":[22900,25388]},{"fr":"Si toutes ces raisons ne suffisent pas, je veux dédier ce livre à l'enfant qu'a été autrefois cette grande personne.","zh":"如果这些理由还不够，我想将这本书献给我曾经是那个伟大的人的孩子。","t":[25388,31550]},{"fr":"Toutes les grandes personnes ont d'abord été des enfants.","zh":"所有的大人最初都是孩子。","t":[31550,34662]},{"fr":"(Mais peu d'entre elles s'en souviennent.) Je corrige donc ma dédicace : À LEON WERTH, QUAND IL ÉTAIT PETIT GARÇON.","zh":"(但她们中的少数人还记得。) 因此，我修正了我的献词：献给莱昂·韦尔，当他还是个小男孩的时候。","t":[34662,41287]}]}]},{"id":"ch01","title_fr":"Chapitre I","title_zh":"第 1 章","paras":[{"id":"ch01p00","audio":true,"sents":[{"fr":"Lorsque j’avais six ans j’ai vu, une fois, une magnifique image, dans un livre sur la Forêt Vierge qui s’appelait \"Histoires Vécues\".","zh":"当我六岁的时候，我在一本关于原始森林的书上看到了一幅美丽的画面，那本书叫做《亲身经历的故事》。","t":[100,7875]},{"fr":"Ça représentait un serpent boa qui avalait un fauve.","zh":"这是一条吞食着一只野兽的 boa 蛇。","t":[7875,11488]},{"fr":"Voilà la copie du dessin.","zh":"这是我的画稿。","t":[11488,12938]}]},{"id":"ch01p01","audio":true,"sents":[{"fr":"On disait dans le livre : \"Les serpents boas avalent leur proie tout entière, sans la mâcher.","zh":"书中写道：\" boa 蛇会整个吞下猎物，而不咀嚼。","t":[100,6088]},{"fr":"Ensuite ils ne peuvent plus bouger et ils dorment pendant les six mois de leur digestion\".","zh":"然后它们就不能动了，在消化过程中，它们会睡上六个月。","t":[6088,10013]}]},{"id":"ch01p02","audio":true,"sents":[{"fr":"J’ai alors beaucoup réfléchi sur les aventures de la jungle et, à mon tour, j’ai réussi, avec un crayon de couleur, à tracer mon premier dessin.","zh":"于是我开始思考丛林中的冒险，然后我用彩色铅笔，成功地画出了我的第一幅画。","t":[100,9025]},{"fr":"Mon dessin numéro 1.","zh":"这是我的第一幅画。","t":[9025,10038]},{"fr":"Il était comme ça :","zh":"它看起来是这样的：","t":[10038,12825]}]},{"id":"ch01p03","audio":true,"sents":[{"fr":"J’ai montré mon chef d’œuvre aux grandes personnes et je leur ai demandé si mon dessin leur faisait peur.","zh":"我把我的杰作给大人看，并问他们我的画是否吓到了他们。","t":[100,4650]}]},{"id":"ch01p04","audio":true,"sents":[{"fr":"Elles m’ont répondu : \"Pourquoi un chapeau ferait-il peur ?\"","zh":"他们回答说：\"为什么一顶帽子会让人害怕？\"","t":[100,4250]}]},{"id":"ch01p05","audio":true,"sents":[{"fr":"Mon dessin ne représentait pas un chapeau.","zh":"我的画并不是一顶帽子。","t":[100,2962]},{"fr":"Il représentait un serpent boa qui digérait un éléphant.","zh":"它代表了一条正在消化大象的 boa 蛇。","t":[2962,6725]},{"fr":"J’ai alors dessiné l’intérieur du serpent boa, afin que les grandes personnes puissent comprendre.","zh":"于是，我画出了 boa 蛇的内部，以便大人们能够理解。","t":[6725,12488]},{"fr":"Elles ont toujours besoin d’explications.","zh":"他们总是需要解释。","t":[12488,15350]},{"fr":"Mon dessin numéro 2 était comme ça :","zh":"我的第二幅画是这样的：","t":[15350,17937]}]},{"id":"ch01p06","audio":true,"sents":[{"fr":"Les grandes personnes m’ont conseillé de laisser de côté les dessins de serpents boas ouverts ou fermés, et de m’intéresser plutôt à la géographie, à l’histoire, au calcul et à la grammaire.","zh":"大人们建议我放下 boa 蛇张开或闭合的画，而应该关注地理、历史、算术和语法。","t":[100,10600]},{"fr":"C’est ainsi que j’ai abandonné, à l’âge de six ans, une magnifique carrière de peintre.","zh":"就这样，我在六岁那年放弃了成为一名画家的美好生涯。","t":[10600,16188]},{"fr":"J’avais été découragé par l’insuccès de mon dessin numéro 1 et de mon dessin numéro 2.","zh":"我的第一幅画和第二幅画的失败让我感到沮丧。","t":[16188,20638]},{"fr":"Les grandes personnes ne comprennent jamais rien toutes seules, et c’est fatigant, pour les enfants, de toujours leur donner des explications.","zh":"大人们永远不能自己理解任何事情，而且对孩子来说，总是给他们解释是很累人的。","t":[20638,28612]}]},{"id":"ch01p07","audio":true,"sents":[{"fr":"J’ai donc dû choisir un autre métier et j’ai appris à piloter des avions.","zh":"因此，我不得不选择另一份职业，并学习了驾驶飞机。","t":[100,4812]},{"fr":"J’ai volé un peu partout dans le monde.","zh":"我在世界各地都飞过。","t":[4812,7550]},{"fr":"Et la géographie, c’est exact, m’a beaucoup servi.","zh":"地理学，确实，对我很有帮助。","t":[7550,11812]},{"fr":"Je savais reconnaître, du premier coup d’œil, la Chine de l’Arizona.","zh":"我一眼就能认出亚利桑那州的‘中国’。","t":[11812,16825]},{"fr":"C’est très utile, si l’on est égaré pendant la nuit.","zh":"如果晚上迷路了，这很有用。","t":[16825,19500]}]},{"id":"ch01p08","audio":true,"sents":[{"fr":"J’ai ainsi eu, au cours de ma vie, des tas de contacts avec des tas de gens sérieux.","zh":"在我的生活中，我遇到了很多严肃的人。","t":[100,5200]},{"fr":"J’ai beaucoup vécu chez les grandes personnes.","zh":"我在大人那里生活过很多。","t":[5200,8188]},{"fr":"Je les ai vues de très près.","zh":"我近距离观察过他们。","t":[8188,10350]},{"fr":"Ça n’a pas trop amélioré mon opinion.","zh":"这并没有太多改善我的看法。","t":[10350,12325]}]},{"id":"ch01p09","audio":true,"sents":[{"fr":"Quand j’en rencontrais une qui me paraissait un peu lucide, je faisais l’expérience sur elle de mon dessin n° 1 que j’ai toujours conservé.","zh":"当我遇到一个我觉得有点清醒的人时，我就用我始终保留的 No. 1 绘画做实验。","t":[100,7850]},{"fr":"Je voulais savoir si elle était vraiment compréhensive.","zh":"我想知道她是否真的理解。","t":[7850,11400]},{"fr":"Mais toujours elle me répondait : \"C’est un chapeau.\" Alors je ne lui parlais ni de serpents boas, ni de forêts vierges, ni d’étoiles.","zh":"但她总是回答我：‘这是一顶帽子。’所以我不和她谈论 boa 蛇、原始森林或星星。","t":[11400,20888]},{"fr":"Je me mettais à sa portée.","zh":"我走近他。","t":[20888,23238]},{"fr":"Je lui parlais de bridge, de golf, de politique et de cravates.","zh":"我跟他谈论桥牌、高尔夫、政治和领带。","t":[23238,27888]},{"fr":"Et la grande personne était bien contente de connaître un homme aussi raisonnable.","zh":"那个大人物很高兴认识一个如此有理性的人。","t":[27888,31688]}]},{"id":"ch01p10","audio":true,"sents":[]}]},{"id":"ch02","title_fr":"Chapitre II","title_zh":"第 2 章","paras":[{"id":"ch02p00","audio":true,"sents":[{"fr":"J’ai ainsi vécu seul, sans personne avec qui parler véritablement, jusqu’à une panne dans le désert du Sahara, il y a six ans.","zh":"就这样，我在没有真正可以交谈的人陪伴下独自生活，直到六年前在撒哈拉沙漠的一次故障。","t":[100,7825]},{"fr":"Quelque chose s’était cassé dans mon moteur.","zh":"我的发动机里有些东西坏了。","t":[7825,10888]},{"fr":"Et comme je n’avais avec moi ni mécanicien, ni passagers, je me préparai à essayer de réussir, tout seul, une réparation difficile.","zh":"由于我没有机械师或乘客，我准备尝试独自完成一次困难的修理。","t":[10888,19675]},{"fr":"C’était pour moi une question de vie ou de mort.","zh":"这对我是生与死的问题。","t":[19675,22750]},{"fr":"J’avais à peine de l’eau à boire pour huit jours.","zh":"我只有足够喝八天的水。","t":[22750,25025]}]},{"id":"ch02p01","audio":true,"sents":[{"fr":"Le premier soir je me suis donc endormi sur le sable à mille milles de toute terre habitée.","zh":"第一个晚上，我就睡在了离任何有人居住的陆地一千英里的沙地上。","t":[100,5175]},{"fr":"J’étais bien plus isolé qu’un naufragé sur un radeau au milieu de l’océan.","zh":"我比一个在海洋中央的救生筏上的遇难者还要孤独。","t":[5175,9762]},{"fr":"Alors vous imaginez ma surprise, au lever du jour, quand une drôle de petite voix m’a réveillé.","zh":"那么，你们可以想象，当第一缕晨光到来时，我被一个奇怪的小声音叫醒时的惊讶。","t":[9762,15850]},{"fr":"Elle disait :","zh":"她说道：","t":[15850,17274]}]},{"id":"ch02p02","audio":true,"sents":[{"fr":"— S’il vous plaît…","zh":"—— 请……","t":[100,2125]},{"fr":"dessine-moi un mouton !","zh":"给我画一只绵羊！","t":[2125,3887]}]},{"id":"ch02p03","audio":true,"sents":[{"fr":"— Hein !","zh":"—— 嗯？","t":[100,2163]}]},{"id":"ch02p04","audio":true,"sents":[{"fr":"— Dessine-moi un mouton…","zh":"—— 给我画一只绵羊……","t":[100,2387]}]},{"id":"ch02p05","audio":true,"sents":[{"fr":"J’ai sauté sur mes pieds comme si j’avais été frappé par la foudre.","zh":"我像被闪电击中一样跳了起来。","t":[100,4088]},{"fr":"J’ai bien frotté mes yeux.","zh":"我确实揉了揉眼睛。","t":[4088,6225]},{"fr":"J’ai bien regardé.","zh":"我确实仔细地看了。","t":[6225,8200]},{"fr":"Et j’ai vu un petit bonhomme tout à fait extraordinaire qui me considérait gravement.","zh":"我看见了一个非常特别的小家伙，他严肃地打量着我。","t":[8200,13100]},{"fr":"Voilà le meilleur portrait que, plus tard, j’ai réussi à faire de lui.","zh":"这就是后来我为他画的最像的一幅肖像。","t":[13100,17962]},{"fr":"Mais mon dessin, bien sûr, est beaucoup moins ravissant que le modèle.","zh":"当然，我的画远不如本人好看。","t":[17962,22712]},{"fr":"Ce n’est pas ma faute.","zh":"这不是我的错。","t":[22712,24688]},{"fr":"J’avais été découragé dans ma carrière de peintre par les grandes personnes, à l’âge de six ans, et je n’avais rien appris à dessiner, sauf les boas fermés et les boas ouverts.","zh":"我在六岁时就被大人们打消了成为画家的念头，除了画过闭着的和开着蟒蛇，我什么都没学会画。","t":[24688,33812]}]},{"id":"ch02p06","audio":true,"sents":[{"fr":"Je regardai donc cette apparition avec des yeux tout ronds d’étonnement.","zh":"于是我惊奇地睁大眼睛看着这个突然出现的小家伙。","t":[100,4875]},{"fr":"N’oubliez pas que je me trouvais à mille milles de toute région habitée.","zh":"别忘了我当时身处一千英里之外，远离任何有人居住的地方。","t":[4875,8300]},{"fr":"Or mon petit bonhomme ne me semblait ni égaré, ni mort de fatigue, ni mort de faim, ni mort de soif, ni mort de peur.","zh":"然而我的小家伙看起来既不像迷了路，也不像累死、饿死、渴死或吓死的样子。","t":[8300,16250]},{"fr":"Il n’avait en rien l’apparence d’un enfant perdu au milieu du désert, à mille milles de toute région habitée.","zh":"他完全不像一个迷失在沙漠中、远离任何有人居住的地方的孩子。","t":[16250,22388]},{"fr":"Quand je réussis enfin à parler, je lui dis :","zh":"当我终于能够开口说话时，我对他说：","t":[22388,25538]}]},{"id":"ch02p07","audio":true,"sents":[{"fr":"— Mais…","zh":"但是……","t":[100,1650]},{"fr":"qu’est-ce que tu fais là ?","zh":"你在那里做什么？","t":[1650,3263]}]},{"id":"ch02p08","audio":true,"sents":[{"fr":"Et il me répéta alors, tout doucement, comme une chose très sérieuse :","zh":"然后他轻声地重复，仿佛这是一件非常严肃的事情：","t":[100,4387]}]},{"id":"ch02p09","audio":true,"sents":[{"fr":"— S’il vous plaît…","zh":"请……","t":[100,2112]},{"fr":"dessine-moi un mouton…","zh":"给我画一只绵羊……","t":[2112,3162]}]},{"id":"ch02p10","audio":true,"sents":[{"fr":"Quand le mystère est trop impressionnant, on n’ose pas désobéir.","zh":"当神秘的事物太过震撼时，我们不敢违抗。","t":[100,4150]},{"fr":"Aussi absurde que cela me semblât à mille milles de tous les endroits habités et en danger de mort, je sortis de ma poche une feuille de papier et un stylographe.","zh":"尽管这在我看来像是在千千万万个危险的地方，我仍然从口袋里掏出了一张纸和一支钢笔。","t":[4150,13125]},{"fr":"Mais je me rappelai alors que j’avais surtout étudié la géographie, l’histoire, le calcul et la grammaire et je dis au petit bonhomme (avec un peu de mauvaise humeur) que je ne savais pas dessiner.","zh":"但我想起了我主要学习的是地理、历史、计算和语法，我对这个小家伙（带着一点不高兴）说我不会画画。","t":[13125,24125]},{"fr":"Il me répondit :","zh":"他回答道：","t":[24125,25850]}]},{"id":"ch02p11","audio":true,"sents":[{"fr":"— Ça ne fait rien.","zh":"没关系。","t":[100,2912]},{"fr":"Dessine-moi un mouton.","zh":"画一只绵羊给我看。","t":[2912,4126]}]},{"id":"ch02p12","audio":true,"sents":[{"fr":"Comme je n’avais jamais dessiné un mouton je refis, pour lui, l’un des deux seuls dessins dont j’étais capable.","zh":"因为我从来没有画过绵羊，所以我重新画了一张，这是我唯一会画的两个画中的一个。","t":[100,6462]},{"fr":"Celui du boa fermé.","zh":"就是那条闭着的 boa。","t":[6462,8588]},{"fr":"Et je fus stupéfait d’entendre le petit bonhomme me répondre :","zh":"我惊讶地听到小家伙回答我：","t":[8588,12162]}]},{"id":"ch02p13","audio":true,"sents":[{"fr":"— Non !","zh":"—— 不是！","t":[100,3125]},{"fr":"Non !","zh":"不是！","t":[3125,5112]},{"fr":"Je ne veux pas d’un éléphant dans un boa.","zh":"我不要一条 boa 里的象。","t":[5112,7950]},{"fr":"Un boa c’est très dangereux, et un éléphant c’est très encombrant.","zh":"boa 很危险，而象又很大。","t":[7950,12025]},{"fr":"Chez moi c’est tout petit.","zh":"在我那里很小。","t":[12025,14150]},{"fr":"J’ai besoin d’un mouton.","zh":"我需要一只绵羊。","t":[14150,16300]},{"fr":"Dessine-moi un mouton.","zh":"画一只绵羊给我。","t":[16300,17513]}]},{"id":"ch02p14","audio":true,"sents":[{"fr":"Alors j’ai dessiné.","zh":"于是我画了。","t":[100,1237]}]},{"id":"ch02p15","audio":true,"sents":[{"fr":"Il regarda attentivement, puis :","zh":"他仔细地看了，然后说道：","t":[100,2687]}]},{"id":"ch02p16","audio":true,"sents":[{"fr":"— Non !","zh":"——不！","t":[100,3125]},{"fr":"Celui-là est déjà très malade.","zh":"那只已经病得很重了。","t":[3125,5775]},{"fr":"Fais-en un autre.","zh":"再画一个。","t":[5775,6750]}]},{"id":"ch02p17","audio":true,"sents":[{"fr":"Je dessinai :","zh":"我画了：","t":[100,1750]}]},{"id":"ch02p18","audio":true,"sents":[{"fr":"Mon ami sourit gentiment, avec indulgence :","zh":"我的朋友微笑着，带着宽容：","t":[100,3287]}]},{"id":"ch02p19","audio":true,"sents":[{"fr":"— Tu vois bien…","zh":"——你看清楚……","t":[100,2100]},{"fr":"ce n’est pas un mouton, c’est un bélier.","zh":"这不是绵羊，这是一只公羊。","t":[2100,4938]},{"fr":"Il a des cornes…","zh":"他长着角……","t":[4938,5837]}]},{"id":"ch02p20","audio":true,"sents":[{"fr":"Je refis donc encore mon dessin :","zh":"所以我再次重画了我的画：","t":[100,2600]}]},{"id":"ch02p21","audio":true,"sents":[{"fr":"Mais il fut refusé, comme les précédents :","zh":"但是它被拒绝了，就像之前的那些：","t":[100,3100]}]},{"id":"ch02p22","audio":true,"sents":[{"fr":"— Celui-là est trop vieux.","zh":"—— 这只太老了。","t":[100,3200]},{"fr":"Je veux un mouton qui vive longtemps.","zh":"我想找一只活很久的羊。","t":[3200,4974]}]},{"id":"ch02p23","audio":true,"sents":[{"fr":"Alors, faute de patience, comme j’avais hâte de commencer le démontage de mon moteur, je griffonnai ce dessin-ci.","zh":"然后，由于缺乏耐心，因为我急于开始拆卸我的发动机，我就草草地画了这张画。","t":[100,6788]}]},{"id":"ch02p24","audio":true,"sents":[{"fr":"Et je lançai :","zh":"于是我说：","t":[100,1687]}]},{"id":"ch02p25","audio":true,"sents":[{"fr":"— Ça c’est la caisse.","zh":"—— 这就是车身。","t":[100,3038]},{"fr":"Le mouton que tu veux est dedans.","zh":"你想要的羊就在里面。","t":[3038,4612]}]},{"id":"ch02p26","audio":true,"sents":[{"fr":"Mais je fus bien surpris de voir s’illuminer le visage de mon jeune juge :","zh":"但是看到我的年轻法官脸上露出惊讶的表情，我感到非常惊讶：","t":[100,4063]}]},{"id":"ch02p27","audio":true,"sents":[{"fr":"— C’est tout à fait comme ça que je le voulais !","zh":"— 这正是我想要的样子！","t":[100,4575]},{"fr":"Crois-tu qu’il faille beaucoup d’herbe à ce mouton ?","zh":"你认为这只羊需要很多草吗？","t":[4575,7512]}]},{"id":"ch02p28","audio":true,"sents":[{"fr":"— Pourquoi ?","zh":"— 为什么？","t":[100,2462]}]},{"id":"ch02p29","audio":true,"sents":[{"fr":"— Parce que chez moi c’est tout petit…","zh":"— 因为在我的星球上很小…","t":[100,2687]}]},{"id":"ch02p30","audio":true,"sents":[{"fr":"— Ça suffira sûrement.","zh":"— 那肯定足够了。","t":[100,3200]},{"fr":"Je t’ai donné un tout petit mouton.","zh":"我给了你一只小小的羊。","t":[3200,4975]}]},{"id":"ch02p31","audio":true,"sents":[{"fr":"Il pencha la tête vers le dessin :","zh":"他把头倾向图画：","t":[100,2538]}]},{"id":"ch02p32","audio":true,"sents":[{"fr":"— Pas si petit que ça…","zh":"— 不那么小…","t":[100,3025]},{"fr":"Tiens !","zh":"瞧！","t":[3025,5088]},{"fr":"Il s’est endormi…","zh":"他睡着了…","t":[5088,6150]}]},{"id":"ch02p33","audio":true,"sents":[{"fr":"Et c’est ainsi que je fis la connaissance du petit prince.","zh":"就这样，我认识了小王子。","t":[100,2750]}]},{"id":"ch02p34","audio":true,"sents":[]}]},{"id":"ch03","title_fr":"Chapitre III","title_zh":"第 3 章","paras":[{"id":"ch03p00","audio":true,"sents":[{"fr":"Il me fallut longtemps pour comprendre d’où il venait.","zh":"我花了很长时间才弄清楚他来自哪里。","t":[100,3325]},{"fr":"Le petit prince, qui me posait beaucoup de questions, ne semblait jamais entendre les miennes.","zh":"小王子不停地问我问题，却似乎从来不听我的。","t":[3325,8988]},{"fr":"Ce sont des mots prononcés par hasard qui, peu à peu, m’ont tout révélé.","zh":"是一些偶然说出的词，渐渐地向我揭示了所有的一切。","t":[8988,13850]},{"fr":"Ainsi, quand il aperçut pour la première fois mon avion (je ne dessinerai pas mon avion, c’est un dessin beaucoup trop compliqué pour moi) il me demanda :","zh":"因此，当他第一次看到我的飞机（我不会画我的飞机，对我来说这太复杂了）时，他问我：","t":[13850,22400]}]},{"id":"ch03p01","audio":true,"sents":[{"fr":"— Qu’est ce que c’est que cette chose-là ?","zh":"——这是什么？","t":[100,3388]}]},{"id":"ch03p02","audio":true,"sents":[{"fr":"— Ce n’est pas une chose.","zh":"——这不是东西。","t":[100,3150]},{"fr":"Ça vole.","zh":"它会飞。","t":[3150,4725]},{"fr":"C’est un avion.","zh":"这是一架飞机。","t":[4725,6488]},{"fr":"C’est mon avion.","zh":"这是我的飞机。","t":[6488,7388]}]},{"id":"ch03p03","audio":true,"sents":[{"fr":"Et j’étais fier de lui apprendre que je volais.","zh":"我自豪地教他我会飞。","t":[100,3100]},{"fr":"Alors il s’écria :","zh":"然后他大声说：","t":[3100,5050]}]},{"id":"ch03p04","audio":true,"sents":[{"fr":"— Comment !","zh":"—— 怎么！","t":[100,3238]},{"fr":"tu es tombé du ciel !","zh":"你是从天上掉下来的！","t":[3238,4988]}]},{"id":"ch03p05","audio":true,"sents":[{"fr":"— Oui, fis-je modestement.","zh":"—— 是的，我谦虚地回答。","t":[100,2750]}]},{"id":"ch03p06","audio":true,"sents":[{"fr":"— Ah !","zh":"—— 哎！","t":[100,3038]},{"fr":"ça c’est drôle…","zh":"这很有趣……","t":[3038,3974]}]},{"id":"ch03p07","audio":true,"sents":[{"fr":"Et le petit prince eut un très joli éclat de rire qui m’irrita beaucoup.","zh":"小王子露出一个很美的笑容，这让我非常恼火。","t":[100,4300]},{"fr":"Je désire que l’on prenne mes malheurs au sérieux.","zh":"我希望人们能认真对待我的不幸。","t":[4300,7450]},{"fr":"Puis il ajouta :","zh":"然后他又说：","t":[7450,9162]}]},{"id":"ch03p08","audio":true,"sents":[{"fr":"— Alors, toi aussi tu viens du ciel !","zh":"—— 那么，你也来自天空！","t":[100,4700]},{"fr":"De quelle planète es-tu ?","zh":"你来自哪个星球？","t":[4700,6524]}]},{"id":"ch03p09","audio":true,"sents":[{"fr":"J’entrevis aussitôt une lueur, dans le mystère de sa présence, et j’interrogeai brusquement :","zh":"我立刻在它的存在之谜中看到了一丝光芒，我突然问道：","t":[100,5812]}]},{"id":"ch03p10","audio":true,"sents":[{"fr":"— Tu viens donc d’une autre planète ?","zh":"—— 你是从另一个星球来的？","t":[100,3500]}]},{"id":"ch03p11","audio":true,"sents":[{"fr":"Mais il ne me répondit pas.","zh":"但他没有回答我。","t":[100,2200]},{"fr":"Il hochait la tête doucement tout en regardant mon avion :","zh":"他轻轻地点了点头，同时看着我的飞机：","t":[2200,5512]}]},{"id":"ch03p12","audio":true,"sents":[{"fr":"— C’est vrai que, là-dessus, tu ne peux pas venir de bien loin…","zh":"—— 的确，在这方面，你不可能来自太远的地方……","t":[100,4463]}]},{"id":"ch03p13","audio":true,"sents":[{"fr":"Et il s’enfonça dans une rêverie qui dura longtemps.","zh":"然后，他陷入了长时间的沉思。","t":[100,3350]},{"fr":"Puis, sortant mon mouton de sa poche, il se plongea dans la contemplation de son trésor.","zh":"接着，他从口袋里拿出我的羊，陷入了对他财宝的沉思。","t":[3350,8362]}]},{"id":"ch03p14","audio":true,"sents":[{"fr":"Vous imaginez combien j’avais pu être intrigué par cette demi-confidence sur \"les autres planètes\".","zh":"你想象一下，我对‘其他星球’这种半信半疑的态度有多么好奇。","t":[100,5950]},{"fr":"Je m’efforçai donc d’en savoir plus long :","zh":"所以我努力去了解更多：","t":[5950,8688]}]},{"id":"ch03p15","audio":true,"sents":[{"fr":"— D’où viens-tu mon petit bonhomme ?","zh":"——小家伙，你从哪里来？","t":[100,4162]},{"fr":"Où est-ce \"chez toi\" ?","zh":"‘在你那里’在哪里？","t":[4162,6775]},{"fr":"Où veux-tu emporter mon mouton ?","zh":"你想要把我这只羊带到哪里去？","t":[6775,8950]}]},{"id":"ch03p16","audio":true,"sents":[{"fr":"Il me répondit après un silence méditatif :","zh":"他沉思了一会儿后回答我：","t":[100,3138]}]},{"id":"ch03p17","audio":true,"sents":[{"fr":"— Ce qui est bien, avec la caisse que tu m’as donnée, c’est que, la nuit, ça lui servira de maison.","zh":"——有了你给我的那个箱子，晚上它就可以当房子了。","t":[100,6587]}]},{"id":"ch03p18","audio":true,"sents":[{"fr":"— Bien sûr.","zh":"——当然。","t":[100,2750]},{"fr":"Et si tu es gentil, je te donnerai aussi une corde pour l’attacher pendant le jour.","zh":"如果你对我好，我还会给你一根绳子，白天可以用来拴住它。","t":[2750,7788]},{"fr":"Et un piquet.","zh":"还有一根桩子。","t":[7788,8513]}]},{"id":"ch03p19","audio":true,"sents":[{"fr":"La proposition parut choquer le petit prince :","zh":"这个提议让小王子感到震惊：","t":[100,3063]}]},{"id":"ch03p20","audio":true,"sents":[{"fr":"— L’attacher ?","zh":"——把它绑起来？","t":[100,3462]},{"fr":"Quelle drôle d’idée !","zh":"多么奇怪的想法啊！","t":[3462,5200]}]},{"id":"ch03p21","audio":true,"sents":[{"fr":"— Mais si tu ne l’attaches pas, il ira n’importe où, et il se perdra…","zh":"——但是如果你不绑它，它会随便去哪里，然后就会迷路……","t":[100,4650]}]},{"id":"ch03p22","audio":true,"sents":[{"fr":"Et mon ami eut un nouvel éclat de rire :","zh":"我的朋友又大笑起来：","t":[100,2675]}]},{"id":"ch03p23","audio":true,"sents":[{"fr":"— Mais où veux-tu qu’il aille !","zh":"——但是你想让它去哪里呢！","t":[100,2937]}]},{"id":"ch03p24","audio":true,"sents":[{"fr":"— N’importe où.","zh":"——随便哪里。","t":[100,2775]},{"fr":"Droit devant lui…","zh":"正前方……","t":[2775,3763]}]},{"id":"ch03p25","audio":true,"sents":[{"fr":"Alors le petit prince remarqua gravement :","zh":"然后小王子严肃地注意到了：","t":[100,2838]}]},{"id":"ch03p26","audio":true,"sents":[{"fr":"— Ça ne fait rien, c’est tellement petit, chez moi !","zh":"——没关系，在我那里它太小了！","t":[100,4488]}]},{"id":"ch03p27","audio":true,"sents":[{"fr":"Et, avec un peu de mélancolie, peut-être, il ajouta :","zh":"而且，带着一丝忧郁，他可能又补充道：","t":[100,4088]}]},{"id":"ch03p28","audio":true,"sents":[{"fr":"Droit devant soi on ne peut pas aller bien loin…","zh":"正前方走不远……","t":[100,2250]}]},{"id":"ch03p29","audio":true,"sents":[]},{"id":"ch03p30","audio":true,"sents":[]}]},{"id":"ch04","title_fr":"Chapitre IV","title_zh":"第 4 章","paras":[{"id":"ch04p00","audio":true,"sents":[{"fr":"J’avais ainsi appris une seconde chose très importante : C’est que sa planète d’origine était à peine plus grande qu’une maison !","zh":"就这样，我又学到了一个非常重要的道理：那就是他的星球比一座房子大不了多少！","t":[100,7250]}]},{"id":"ch04p01","audio":true,"sents":[{"fr":"Ça ne pouvait pas m’étonner beaucoup.","zh":"这并不让我感到特别惊讶。","t":[100,2662]},{"fr":"Je savais bien qu’en dehors des grosses planètes comme la Terre, Jupiter, Mars, Vénus, auxquelles on a donné des noms, il y en a des centaines d’autres qui sont quelque-fois si petites qu’on a beaucoup de mal à les apercevoir au télescope.","zh":"我非常清楚，除了像地球、木星、火星、金星这样的大行星，还有成百上千的其他小行星，它们有时非常小，以至于在望远镜中很难看到。","t":[2662,15575]},{"fr":"Quand un astronome découvre l’une d’elles, il lui donne pour nom un numéro.","zh":"当一个天文学家发现其中一颗时，他会给它一个编号。","t":[15575,20338]},{"fr":"Il l’appelle par exemple : \"l’astéroïde 3251.\"","zh":"例如，他会称之为：'小行星3251'。","t":[20338,24713]}]},{"id":"ch04p02","audio":true,"sents":[{"fr":"J’ai de sérieuses raisons de croire que la planète d’où venait le petit prince est l’astéroïde B 612.","zh":"我有充分的理由相信，小王子的星球是B612号小行星。","t":[100,4638]},{"fr":"Cet astéroïde n’a été aperçu qu’une fois au télescope, en 1909, par un astronome turc.","zh":"这个星球只在1909年被一位土耳其天文学家用望远镜观测到。","t":[4638,12162]}]},{"id":"ch04p03","audio":true,"sents":[{"fr":"Il avait fait alors une grande démonstration de sa découverte à un Congrès International d’Astronomie.","zh":"当时他在国际天文学大会上对他的发现进行了大规模展示。","t":[100,6175]},{"fr":"Mais personne ne l’avait cru à cause de son costume.","zh":"但没有人相信他，因为他的服装。","t":[6175,9525]},{"fr":"Les grandes personnes sont comme ça.","zh":"大人就是这样。","t":[9525,11225]}]},{"id":"ch04p04","audio":true,"sents":[{"fr":"Heureusement pour la réputation de l’astéroïde B 612 un dictateur turc imposa à son peuple, sous peine de mort, de s’habiller à l’Européenne.","zh":"幸运的是，为了B 612星球的声誉，一位土耳其独裁者强迫他的民众，如果不穿欧洲服装就面临死刑。","t":[100,9550]},{"fr":"L’astronome refit sa démonstration en 1920, dans un habit très élégant.","zh":"这位天文学家在1920年再次进行了展示，穿着非常优雅。","t":[9550,14162]},{"fr":"Et cette fois-ci tout le monde fut de son avis.","zh":"这一次，所有人都同意了他的观点。","t":[14162,16400]}]},{"id":"ch04p05","audio":true,"sents":[{"fr":"Si je vous ai raconté ces détails sur l’astéroïde B 612 et si je vous ai confié son numéro, c’est à cause des grandes personnes.","zh":"如果我向您讲述了关于B 612星球的这些细节，并告诉了您它的编号，那是因为大人们。","t":[100,7838]},{"fr":"Les grandes personnes aiment les chiffres.","zh":"大人们喜欢数字。","t":[7838,10325]},{"fr":"Quand vous leur parlez d’un nouvel ami, elles ne vous questionnent jamais sur l’essentiel.","zh":"当您向他们介绍一个新朋友时，他们从不询问本质问题。","t":[10325,15112]},{"fr":"Elles ne vous disent jamais : \"Quel est le son de sa voix ?","zh":"她们从不会问你们：“他的声音是怎样的？”","t":[15112,19850]},{"fr":"Quels sont les jeux qu’il préfère ?","zh":"他最喜欢玩什么游戏？","t":[19850,22725]},{"fr":"Est-ce qu’il collectionne les papillons ?\" Elles vous demandent : \"Quel âge a-t-il ?","zh":"他是不是收集蝴蝶？她们会问你们：“他多大了？","t":[22725,29912]},{"fr":"Combien a-t-il de frères ?","zh":"他有多少个兄弟？","t":[29912,32612]},{"fr":"Combien pèse-t-il ?","zh":"他有多重？","t":[32612,34988]},{"fr":"Combien gagne son père ?\" Alors seulement elles croient le connaître.","zh":"他父亲赚多少钱？”只有在那时，她们才相信自己了解他。","t":[34988,40262]},{"fr":"Si vous dites aux grandes personnes : \"J’ai vu une belle maison en briques roses, avec des géraniums aux fenêtres et des colombes sur le toit…\" elles ne parviennent pas à s’imaginer cette maison.","zh":"如果你们对大人说：“我看见了一座粉红色的美丽房子，窗户上有天竺葵，屋顶上有鸽子……”他们无法想象这座房子。","t":[40262,51275]},{"fr":"Il faut leur dire : \"J’ai vu une maison de cent mille francs.\" Alors elles s’écrient : \"Comme c’est joli !\"","zh":"你们得这么说：“我看见了一座价值十万法郎的房子。”然后她们会惊呼：“多么漂亮啊！","t":[51275,59050]}]},{"id":"ch04p06","audio":true,"sents":[{"fr":"Ainsi, si vous leur dites : \"La preuve que le petit prince a existé c’est qu’il était ravissant, qu’il riait, et qu’il voulait un mouton.","zh":"因此，如果你们对她们说：“小王子存在的证据是他很可爱，他笑，他想要一只羊。","t":[100,8488]},{"fr":"Quand on veut un mouton, c’est la preuve qu’on existe\" elles hausseront les épaules et vous traiteront d’enfant !","zh":"当你们想要一只羊的时候，这就是你们存在的证据。”她们会耸耸肩，把你们当作孩子！","t":[8488,14612]},{"fr":"Mais si vous leur dites : \"La planète d’où il venait est l’astéroïde B 612\" alors elles seront convaincues, et elles vous laisseront tranquille avec leurs questions.","zh":"但如果你们对她们说：‘他来自的星球是B 612号小行星’那么她们就会相信，她们就会停止问你们问题。","t":[14612,23888]},{"fr":"Elles sont comme ça.","zh":"她们就是这样。","t":[23888,25725]},{"fr":"Il ne faut pas leur en vouloir.","zh":"我们不应该对她们生气。","t":[25725,28088]},{"fr":"Les enfants doivent être très indulgents envers les grandes personnes.","zh":"孩子们必须对大人们非常宽容。","t":[28088,31312]}]},{"id":"ch04p07","audio":true,"sents":[{"fr":"Mais, bien sûr, nous qui comprenons la vie, nous nous moquons bien des numéros !","zh":"但是，当然，我们这些理解生活的人，对那些数字根本不屑一顾！","t":[100,6125]},{"fr":"J’aurais aimé commencer cette histoire à la façon des contes de fées.","zh":"我本想以童话故事的方式开始这个故事。","t":[6125,10262]},{"fr":"J’aurais aimé dire :","zh":"我本想这么说：","t":[10262,11925]}]},{"id":"ch04p08","audio":true,"sents":[{"fr":"\"Il était une fois un petit prince qui habitait une planète à peine plus grande que lui, et qui avait besoin d’un ami…\" Pour ceux qui comprennent la vie, ça aurait eu l’air beaucoup plus vrai.","zh":"‘从前，有一个小王子，他住在一个比他稍大的星球上，他需要一个朋友……’对于理解生活的人来说，这会显得更加真实。","t":[100,9538]}]},{"id":"ch04p09","audio":true,"sents":[{"fr":"Car je n’aime pas qu’on lise mon livre à la légère.","zh":"因为我不喜欢人们轻率地阅读我的书。","t":[100,3375]},{"fr":"J’éprouve tant de chagrin à raconter ces souvenirs.","zh":"讲述这些回忆让我感到非常痛苦。","t":[3375,6925]},{"fr":"Il y a six ans déjà que mon ami s’en est allé avec son mouton.","zh":"六年前，我的朋友带着他的绵羊离开了。","t":[6925,10812]},{"fr":"Si j’essaie ici de le décrire, c’est afin de ne pas l’oublier.","zh":"如果我在这里尝试描述他，那是为了不忘记他。","t":[10812,15262]},{"fr":"C’est triste d’oublier un ami.","zh":"忘记一个朋友是件很伤心的事。","t":[15262,17562]},{"fr":"Tout le monde n’a pas eu un ami.","zh":"并不是每个人都曾有过朋友。","t":[17562,20050]},{"fr":"Et je puis devenir comme les grandes personnes qui ne s’intéressent plus qu’aux chiffres.","zh":"我可能会变成那些只对数字感兴趣的大人。","t":[20050,24525]},{"fr":"C’est donc pour ça encore que j’ai acheté une boîte de couleurs et des crayons.","zh":"所以，我仍然买了盒颜料和画笔。","t":[24525,29188]},{"fr":"C’est dur de se remettre au dessin, à mon âge, quand on n’a jamais fait d’autres tentatives que celle d’un boa fermé et celle d’un boa ouvert, à l’âge de six ans !","zh":"对我来说，重新开始画画很难，尤其是当我六岁时除了画一个闭着的蛇和一个张开的蛇之外，再也没有尝试过其他事情！","t":[29188,38762]},{"fr":"J’essaierai, bien sûr, de faire des portraits le plus ressemblants possible.","zh":"当然，我会尽力画得尽可能像。","t":[38762,43912]},{"fr":"Mais je ne suis pas tout à fait certain de réussir.","zh":"但我并不完全确定自己能成功。","t":[43912,47112]},{"fr":"Un dessin va, et l’autre ne ressemble plus.","zh":"一幅画完成了，另一幅却不再像了。","t":[47112,50375]},{"fr":"Je me trompe un peu aussi sur la taille.","zh":"我也有些搞错了尺寸。","t":[50375,53250]},{"fr":"Ici le petit prince est trop grand.","zh":"在这里，小王子太大了。","t":[53250,55738]},{"fr":"Là il est trop petit.","zh":"在那里，他又太小了。","t":[55738,57738]},{"fr":"J’hésite aussi sur la couleur de son costume.","zh":"我也在犹豫他的服装颜色。","t":[57738,60925]},{"fr":"Alors je tâtonne comme ci et comme ça, tant bien que mal.","zh":"所以我像这样、那样地摸索着，勉强应付。","t":[60925,64912]},{"fr":"Je me tromperai enfin sur certains détails plus importants.","zh":"最后，我也许会在一些更重要的细节上出错。","t":[64912,68650]},{"fr":"Mais ça, il faudra me le pardonner.","zh":"但是，这一点，请你们原谅我。","t":[68650,71588]},{"fr":"Mon ami ne donnait jamais d’explications.","zh":"我的朋友从不解释。","t":[71588,74588]},{"fr":"Il me croyait peut-être semblable à lui.","zh":"他可能认为我和他相似。","t":[74588,77588]},{"fr":"Mais moi, malheureusement, je ne sais pas voir les moutons à travers les caisses.","zh":"但不幸的是，我看不到箱子后面的羊。","t":[77588,82488]},{"fr":"Je suis peut-être un peu comme les grandes personnes.","zh":"我可能多少有点像大人。","t":[82488,85612]},{"fr":"J’ai dû vieillir.","zh":"我一定是变老了。","t":[85612,86674]}]},{"id":"ch04p10","audio":true,"sents":[]}]},{"id":"ch05","title_fr":"Chapitre V","title_zh":"第 5 章","paras":[{"id":"ch05p00","audio":true,"sents":[{"fr":"Chaque jour j’apprenais quelque chose sur la planète, sur le départ, sur le voyage.","zh":"每天我都在这个星球上、在出发、在旅途中学到一些东西。","t":[100,5562]},{"fr":"Ça venait tout doucement, au hasard des réflexions.","zh":"这一切都是偶然间，在思考中慢慢浮现。","t":[5562,9162]},{"fr":"C’est ainsi que, le troisième jour, je connus le drame des baobabs.","zh":"就这样，第三天，我了解了猴面包树的悲剧。","t":[9162,13026]}]},{"id":"ch05p01","audio":true,"sents":[{"fr":"Cette fois-ci encore ce fut grâce au mouton, car brusquement le petit prince m’interrogea, comme pris d’un doute grave :","zh":"这一次，又是羊帮了我，因为小王子突然严肃地问我：","t":[100,6563]}]},{"id":"ch05p02","audio":true,"sents":[{"fr":"— C’est bien vrai, n’est-ce pas, que les moutons mangent les arbustes ?","zh":"——是真的吗，不是吗，绵羊会吃灌木丛吗？","t":[100,5025]}]},{"id":"ch05p03","audio":true,"sents":[{"fr":"— Oui.","zh":"——是的。","t":[100,2400]},{"fr":"C’est vrai.","zh":"这是真的。","t":[2400,3000]}]},{"id":"ch05p04","audio":true,"sents":[{"fr":"— Ah !","zh":"啊！","t":[100,3038]},{"fr":"Je suis content.","zh":"我很高兴。","t":[3038,3938]}]},{"id":"ch05p05","audio":true,"sents":[{"fr":"Je ne compris pas pourquoi il était si important que les moutons mangeassent les arbustes.","zh":"我不明白为什么羊吃灌木丛这么重要。","t":[100,5062]},{"fr":"Mais le petit prince ajouta :","zh":"但小王子接着说：","t":[5062,7288]}]},{"id":"ch05p06","audio":true,"sents":[{"fr":"— Par conséquent ils mangent aussi les baobabs ?","zh":"那么他们也吃猴面包树吗？","t":[100,3850]}]},{"id":"ch05p07","audio":true,"sents":[{"fr":"Je fis remarquer au petit prince que les baobabs ne sont pas des arbustes, mais des arbres grand comme des églises et que, si même il emportait avec lui tout un troupeau d’éléphants, ce troupeau ne viendrait pas à bout d’un seul baobab.","zh":"我向小王子指出，猴面包树不是灌木，而是像教堂一样大的树，即使他带着一群大象，这群大象也吃不完一棵猴面包树。","t":[100,11200]}]},{"id":"ch05p08","audio":true,"sents":[{"fr":"L’idée du troupeau d’éléphants fit rire le petit prince :","zh":"大象群的想法让小王子笑了：","t":[100,3338]}]},{"id":"ch05p09","audio":true,"sents":[{"fr":"— Il faudrait les mettre les uns sur les autres…","zh":"得把它们一个堆在另一个上面……","t":[100,3013]}]},{"id":"ch05p10","audio":true,"sents":[{"fr":"Mais il remarqua avec sagesse :","zh":"但他明智地指出：","t":[100,2437]}]},{"id":"ch05p11","audio":true,"sents":[{"fr":"— Les baobabs, avant de grandir, ça commence par être petit.","zh":"猴面包树，在长得很大之前，都是从很小开始的。","t":[100,4837]}]},{"id":"ch05p12","audio":true,"sents":[{"fr":"— C’est exact !","zh":"这没错！","t":[100,3512]},{"fr":"Mais pourquoi veux-tu que tes moutons mangent les petits baobabs ?","zh":"但你为什么想让你的绵羊吃小猴面包树呢？","t":[3512,6974]}]},{"id":"ch05p13","audio":true,"sents":[{"fr":"Il me répondit : \"Ben !","zh":"他回答道：“嗯！”","t":[100,3875]},{"fr":"Voyons !\" comme s’il s’agissait là d’une évidence.","zh":"咱们看看吧！就像这是一件理所当然的事情。","t":[3875,8162]},{"fr":"Et il me fallut un grand effort d’intelligence pour comprendre à moi seul ce problème.","zh":"我必须付出极大的智力努力才能独自理解这个问题。","t":[8162,12213]}]},{"id":"ch05p14","audio":true,"sents":[{"fr":"Et en effet, sur la planète du petit prince, il y avait comme sur toutes les planètes, de bonnes herbes et de mauvaises herbes.","zh":"确实，在小王子的星球上，就像在所有星球上一样，有好的草和坏的草。","t":[100,7512]},{"fr":"Par conséquent de bonnes graines de bonnes herbes et de mauvaises graines de mauvaises herbes.","zh":"因此，好的草籽和坏的草籽。","t":[7512,12162]},{"fr":"Mais les graines sont invisibles.","zh":"但种子是看不见的。","t":[12162,14675]},{"fr":"Elles dorment dans le secret de la terre jusqu’à ce qu’il prenne fantaisie à l’une d’elles de se réveiller.","zh":"它们在土地的秘密中沉睡，直到其中一只突然想要醒来。","t":[14675,19900]},{"fr":"Alors elle s’étire, et pousse d’abord timidement vers le soleil une ravissante petite brindille inoffensive.","zh":"然后她伸展身体，首先胆怯地向太阳伸出一条迷人而无害的小枝条。","t":[19900,26212]},{"fr":"S’il s’agît d’une brindille de radis ou de rosier, on peut la laisser pousser comme elle veut.","zh":"无论是萝卜苗还是玫瑰苗，都可以任其生长。","t":[26212,61863]},{"fr":"Mais s’il s’agit d’une mauvaise plante, il faut arracher la plante aussitôt, dès qu’on a su la reconnaître.","zh":"但如果是一株坏苗，一旦认出就要立即拔除。","t":[61863,62363]},{"fr":"Or il y avait des graines terribles sur la planète du petit prince…","zh":"然而，小王子的星球上长满了可怕的种子……","t":[62363,62863]},{"fr":"c’étaient les graines de baobabs.","zh":"那是猴面包树的种子。","t":[62863,63363]},{"fr":"Le sol de la planète en était infesté.","zh":"整个星球都被它们侵占了。","t":[63363,63863]},{"fr":"Or un baobab, si l’on s’y prend trop tard, on ne peut jamais plus s’en débarrasser.","zh":"如果等到猴面包树长得太大，就再也除不掉了。","t":[63863,64363]},{"fr":"Il encombre toute la planète.","zh":"它占据了整个星球。","t":[64363,64863]},{"fr":"Il la perfore de ses racines.","zh":"它的根会穿透星球。","t":[64863,65363]},{"fr":"Et si la planète est trop petite, et si les baobabs sont trop nombreux, ils la font éclater.","zh":"如果星球太小，猴面包树又太多，它们就会把星球撑爆。","t":[65363,65863]}]},{"id":"ch05p15","audio":true,"sents":[{"fr":"\"C’est une question de discipline, me disait plus tard le petit prince.","zh":"‘这是一场纪律问题，小王子后来对我说。’","t":[100,4625]},{"fr":"Quand on a terminé sa toilette du matin, il faut faire soigneusement la toilette de la planète.","zh":"当完成早晨的梳洗后，必须仔细地清理星球。","t":[4625,10500]},{"fr":"Il faut s’astreindre régulièrement à arracher les baobabs dès qu’on les distingue d’avec les rosiers auxquels ils ressemblent beaucoup quand ils sont très jeunes.","zh":"必须定期拔除那些一旦与玫瑰区分开来就非常相似的猴面包树。","t":[10500,18362]},{"fr":"C’est un travail très ennuyeux, mais très facile.\"","zh":"这是一项非常无聊但非常容易的工作。","t":[18362,21100]}]},{"id":"ch05p16","audio":true,"sents":[{"fr":"Et un jour il me conseilla de m’appliquer à réussir un beau dessin, pour bien faire entrer ça dans la tête des enfants de chez moi.","zh":"有一天，他建议我努力画一幅漂亮的画，以便更好地让孩子们记住。","t":[100,7075]},{"fr":"\"S’ils voyagent un jour, me disait-il, ça pourra leur servir.","zh":"他说，如果他们有一天旅行，这会帮到他们。","t":[7075,11762]},{"fr":"Il est quelquefois sans inconvénient de remettre à plus tard son travail.","zh":"有时候推迟工作并无不便。","t":[11762,16062]},{"fr":"Mais, s’il s’agit des baobabs, c’est toujours une catastrophe.","zh":"但是，如果是猴面包树，那总是灾难。","t":[16062,20550]},{"fr":"J’ai connu une planète, habitée par un paresseux.","zh":"我认识一个住着懒汉的星球。","t":[20550,24062]},{"fr":"Il avait négligé trois arbustes…\"","zh":"他忽略了三棵灌木……","t":[24062,25825]}]},{"id":"ch05p17","audio":true,"sents":[{"fr":"Et, sur les indications du petit prince, j’ai dessiné cette planète-là.","zh":"根据小王子的指示，我画出了这个星球。","t":[100,4775]},{"fr":"Je n’aime guère prendre le ton d’un moraliste.","zh":"我不太喜欢摆出一副道德家的姿态。","t":[4775,7812]},{"fr":"Mais le danger des baobabs est si peu connu, et les risques courus par celui qui s’égarerait dans un astéroïde sont si considérables, que, pour une fois, je fais exception à ma réserve.","zh":"但是人们对猴面包树的危险知之甚少，而迷失在某个星球上的人所面临的风险如此之大，以至于这一次，我破例打破了我的谨慎。","t":[7812,18612]},{"fr":"Je dis : \"Enfants !","zh":"我说：“孩子们！”","t":[18612,22125]},{"fr":"Faites attention aux baobabs !\" C’est pour avertir mes amis d’un danger qu’ils frôlaient depuis longtemps, comme moi-même, sans le connaître, que j’ai tant travaillé ce dessin-là.","zh":"注意那些猴面包树！这是我为了提醒我的朋友们一个他们长期以来一直未知的危险，就像我自己一样，而费尽心思画这幅画的原因。","t":[22125,33025]},{"fr":"La leçon que je donnais en valait la peine.","zh":"我传授的教训是值得的。","t":[33025,35912]},{"fr":"Vous vous demanderez peut-être : Pourquoi n’y a-t-il pas, dans ce livre, d’autres dessins aussi grandioses que le dessin des baobabs ?","zh":"你们或许会问：为什么这本书里没有像猴面包树插画那样宏伟的图画呢？","t":[35912,44550]},{"fr":"La réponse est bien simple : J’ai essayé mais je n’ai pas pu réussir.","zh":"答案是简单的：我尝试了，但没有成功。","t":[44550,49688]},{"fr":"Quand j’ai dessiné les baobabs j’ai été animé par le sentiment de l’urgence.","zh":"当我画下猴面包树时，我感到一种紧迫感。","t":[49688,53475]}]},{"id":"ch05p18","audio":true,"sents":[]}]},{"id":"ch06","title_fr":"Chapitre VI","title_zh":"第 6 章","paras":[{"id":"ch06p00","audio":true,"sents":[{"fr":"Ah !","zh":"啊！","t":[100,2012]},{"fr":"petit prince, j’ai compris, peu à peu, ainsi, ta petite vie mélancolique.","zh":"小王子，我渐渐明白了，你的小小忧郁生活。","t":[2012,7712]},{"fr":"Tu n’avais eu longtemps pour distraction que la douceur des couchers de soleil.","zh":"你长久以来唯一的消遣就是欣赏日落的温柔。","t":[7712,12088]},{"fr":"J’ai appris ce détail nouveau, le quatrième jour au matin, quand tu m’as dit :","zh":"我在第四天早上，当你告诉我时，我得知了这个新细节：","t":[12088,16788]}]},{"id":"ch06p01","audio":true,"sents":[{"fr":"— J’aime bien les couchers de soleil.","zh":"——我喜欢日落。","t":[100,3738]},{"fr":"Allons voir un coucher de soleil…","zh":"我们去看看日落吧……","t":[3738,5387]}]},{"id":"ch06p02","audio":true,"sents":[{"fr":"— Mais il faut attendre…","zh":"——但是需要等待……","t":[100,2362]}]},{"id":"ch06p03","audio":true,"sents":[{"fr":"— Attendre quoi ?","zh":"——等待什么？","t":[100,2750]}]},{"id":"ch06p04","audio":true,"sents":[{"fr":"— Attendre que le soleil se couche.","zh":"——等待太阳落山。","t":[100,2987]}]},{"id":"ch06p05","audio":true,"sents":[{"fr":"Tu as eu l’air très surpris d’abord, et puis tu as ri de toi-même.","zh":"你一开始看起来非常惊讶，然后你对自己笑了。","t":[100,4325]},{"fr":"Et tu m’as dit :","zh":"然后你对我说：","t":[4325,5775]}]},{"id":"ch06p06","audio":true,"sents":[{"fr":"— Je me crois toujours chez moi !","zh":"我始终觉得自己在家！","t":[100,3212]}]},{"id":"ch06p07","audio":true,"sents":[{"fr":"En effet.","zh":"的确。","t":[100,1550]},{"fr":"Quand il est midi aux États-Unis, le soleil, tout le monde le sait, se couche sur la France.","zh":"当美国是中午的时候，众所周知，太阳会落在法国。","t":[1550,7600]},{"fr":"Il suffirait de pouvoir aller en France en une minute pour assister au coucher de soleil.","zh":"如果能够在一分钟内到达法国，就能看到日落了。","t":[7600,12838]},{"fr":"Malheureusement la France est bien trop éloignée.","zh":"不幸的是，法国太远了。","t":[12838,15975]},{"fr":"Mais, sur ta si petite planète, il te suffisait de tirer ta chaise de quelques pas.","zh":"但是，在你的那个小小的星球上，你只需要把椅子拉远几步。","t":[15975,21350]},{"fr":"Et tu regardais le crépuscule chaque fois que tu le désirais…","zh":"而且，你每次想看黄昏的时候就可以看……","t":[21350,24200]}]},{"id":"ch06p08","audio":true,"sents":[{"fr":"— Un jour, j’ai vu le soleil se coucher quarante-trois fois !","zh":"有一天，我看到太阳落下了四十三次！","t":[100,4750]}]},{"id":"ch06p09","audio":true,"sents":[{"fr":"Et un peu plus tard tu ajoutais :","zh":"过了一会儿，你又补充说：","t":[100,2400]}]},{"id":"ch06p10","audio":true,"sents":[{"fr":"— Tu sais…","zh":"你知道……","t":[100,1888]},{"fr":"quand on est tellement triste on aime les couchers de soleil…","zh":"当一个人非常伤心的时候，他会爱上日落……","t":[1888,4325]}]},{"id":"ch06p11","audio":true,"sents":[{"fr":"Le jour des quarante-trois fois tu étais donc tellement triste ?","zh":"在四十三次的日子，你难道不是非常伤心吗？","t":[100,4400]},{"fr":"Mais le petit prince ne répondit pas.","zh":"但小王子没有回答。","t":[4400,6162]}]},{"id":"ch06p12","audio":true,"sents":[]}]},{"id":"ch07","title_fr":"Chapitre VII","title_zh":"第 7 章","paras":[{"id":"ch07p00","audio":true,"sents":[{"fr":"Le cinquième jour, toujours grâce au mouton, ce secret de la vie du petit prince me fut révélé.","zh":"第五天，多亏了绵羊，小王子的生活秘密被我揭露了。","t":[100,6162]},{"fr":"Il me demanda avec brusquerie, sans préambule, comme le fruit d’un problème longtemps médité en silence :","zh":"他粗暴地问我，没有前言，就像是对一个长时间默默思考的问题的回答：","t":[6162,12300]}]},{"id":"ch07p01","audio":true,"sents":[{"fr":"— Un mouton, s’il mange les arbustes, il mange aussi les fleurs ?","zh":"—— 一只绵羊，如果它吃灌木，它也会吃花朵吗？","t":[100,5113]}]},{"id":"ch07p02","audio":true,"sents":[{"fr":"— Un mouton mange tout ce qu’il rencontre.","zh":"—— 绵羊吃它遇到的一切。","t":[100,3126]}]},{"id":"ch07p03","audio":true,"sents":[{"fr":"— Même les fleurs qui ont des épines ?","zh":"—— 即使是有刺的花朵呢？","t":[100,3350]}]},{"id":"ch07p04","audio":true,"sents":[{"fr":"— Oui.","zh":"—— 是的。","t":[100,2400]},{"fr":"Même les fleurs qui ont des épines.","zh":"即使是有刺的花朵。","t":[2400,4050]}]},{"id":"ch07p05","audio":true,"sents":[{"fr":"— Alors les épines, à quoi servent-elles ?","zh":"那么，刺有什么用呢？","t":[100,3800]}]},{"id":"ch07p06","audio":true,"sents":[{"fr":"Je ne le savais pas.","zh":"我不知道。","t":[100,1962]},{"fr":"J’étais alors très occupé à essayer de dévisser un boulon trop serré de mon moteur.","zh":"我当时正忙于试图拧下发动机上太紧的螺栓。","t":[1962,7075]},{"fr":"J’étais très soucieux car ma panne commençait de m’apparaître comme très grave, et l’eau à boire qui s’épuisait me faisait craindre le pire.","zh":"我非常担心，因为我的故障开始显得非常严重，而且饮用水即将用完，这让我害怕最坏的情况。","t":[7075,13762]}]},{"id":"ch07p07","audio":true,"sents":[{"fr":"— Les épines, à quoi servent-elles ?","zh":"那么，刺有什么用呢？","t":[100,3538]}]},{"id":"ch07p08","audio":true,"sents":[{"fr":"Le petit prince ne renonçait jamais à une question, une fois qu’il l’avait posée.","zh":"小王子一旦提出一个问题，就绝不会放弃。","t":[100,4950]},{"fr":"J’étais irrité par mon boulon et je répondis n’importe quoi :","zh":"我对我的螺栓感到恼火，随便回答道：","t":[4950,8800]}]},{"id":"ch07p09","audio":true,"sents":[{"fr":"— Les épines, ça ne sert à rien, c’est de la pure méchanceté de la part des fleurs !","zh":"刺没有什么用，这是花朵的纯粹恶意！","t":[100,5975]}]},{"id":"ch07p10","audio":true,"sents":[{"fr":"— Oh !","zh":"哦！","t":[100,2176]}]},{"id":"ch07p11","audio":true,"sents":[{"fr":"Mais après un silence il me lança, avec une sorte de rancune :","zh":"但沉默了一会儿后，他带着一种怨恨对我说：","t":[100,4063]}]},{"id":"ch07p12","audio":true,"sents":[{"fr":"— Je ne te crois pas !","zh":"—— 我不相信你！","t":[100,3625]},{"fr":"Les fleurs sont faibles.","zh":"花儿是脆弱的。","t":[3625,5725]},{"fr":"Elles sont naïves.","zh":"她们是天真的。","t":[5725,7462]},{"fr":"Elles se rassurent comme elles peuvent.","zh":"她们尽力安慰自己。","t":[7462,9875]},{"fr":"Elles se croient terribles avec leurs épines…","zh":"她们以为自己有了刺就了不起……","t":[9875,11875]}]},{"id":"ch07p13","audio":true,"sents":[{"fr":"Je ne répondis rien.","zh":"我没有回答。","t":[100,2225]},{"fr":"A cet instant-là je me disais : \"Si ce boulon résiste encore, je le ferai sauter d’un coup de marteau.\" Le petit prince dérangea de nouveau mes réflexions :","zh":"就在这时，我想：'如果这个螺栓还能坚持，我就用锤子一下把它敲下来。' 小王子又打断了我的思考：","t":[2225,12438]}]},{"id":"ch07p14","audio":true,"sents":[{"fr":"— Et tu crois, toi, que les fleurs…","zh":"—— 你也认为花儿……","t":[100,3187]}]},{"id":"ch07p15","audio":true,"sents":[{"fr":"— Mais non !","zh":"—— 但不！","t":[100,3200]},{"fr":"Mais non !","zh":"但是不！","t":[3200,5312]},{"fr":"Je ne crois rien !","zh":"我什么都不信！","t":[5312,7900]},{"fr":"J’ai répondu n’importe quoi.","zh":"我随便回答了。","t":[7900,10362]},{"fr":"Je m’occupe, moi, de choses sérieuses !","zh":"我负责的是严肃的事情！","t":[10362,13476]}]},{"id":"ch07p16","audio":true,"sents":[{"fr":"Il me regarda stupéfiait.","zh":"他惊讶地看着我。","t":[100,1600]}]},{"id":"ch07p17","audio":true,"sents":[{"fr":"— De choses sérieuses !","zh":"——严肃的事情！","t":[100,2826]}]},{"id":"ch07p18","audio":true,"sents":[{"fr":"Il me voyait, mon marteau à la main, et les doigts noirs de cambouis, penché sur un objet qui lui semblait très laid.","zh":"他看到我手里拿着锤子，手指沾满了油污，弯腰看着一个在他看来非常丑陋的东西。","t":[100,6000]}]},{"id":"ch07p19","audio":true,"sents":[{"fr":"— Tu parles comme les grandes personnes !","zh":"——你说话像大人一样！","t":[100,3375]}]},{"id":"ch07p20","audio":true,"sents":[{"fr":"Ça me fit un peu honte.","zh":"这让我有点儿不好意思。","t":[100,2250]},{"fr":"Mais, impitoyable, il ajouta :","zh":"但是，无情地，他又补充说：","t":[2250,5250]}]},{"id":"ch07p21","audio":true,"sents":[{"fr":"— Tu confonds tout…","zh":"你把一切都搞混了……","t":[100,2162]},{"fr":"tu mélanges tout !","zh":"你把一切都混在一起！","t":[2162,3675]}]},{"id":"ch07p22","audio":true,"sents":[{"fr":"Il était vraiment très irrité.","zh":"他真的很生气。","t":[100,2550]},{"fr":"Il secouait au vent des cheveux tout dorés :","zh":"他随风摇动着金黄色的头发：","t":[2550,5162]}]},{"id":"ch07p23","audio":true,"sents":[{"fr":"— Je connais une planète où il y a un Monsieur cramoisi.","zh":"——我知道一个有红先生居住的星球。","t":[100,4450]},{"fr":"Il n’a jamais respiré une fleur.","zh":"他从未呼吸过一朵花。","t":[4450,7125]},{"fr":"Il n’a jamais regardé une étoile.","zh":"他从未看过一颗星星。","t":[7125,9838]},{"fr":"Il n’a jamais aimé personne.","zh":"他从未爱过任何人。","t":[9838,12225]},{"fr":"Il n’a jamais rien fait d’autre que des additions.","zh":"他从未做过除了加法以外的事情。","t":[12225,15325]},{"fr":"Et toute la journée il répète comme toi : \"Je suis un homme sérieux !","zh":"而且一整天他都像你一样重复着：'我是一个严肃的人！'","t":[15325,20938]},{"fr":"Je suis un homme sérieux !\" et ça le fait gonfler d’orgueil.","zh":"“我是一个严肃的人！”这话让他很自豪。","t":[20938,25638]},{"fr":"Mais ce n’est pas un homme, c’est un champignon !","zh":"但这不是人，而是一朵蘑菇！","t":[25638,28562]}]},{"id":"ch07p24","audio":true,"sents":[{"fr":"— Un quoi ?","zh":"一个什么？","t":[100,2412]}]},{"id":"ch07p25","audio":true,"sents":[{"fr":"— Un champignon !","zh":"一个蘑菇！","t":[100,2687]}]},{"id":"ch07p26","audio":true,"sents":[{"fr":"Le petit prince était maintenant tout pâle de colère.","zh":"小王子现在气得脸色苍白。","t":[100,2662]}]},{"id":"ch07p27","audio":true,"sents":[{"fr":"— Il y a des millions d’années que les fleurs fabriquent des épines.","zh":"数百万年来，花朵在制造荆棘。","t":[100,4625]},{"fr":"Il y a des millions d’années que les moutons mangent quand même les fleurs.","zh":"数百万年来，羊还是照样吃花。","t":[4625,8500]},{"fr":"Et ce n’est pas sérieux de chercher à comprendre pourquoi elles se donnent tant de mal pour se fabriquer des épines qui ne servent jamais à rien ?","zh":"这不是认真，试图理解她们为什么费那么大劲去制造那些永远派不上用场的刺？","t":[8500,16288]},{"fr":"Ce n’est pas important la guerre des moutons et des fleurs ?","zh":"这不重要，羊和花之间的战争？","t":[16288,20250]},{"fr":"Ce n’est pas plus sérieux et plus important que les additions d’un gros Monsieur rouge ?","zh":"这难道不比一个红脸大汉的加减法更严肃、更重要吗？","t":[20250,25388]},{"fr":"Et si je connais, moi, une fleur unique au monde, qui n’existe nulle part, sauf dans ma planète, et qu’un petit mouton peut anéantir d’un seul coup, comme ça, un matin, sans se rendre compte de ce qu’il fait, ce n’est pas important ça !","zh":"如果我知道，我认识一朵世界上独一无二的花，它只存在于我的星球上，而一只小绵羊可以一眨眼间将它毁灭，就像这样，一个早晨，没有意识到自己在做什么，这并不重要！","t":[25388,38912]}]},{"id":"ch07p28","audio":true,"sents":[{"fr":"Il rougit, puis reprit :","zh":"他脸红了，然后又说：","t":[100,2262]}]},{"id":"ch07p29","audio":true,"sents":[{"fr":"— Si quelqu’un aime une fleur qui n’existe qu’à un exemplaire dans les millions et les millions d’étoiles, ça suffit pour qu’il soit heureux quand il les regarde.","zh":"——如果有人爱上一朵只存在于亿万星辰中的一朵花，那么当他仰望星空时，他就感到幸福。","t":[100,9375]},{"fr":"Il se dit : \"Ma fleur est là quelque part…\" Mais si le mouton mange la fleur, c’est pour lui comme si, brusquement, toutes les étoiles s’éteignaient !","zh":"他想：'我的花在某处……'但如果绵羊吃掉了我的花，那么对他来说，就像突然间所有的星星都熄灭了！","t":[9375,19975]},{"fr":"Et ce n’est pas important ça !","zh":"这并不重要！","t":[19975,21937]}]},{"id":"ch07p30","audio":true,"sents":[{"fr":"Il ne put rien dire de plus.","zh":"他无法再说更多。","t":[100,2275]},{"fr":"Il éclata brusquement en sanglots.","zh":"他突然放声大哭。","t":[2275,4962]},{"fr":"La nuit était tombée.","zh":"夜幕降临。","t":[4962,6950]},{"fr":"J’avais lâché mes outils.","zh":"我扔掉了我的工具。","t":[6950,9188]},{"fr":"Je me moquais bien de mon marteau, de mon boulon, de la soif et de la mort.","zh":"我对我的锤子、螺栓、口渴和死亡一笑了之。","t":[9188,14162]},{"fr":"Il y avait, sur une étoile, une planète, la mienne, la Terre, un petit prince à consoler !","zh":"在一颗星星上，有一个星球，我的星球，地球，有一个小王子需要安慰！","t":[14162,21125]},{"fr":"Je le pris dans les bras.","zh":"我把他抱在怀里。","t":[21125,23112]},{"fr":"Je le berçai.","zh":"我轻轻地摇晃他。","t":[23112,24900]},{"fr":"Je lui disais : \"La fleur que tu aimes n’est pas en danger…","zh":"我对他说：\"你爱的那朵花没有危险...","t":[24900,29288]},{"fr":"Je lui dessinerai une muselière, à ton mouton…","zh":"我会给你画一个口套，给你的羊...","t":[29288,32888]},{"fr":"Je te dessinerai une armure pour ta fleur…","zh":"我会给你画一套盔甲，保护你的花...","t":[32888,36075]},{"fr":"Je…\" Je ne savais pas trop quoi dire.","zh":"我……我不知道该说什么。","t":[36075,39838]},{"fr":"Je me sentais très maladroit.","zh":"我觉得自己非常笨拙。","t":[39838,42275]},{"fr":"Je ne savais comment l’atteindre, où le rejoindre…","zh":"我不知道怎么接近他，怎么找到他……","t":[42275,45675]},{"fr":"C’est tellement mystérieux, le pays des larmes.","zh":"泪水之国是如此神秘。","t":[45675,48212]}]}]},{"id":"ch08","title_fr":"Chapitre VIII","title_zh":"第 8 章","paras":[{"id":"ch08p00","audio":true,"sents":[{"fr":"J’appris bien vite à mieux connaître cette fleur.","zh":"我很快就学会了更好地了解这朵花。","t":[100,3400]},{"fr":"Il y avait toujours eu, sur la planète du petit prince, des fleurs très simples, ornées d’un seul rang de pétales, et qui ne tenaient point de place, et qui ne dérangeaient personne.","zh":"小王子的星球上曾经有过一些非常简单的花，它们只有一层花瓣，不占地方，也不打扰任何人。","t":[3400,13575]},{"fr":"Elles apparaissaient un matin dans l’herbe, et puis elles s’éteignaient le soir.","zh":"它们在一个清晨出现在草地上，然后在夜晚凋谢。","t":[13575,17988]},{"fr":"Mais celle-là avait germé un jour, d’une graine apportée d’on ne sait où, et le petit prince avait surveillé de très près cette brindille qui ne ressemblait pas aux autres brindilles.","zh":"但是这朵花有一天从不知名的地方的一粒种子中发芽了，小王子非常仔细地观察着这根与众不同的嫩芽。","t":[17988,27038]},{"fr":"Ça pouvait être un nouveau genre de baobab.","zh":"这可能是一种新的猴面包树。","t":[27038,30038]},{"fr":"Mais l’arbuste cessa vite de croître, et commença de préparer une fleur.","zh":"但是这棵灌木很快停止了生长，开始准备开花。","t":[30038,34938]},{"fr":"Le petit prince, qui assistait à l’installation d’un bouton énorme, sentait bien qu’il en sortirait une apparition miraculeuse, mais la fleur n’en finissait pas de se préparer à être belle, à l’abri de sa chambre verte.","zh":"小王子看着那巨大的花蕾的安装，很清楚这将是一个奇迹般的出现，但是这朵花一直在它的绿色房间里准备着，让自己变得美丽。","t":[34938,47300]},{"fr":"Elle choisissait avec soin ses couleurs.","zh":"它精心地挑选着颜色。","t":[47300,50262]},{"fr":"Elle s’habillait lentement, elle ajustait un à un ses pétales.","zh":"它慢慢地穿上衣服，一瓣一瓣地调整。","t":[50262,54188]},{"fr":"Elle ne voulait pas sortir toute fripée comme les coquelicots.","zh":"它不想像向日葵那样蓬松地出场。","t":[54188,57838]},{"fr":"Elle ne voulait apparaître que dans le plein rayonnement de sa beauté.","zh":"她只想在美丽的光辉中显现。","t":[57838,61762]},{"fr":"Eh !","zh":"Eh !","t":[61762,63650]},{"fr":"oui.","zh":"是的。","t":[63650,64912]},{"fr":"Elle était très coquette !","zh":"她非常爱美！","t":[64912,67488]},{"fr":"Sa toilette mystérieuse avait donc duré des jours et des jours.","zh":"她的神秘打扮持续了好多天。","t":[67488,71625]},{"fr":"Et puis voici qu’un matin, justement à l’heure du lever du soleil, elle s’était montrée.","zh":"然后，就在一个清晨，正好是日出时分，她出现了。","t":[71625,76237]}]},{"id":"ch08p01","audio":true,"sents":[{"fr":"Et elle, qui avait travaillé avec tant de précision, dit en bâillant :","zh":"她，尽管工作得非常精确，一边打着哈欠说：","t":[100,4413]}]},{"id":"ch08p02","audio":true,"sents":[{"fr":"— Ah !","zh":"—— 啊！","t":[100,3038]},{"fr":"Je me réveille à peine…","zh":"我刚刚醒来……","t":[3038,5200]},{"fr":"Je vous demande pardon…","zh":"请原谅我……","t":[5200,7300]},{"fr":"Je suis encore toute décoiffée…","zh":"我仍然有点儿头发散乱……","t":[7300,8950]}]},{"id":"ch08p03","audio":true,"sents":[{"fr":"Le petit prince, alors, ne put contenir son admiration :","zh":"小王子，他禁不住赞叹道：","t":[100,4488]}]},{"id":"ch08p04","audio":true,"sents":[{"fr":"— Que vous êtes belle !","zh":"—— 你真美！","t":[100,2638]}]},{"id":"ch08p05","audio":true,"sents":[{"fr":"— N’est-ce pas, répondit doucement la fleur.","zh":"—— 是的，花儿轻声回答。","t":[100,4350]},{"fr":"Et je suis née en même temps que le soleil…","zh":"我和太阳同时出生……","t":[4350,6225]}]},{"id":"ch08p06","audio":true,"sents":[{"fr":"Le petit prince devina bien qu’elle n’était pas trop modeste, mais elle était si émouvante !","zh":"小王子很快就猜到她并不太谦虚，但她却如此感人！","t":[100,4937]}]},{"id":"ch08p07","audio":true,"sents":[{"fr":"— C’est l’heure, je crois, du petit déjeuner, avait-elle bientôt ajouté, auriez-vous la bonté de penser à moi…","zh":"—— 我想这是吃早餐的时间了，她很快又补充道，你愿意为我着想吗……","t":[100,7313]}]},{"id":"ch08p08","audio":true,"sents":[{"fr":"Et le petit prince, tout confus, ayant été chercher un arrosoir d’eau fraîche, avait servi la fleur.","zh":"小王子感到非常尴尬，他去找了一壶凉水，然后为花儿服务。","t":[100,5774]}]},{"id":"ch08p09","audio":true,"sents":[{"fr":"Ainsi l’avait-elle bien vite tourmenté par sa vanité un peu ombrageuse.","zh":"就这样，她很快地通过她那有点儿阴郁的虚荣心折磨了她。","t":[100,4450]},{"fr":"Un jour, par exemple, parlant de ses quatre épines, elle avait dit au petit prince :","zh":"有一天，比如，她向小王子提起她的四根刺，她说：","t":[4450,9674]}]},{"id":"ch08p10","audio":true,"sents":[{"fr":"— Ils peuvent venir, les tigres, avec leurs griffes !","zh":"他们可以带着他们的爪子来！","t":[100,4500]}]},{"id":"ch08p11","audio":true,"sents":[{"fr":"— Il n’y a pas de tigres sur ma planète, avait objecté le petit prince, et puis les tigres ne mangent pas l’herbe.","zh":"我的星球上没有老虎，小王子反驳道，而且老虎不吃草。","t":[100,6713]}]},{"id":"ch08p12","audio":true,"sents":[{"fr":"— Je ne suis pas une herbe, avait doucement répondu la fleur.","zh":"我不是草，花儿轻声回答。","t":[100,4237]}]},{"id":"ch08p13","audio":true,"sents":[{"fr":"— Pardonnez-moi…","zh":"请原谅……","t":[100,1963]}]},{"id":"ch08p14","audio":true,"sents":[{"fr":"— Je ne crains rien des tigres, mais j’ai horreur des courants d’air.","zh":"我不怕老虎，但我讨厌风。","t":[100,5250]},{"fr":"Vous n’auriez pas un paravent ?","zh":"您有没有一把屏风？","t":[5250,7338]}]},{"id":"ch08p15","audio":true,"sents":[{"fr":"\"Horreur des courants d’air…","zh":"讨厌风……","t":[100,1525]},{"fr":"ce n’est pas de chance, pour une plante, avait remarqué le petit prince.","zh":"对一个植物来说，这不是运气，小王子评论道。","t":[1525,6362]},{"fr":"Cette fleur est bien compliquée…\"","zh":"这朵花太复杂了……","t":[6362,7975]}]},{"id":"ch08p16","audio":true,"sents":[{"fr":"— Le soir vous me mettrez sous globe.","zh":"晚上您会把我放在灯笼下。","t":[100,3738]},{"fr":"Il fait très froid chez vous.","zh":"你们那里非常冷。","t":[3738,5788]},{"fr":"C’est mal installé.","zh":"安装得不好。","t":[5788,7712]},{"fr":"Là d’où je viens…","zh":"我从哪里来……","t":[7712,8650]}]},{"id":"ch08p17","audio":true,"sents":[{"fr":"Mais elle s’était interrompue.","zh":"但是它被打断了。","t":[100,2325]},{"fr":"Elle était venue sous forme de graine.","zh":"它是以种子的形式来的。","t":[2325,4975]},{"fr":"Elle n’avait rien pu connaître des autres mondes.","zh":"它无法了解其他的世界。","t":[4975,8075]},{"fr":"Humiliée de s’être laissé surprendre à préparer un mensonge aussi naïf, elle avait toussé deux ou trois fois, pour mettre le petit prince dans son tort :","zh":"因为被自己被欺骗地准备了一个如此天真的谎言而感到羞愧，它咳嗽了两三次，为了让小王子处于错误之中：","t":[8075,15888]}]},{"id":"ch08p18","audio":true,"sents":[{"fr":"— Ce paravent ?…","zh":"——那扇屏风？……","t":[100,2563]}]},{"id":"ch08p19","audio":true,"sents":[{"fr":"— J’allais le chercher mais vous me parliez !","zh":"——我正要去拿，但是你和我说话了！","t":[100,3663]}]},{"id":"ch08p20","audio":true,"sents":[{"fr":"Alors elle avait forcé sa toux pour lui infliger quand même des remords.","zh":"然后它强迫自己咳嗽，以便至少让他感到内疚。","t":[100,3337]}]},{"id":"ch08p21","audio":true,"sents":[{"fr":"Ainsi le petit prince, malgré la bonne volonté de son amour, avait vite douté d’elle.","zh":"小王子，尽管他的爱情充满善意，但很快就开始怀疑她了。","t":[100,5888]},{"fr":"Il avait pris au sérieux des mots sans importance, et était devenu très malheureux.","zh":"他认真地对待了一些无关紧要的话，结果变得非常不幸。","t":[5888,9962]}]},{"id":"ch08p22","audio":true,"sents":[{"fr":"\"J’aurais dû ne pas l’écouter, me confia-t-il un jour, il ne faut jamais écouter les fleurs.","zh":"有一天，他向我透露，‘我本不该听信她们的话，永远不要听信花朵的话。’","t":[100,5812]},{"fr":"Il faut les regarder et les respirer.","zh":"你必须注视她们，呼吸她们的气息。","t":[5812,8562]},{"fr":"La mienne embaumait ma planète, mais je ne savais pas m’en réjouir.","zh":"我的玫瑰使我的星球变得香气四溢，但我却不知道该为此感到高兴。","t":[8562,12888]},{"fr":"Cette histoire de griffes, qui m’avait tellement agacé, eût dû m’attendrir…\"","zh":"关于爪子的事，虽然让我很烦恼，本该让我感到同情……","t":[12888,16912]}]},{"id":"ch08p23","audio":true,"sents":[{"fr":"Il me confia encore :","zh":"他又向我透露：","t":[100,1962]}]},{"id":"ch08p24","audio":true,"sents":[{"fr":"\"Je n’ai alors rien su comprendre !","zh":"那时，我什么也不懂！","t":[100,3288]},{"fr":"J’aurais dû la juger sur les actes et non sur les mots.","zh":"我本该根据她的行为而非言语来评判她。","t":[3288,6612]},{"fr":"Elle m’embaumait et m’éclairait.","zh":"她既为我防腐又为我照亮了道路。","t":[6612,8862]},{"fr":"Je n’aurais jamais dû m’enfuir !","zh":"我本不该逃跑！","t":[8862,11825]},{"fr":"J’aurais dû deviner sa tendresse derrière ses pauvres ruses.","zh":"我应该能猜出她那可怜的诡计背后的温柔。","t":[11825,15562]},{"fr":"Les fleurs sont si contradictoires !","zh":"花朵是多么矛盾！","t":[15562,18775]},{"fr":"Mais j’étais trop jeune pour savoir l’aimer.\"","zh":"但我当时太年轻，不知道去爱她。","t":[18775,20712]}]},{"id":"ch08p25","audio":true,"sents":[]},{"id":"ch08p26","audio":true,"sents":[]}]},{"id":"ch09","title_fr":"Chapitre IX","title_zh":"第 9 章","paras":[{"id":"ch09p00","audio":true,"sents":[{"fr":"Je crois qu’il profita, pour son évasion, d’une migration d’oiseaux sauvages.","zh":"我相信他利用一群野鸟的迁徙来逃脱。","t":[100,5275]},{"fr":"Au matin du départ il mit sa planète bien en ordre.","zh":"出发的那天早上，他把他的星球整理得井井有条。","t":[5275,8788]},{"fr":"Il ramona soigneusement ses volcans en activité.","zh":"他仔细地清理了那些活火山。","t":[8788,12388]},{"fr":"Il possédait deux volcans en activité.","zh":"他拥有两个活火山。","t":[12388,15375]},{"fr":"Et c’était bien commode pour faire chauffer le petit déjeuner du matin.","zh":"这对加热早上的早餐来说非常方便。","t":[15375,19450]},{"fr":"Il possédait aussi un volcan éteint.","zh":"他还拥有一座熄灭的火山。","t":[19450,22275]},{"fr":"Mais, comme il disait, \"On ne sait jamais !\" Il ramona donc également le volcan éteint.","zh":"但是，正如他所说，'永远不知道！' 因此，他也清理了那座熄灭的火山。","t":[22275,29275]},{"fr":"S’ils sont bien ramonés, les volcans brûlent doucement et régulièrement, sans éruptions.","zh":"如果清理得当，火山会慢慢、规律地燃烧，不会发生喷发。","t":[29275,34738]},{"fr":"Les éruptions volcaniques sont comme des feux de cheminée.","zh":"火山喷发就像壁炉里的火。","t":[34738,38525]},{"fr":"Évidemment sur notre terre nous sommes beaucoup trop petits pour ramoner nos volcans.","zh":"显然，在我们的地球上，我们太小了，无法清理我们的火山。","t":[38525,43138]},{"fr":"C’est pourquoi ils nous causent des tas d’ennuis.","zh":"这就是为什么它们给我们带来了很多麻烦。","t":[43138,45250]}]},{"id":"ch09p01","audio":true,"sents":[{"fr":"Le petit prince arracha aussi, avec un peu de mélancolie, les dernières pousses de baobabs.","zh":"小王子也带着一丝忧郁地拔掉了最后几株猴面包树的幼苗。","t":[100,6162]},{"fr":"Il croyait ne jamais devoir revenir.","zh":"他相信自己永远不会回来。","t":[6162,9050]},{"fr":"Mais tous ces travaux familiers lui parurent, ce matin-là, extrêmement doux.","zh":"但那天早上，所有这些熟悉的劳作在他看来都变得极其甜蜜。","t":[9050,13875]},{"fr":"Et, quand il arrosa une dernière fois la fleur, et se prépara à la mettre à l’abri sous son globe, il se découvrit l’envie de pleurer.","zh":"当他最后一次给花儿浇水，准备把它放在他的玻璃罩下保护起来时，他发现自己想要哭泣。","t":[13875,20913]}]},{"id":"ch09p02","audio":true,"sents":[{"fr":"— Adieu, dit-il à la fleur.","zh":"——再见，他对花儿说。","t":[100,2875]}]},{"id":"ch09p03","audio":true,"sents":[{"fr":"Mais elle ne lui répondit pas.","zh":"但她没有回答他。","t":[100,1450]}]},{"id":"ch09p04","audio":true,"sents":[{"fr":"— Adieu, répéta-t-il.","zh":"——再见，他重复道。","t":[100,2762]}]},{"id":"ch09p05","audio":true,"sents":[{"fr":"La fleur toussa.","zh":"花儿咳嗽了。","t":[100,1950]},{"fr":"Mais ce n’était pas à cause de son rhume.","zh":"但这并不是因为她的感冒。","t":[1950,3724]}]},{"id":"ch09p06","audio":true,"sents":[{"fr":"— J’ai été sotte, lui dit-elle enfin.","zh":"——我太愚蠢了，她终于对他说。","t":[100,4000]},{"fr":"Je te demande pardon.","zh":"我向你道歉。","t":[4000,6138]},{"fr":"Tâche d’être heureux.","zh":"尽量让自己快乐吧。","t":[6138,7124]}]},{"id":"ch09p07","audio":true,"sents":[{"fr":"Il fut surpris par l’absence de reproches.","zh":"他被没有责备他的事感到惊讶。","t":[100,3162]},{"fr":"Il restait là tout déconcerté, le globe en l’air.","zh":"他站在那里，完全困惑，球在空中摇摆。","t":[3162,6775]},{"fr":"Il ne comprenait pas cette douceur calme.","zh":"他无法理解这种平静的温柔。","t":[6775,8712]}]},{"id":"ch09p08","audio":true,"sents":[{"fr":"— Mais oui, je t’aime, lui dit la fleur.","zh":"——是的，我爱你，花儿说。","t":[100,4388]},{"fr":"Tu n’en as rien su, par ma faute.","zh":"你什么都不知道，都是我的错。","t":[4388,7338]},{"fr":"Cela n’a aucune importance.","zh":"这没什么大不了的。","t":[7338,9825]},{"fr":"Mais tu as été aussi sot que moi.","zh":"但你和我一样愚蠢。","t":[9825,12438]},{"fr":"Tâche d’être heureux…","zh":"试着快乐起来……","t":[12438,14262]},{"fr":"Laisse ce globe tranquille.","zh":"让这个球安静下来。","t":[14262,16638]},{"fr":"Je n’en veux plus.","zh":"我不要再了。","t":[16638,17562]}]},{"id":"ch09p09","audio":true,"sents":[{"fr":"— Mais le vent…","zh":"——但风……","t":[100,1713]}]},{"id":"ch09p10","audio":true,"sents":[{"fr":"— Je ne suis pas si enrhumée que ça…","zh":"我并没有那么感冒...","t":[100,3575]},{"fr":"L’air frais de la nuit me fera du bien.","zh":"夜晚的清新空气会对我有好处的。","t":[3575,6300]},{"fr":"Je suis une fleur.","zh":"我是一朵花。","t":[6300,7413]}]},{"id":"ch09p11","audio":true,"sents":[{"fr":"— Mais les bêtes…","zh":"——可是动物们……","t":[100,1912]}]},{"id":"ch09p12","audio":true,"sents":[{"fr":"— Il faut bien que je supporte deux ou trois chenilles si je veux connaître les papillons.","zh":"——但既然我想了解蝴蝶，我总得忍受两三条毛毛虫。","t":[100,5925]},{"fr":"Il paraît que c’est tellement beau.","zh":"听说那非常美丽。","t":[5925,8188]},{"fr":"Sinon qui me rendra visite ?","zh":"否则谁会来看我呢？","t":[8188,11175]},{"fr":"Tu seras loin, toi.","zh":"你将会离得很远。","t":[11175,13500]},{"fr":"Quant aux grosses bêtes, je ne crains rien.","zh":"至于那些大动物，我无所畏惧。","t":[13500,16400]},{"fr":"J’ai mes griffes.","zh":"我有我的爪子。","t":[16400,17288]}]},{"id":"ch09p13","audio":true,"sents":[{"fr":"Et elle montrait naïvement ses quatre épines.","zh":"她天真地展示着她那四根刺。","t":[100,2988]},{"fr":"Puis elle ajouta :","zh":"然后她又补充道：","t":[2988,4700]}]},{"id":"ch09p14","audio":true,"sents":[{"fr":"— Ne traîne pas comme ça, c’est agaçant.","zh":"——别这样拖拖拉拉的，真让人厌烦。","t":[100,4050]},{"fr":"Tu as décidé de partir.","zh":"你已经决定离开了。","t":[4050,6412]},{"fr":"Va-t’en.","zh":"你走吧。","t":[6412,6924]}]},{"id":"ch09p15","audio":true,"sents":[{"fr":"Car elle ne voulait pas qu’il la vît pleurer.","zh":"因为她不想让他看到她哭泣。","t":[100,2812]},{"fr":"C’était une fleur tellement orgueilleuse…","zh":"那是一朵如此傲慢的花……","t":[2812,4637]}]},{"id":"ch09p16","audio":true,"sents":[]},{"id":"ch09p17","audio":true,"sents":[]},{"id":"ch09p18","audio":true,"sents":[]},{"id":"ch09p19","audio":true,"sents":[]},{"id":"ch09p20","audio":true,"sents":[]},{"id":"ch09p21","audio":true,"sents":[]},{"id":"ch09p22","audio":true,"sents":[]},{"id":"ch09p23","audio":true,"sents":[]},{"id":"ch09p24","audio":true,"sents":[]}]},{"id":"ch10","title_fr":"Chapitre X","title_zh":"第 10 章","paras":[{"id":"ch10p00","audio":true,"sents":[{"fr":"Il se trouvait dans la région des astéroïdes 325, 326, 327, 328, 329 et 330.","zh":"他发现自己身处325、326、327、328、329和330号小行星区域。","t":[100,9888]},{"fr":"Il commença donc par les visiter pour y chercher une occupation et pour s’instruire.","zh":"于是他开始逐一拜访，以寻找一份工作和增长见识。","t":[9888,14150]}]},{"id":"ch10p01","audio":true,"sents":[{"fr":"La première était habitée par un roi.","zh":"第一个小行星上住着一位国王。","t":[100,2912]},{"fr":"Le roi siégeait, habillé de pourpre et d’hermine, sur un trône très simple et cependant majestueux.","zh":"国王身着紫袍和狐狸皮，坐在一个简单却威严的宝座上。","t":[2912,8050]}]},{"id":"ch10p02","audio":true,"sents":[{"fr":"— Ah !","zh":"— 啊！","t":[100,3038]},{"fr":"Voilà un sujet, s’écria le roi quand il aperçut le petit prince.","zh":"当国王看见小王子时，他喊道：'这是一个臣民！'","t":[3038,6900]}]},{"id":"ch10p03","audio":true,"sents":[{"fr":"Et le petit prince se demanda :","zh":"而小王子心想：","t":[100,2500]}]},{"id":"ch10p04","audio":true,"sents":[{"fr":"— Comment peut-il me reconnaître puisqu’il ne m’a encore jamais vu !","zh":"— 他怎么能认出我，既然他从未见过我！","t":[100,4838]}]},{"id":"ch10p05","audio":true,"sents":[{"fr":"Il ne savait pas que, pour les rois, le monde est très simplifié.","zh":"他不知道，对于国王来说，世界是非常简化的。","t":[100,4325]},{"fr":"Tous les hommes sont des sujets.","zh":"所有的人都是臣民。","t":[4325,5675]}]},{"id":"ch10p06","audio":true,"sents":[{"fr":"— Approche-toi que je te voie mieux, lui dit le roi qui était tout fier d’être roi pour quelqu’un.","zh":"— 走近点，让我能更好地看你，国王对他说，他为能成为某人的国王而感到非常自豪。","t":[100,5612]}]},{"id":"ch10p07","audio":true,"sents":[{"fr":"Le petit prince chercha des yeux où s’asseoir, mais la planète était toute encombrée par le magnifique manteau d’hermine.","zh":"小王子四处寻找可以坐的地方，但整个星球都被华丽的貂皮大衣占满了。","t":[100,6812]},{"fr":"Il resta donc debout, et, comme il était fatigué, il bâilla.","zh":"所以他站着，而且由于他累了，他打了个哈欠。","t":[6812,10574]}]},{"id":"ch10p08","audio":true,"sents":[{"fr":"— Il est contraire à l’étiquette de bâiller en présence d’un roi, lui dit le monarque.","zh":"— 在国王面前打哈欠是有违礼节的，君主对他说。","t":[100,6250]},{"fr":"Je te l’interdis.","zh":"我禁止你这么做。","t":[6250,7350]}]},{"id":"ch10p09","audio":true,"sents":[{"fr":"— Je ne peux pas m’en empêcher, répondit le petit prince tout confus.","zh":"——我无法控制自己，小王子尴尬地回答。","t":[100,5538]},{"fr":"J’ai fait un long voyage et je n’ai pas dormi…","zh":"我长途跋涉，却没能入睡……","t":[5538,7575]}]},{"id":"ch10p10","audio":true,"sents":[{"fr":"— Alors, lui dit le roi, je t’ordonne de bâiller.","zh":"——那么，国王说，我命令你打哈欠。","t":[100,4888]},{"fr":"Je n’ai vu personne bâiller depuis des années.","zh":"我已经好多年没见过有人打哈欠了。","t":[4888,7950]},{"fr":"Les bâillements sont pour moi des curiosités.","zh":"对我来说，打哈欠是一种好奇。","t":[7950,11050]},{"fr":"Allons !","zh":"走吧！","t":[11050,13125]},{"fr":"bâille encore.","zh":"再打一个哈欠。","t":[13125,14850]},{"fr":"C’est un ordre.","zh":"这是一道命令。","t":[14850,15737]}]},{"id":"ch10p11","audio":true,"sents":[{"fr":"— Ça m’intimide…","zh":"——这让我感到害怕……","t":[100,2300]},{"fr":"je ne peux plus…","zh":"我再也……","t":[2300,3162]},{"fr":"fit le petit prince tout rougissant.","zh":"小王子涨红了脸说。","t":[3162,4713]}]},{"id":"ch10p12","audio":true,"sents":[{"fr":"— Hum !","zh":"——哼！","t":[100,2962]},{"fr":"Hum !","zh":"哼！","t":[2962,4350]},{"fr":"répondit le roi.","zh":"国王回答说。","t":[4350,6125]},{"fr":"Alors je…","zh":"那么我就……","t":[6125,6950]},{"fr":"je t’ordonne tantôt de bâiller et tantôt de…","zh":"我一会儿命令他打哈欠，一会儿又命令他……","t":[6950,9087]}]},{"id":"ch10p13","audio":true,"sents":[{"fr":"Il bredouillait un peu et paraissait vexé.","zh":"他有点结巴，看起来很生气。","t":[100,2225]}]},{"id":"ch10p14","audio":true,"sents":[{"fr":"Car le roi tenait essentiellement à ce que son autorité fût respectée.","zh":"因为国王主要想确保他的权威受到尊重。","t":[100,4500]},{"fr":"Il ne tolérait pas la désobéissance.","zh":"他不允许有人不服从。","t":[4500,7300]},{"fr":"C’était un monarque absolu.","zh":"这是一个绝对君主。","t":[7300,9638]},{"fr":"Mais, comme il était très bon, il donnait des ordres raisonnables.","zh":"但因为他非常善良，所以发布的命令是合理的。","t":[9638,13012]}]},{"id":"ch10p15","audio":true,"sents":[{"fr":"\"Si j’ordonnais, disait-il couramment, si j’ordonnais à un général de se changer en oiseau de mer, et si le général n’obéissait pas, ce ne serait pas la faute du général.","zh":"如果我下令，他说得轻车熟路，如果我下令让一个将军变成海鸟，而将军不服从，那不是将军的错。","t":[100,10600]},{"fr":"Ce serait ma faute.\"","zh":"那将是我的错。","t":[10600,11738]}]},{"id":"ch10p16","audio":true,"sents":[{"fr":"— Puis-je m’asseoir ?","zh":"我可以坐下来吗？","t":[100,3450]},{"fr":"s’enquit timidement le petit prince.","zh":"小王子胆怯地问道。","t":[3450,5325]}]},{"id":"ch10p17","audio":true,"sents":[{"fr":"— Je t’ordonne de t’asseoir, lui répondit le roi, qui ramena majestueusement un pan de son manteau d’hermine.","zh":"我命令你坐下来，国王回答道，他庄严地展开了一块狐狸毛皮披风的布料。","t":[100,6837]}]},{"id":"ch10p18","audio":true,"sents":[{"fr":"Mais le petit prince s’étonnait.","zh":"但小王子感到惊讶。","t":[100,2500]},{"fr":"La planète était minuscule.","zh":"这个星球非常小。","t":[2500,5000]},{"fr":"Sur quoi le roi pouvait-il bien régner ?","zh":"国王又能统治什么呢？","t":[5000,7650]}]},{"id":"ch10p19","audio":true,"sents":[{"fr":"— Sire, lui dit-il…","zh":"陛下，他对她说……","t":[100,2662]},{"fr":"je vous demande pardon de vous interroger…","zh":"我向您道歉，打扰您了……","t":[2662,4587]}]},{"id":"ch10p20","audio":true,"sents":[{"fr":"— Je t’ordonne de m’interroger, se hâta de dire le roi.","zh":"——陛下，我命令你审问我，国王急忙说道。","t":[100,4076]}]},{"id":"ch10p21","audio":true,"sents":[{"fr":"— Sire…","zh":"——陛下……","t":[100,1712]},{"fr":"sur quoi régnez-vous ?","zh":"您统治着什么？","t":[1712,3374]}]},{"id":"ch10p22","audio":true,"sents":[{"fr":"— Sur tout, répondit le roi, avec une grande simplicité.","zh":"——统治着一切，国王简单地回答。","t":[100,4587]}]},{"id":"ch10p23","audio":true,"sents":[{"fr":"— Sur tout ?","zh":"——统治着一切？","t":[100,2350]}]},{"id":"ch10p24","audio":true,"sents":[{"fr":"Le roi d’un geste discret désigna sa planète, les autres planètes et les étoiles.","zh":"国王用一个细微的手势指了指他的星球，其他星球和星星。","t":[100,4750]}]},{"id":"ch10p25","audio":true,"sents":[{"fr":"— Sur tout ça ?","zh":"——统治着这一切？","t":[100,2838]},{"fr":"dit le petit prince.","zh":"小王子说。","t":[2838,3826]}]},{"id":"ch10p26","audio":true,"sents":[{"fr":"— Sur tout ça…","zh":"关于这一切……","t":[100,2112]},{"fr":"répondit le roi.","zh":"国王回答说。","t":[2112,3013]}]},{"id":"ch10p27","audio":true,"sents":[{"fr":"Car non seulement c’était un monarque absolu mais c’était un monarque universel.","zh":"因为不仅他是绝对的君主，他还是宇宙的君主。","t":[100,3950]}]},{"id":"ch10p28","audio":true,"sents":[{"fr":"— Et les étoiles vous obéissent ?","zh":"——星星们会服从你吗？","t":[100,3176]}]},{"id":"ch10p29","audio":true,"sents":[{"fr":"— Bien sûr, lui dit le roi.","zh":"当然，国王说。","t":[100,3725]},{"fr":"Elles obéissent aussitôt.","zh":"它们立刻服从了。","t":[3725,5838]},{"fr":"Je ne tolère pas l’indiscipline.","zh":"我不容忍不守纪律。","t":[5838,7513]}]},{"id":"ch10p30","audio":true,"sents":[{"fr":"Un tel pouvoir émerveilla le petit prince.","zh":"这样的权力让小王子感到惊奇。","t":[100,3175]},{"fr":"S’il l’avait détenu lui-même, il aurait pu assister, non pas à quarante-quatre, mais à soixante-douze, ou même à cent, ou même à deux cents couchers de soleil dans la même journée, sans avoir jamais à tirer sa chaise !","zh":"如果他亲自掌握，他就能看到，不是四十四次，而是七十二次，甚至是一百次，甚至是一百次日出，在一天之内，而无需移动他的椅子！","t":[3175,15388]},{"fr":"Et comme il se sentait un peu triste à cause du souvenir de sa petite planète abandonnée, il s’enhardit à solliciter une grâce du roi :","zh":"由于他因为自己被遗弃的小星球而感到有点悲伤，他鼓起勇气请求国王开恩：","t":[15388,22575]}]},{"id":"ch10p31","audio":true,"sents":[{"fr":"— Je voudrais voir un coucher de soleil…","zh":"我想看看日落……","t":[100,3838]},{"fr":"Faites-moi plaisir…","zh":"让我高兴一下……","t":[3838,5825]},{"fr":"Ordonnez au soleil de se coucher…","zh":"命令太阳落山……","t":[5825,7600]}]},{"id":"ch10p32","audio":true,"sents":[{"fr":"— Si j’ordonnais à un général de voler d’une fleur à l’autre à la façon d’un papillon, ou d’écrire une tragédie, ou de se changer en oiseau de mer, et si le général n’exécutait pas l’ordre reçu, qui, de lui ou de moi, serait dans son tort ?","zh":"如果我命令一位将军像蝴蝶一样从一朵花飞到另一朵花，或者写一部悲剧，或者变成一只海鸟，而将军不执行我下达的命令，那么究竟是谁错了呢？","t":[100,14350]}]},{"id":"ch10p33","audio":true,"sents":[{"fr":"— Ce serait vous, dit fermement le petit prince.","zh":"是你，小王子坚定地说。","t":[100,3650]}]},{"id":"ch10p34","audio":true,"sents":[{"fr":"— Exact.","zh":"正是。","t":[100,2738]},{"fr":"Il faut exiger de chacun ce que chacun peut donner, reprit le roi.","zh":"国王继续说，必须要求每个人做他能做到的事情。","t":[2738,7212]},{"fr":"L’autorité repose d’abord sur la raison.","zh":"权威首先建立在理性之上。","t":[7212,10338]},{"fr":"Si tu ordonnes à ton peuple d’aller se jeter à la mer, il fera la révolution.","zh":"如果你命令你的百姓跳海，他们会造反的。","t":[10338,15362]},{"fr":"J’ai le droit d’exiger l’obéissance parce que mes ordres sont raisonnables.","zh":"我有权要求服从，因为我的命令是合理的。","t":[15362,18988]}]},{"id":"ch10p35","audio":true,"sents":[{"fr":"— Alors mon coucher de soleil ?","zh":"那么我的日落呢？","t":[100,4188]},{"fr":"rappela le petit prince qui jamais n’oubliait une question une fois qu’il l’avait posée.","zh":"小王子提醒道，他一旦提出问题就永远不会忘记。","t":[4188,8012]}]},{"id":"ch10p36","audio":true,"sents":[{"fr":"— Ton coucher de soleil, tu l’auras.","zh":"你的日落，你会拥有的。","t":[100,4025]},{"fr":"Je l’exigerai.","zh":"我会要求的。","t":[4025,5888]},{"fr":"Mais j’attendrai, dans ma science du gouvernement, que les conditions soient favorables.","zh":"但在我治理的科学中，我会等待条件有利。","t":[5888,10413]}]},{"id":"ch10p37","audio":true,"sents":[{"fr":"— Quand ça sera-t-il ?","zh":"那会是什么时候呢？","t":[100,3638]},{"fr":"s’informa le petit prince.","zh":"小王子问道。","t":[3638,5163]}]},{"id":"ch10p38","audio":true,"sents":[{"fr":"— Hem !","zh":"嗯！","t":[100,2975]},{"fr":"Hem !","zh":"嗯！","t":[2975,4875]},{"fr":"lui répondit le roi, qui consulta d’abord un gros calendrier, hem !","zh":"国王回答道，他首先查阅了一个大日历，嗯！","t":[4875,10262]},{"fr":"hem !","zh":"哼！","t":[10262,12162]},{"fr":"ce sera, vers…","zh":"那将是，向着……","t":[12162,13588]},{"fr":"vers…","zh":"向着……","t":[13588,14138]},{"fr":"ce sera ce soir vers sept heures quarante !","zh":"那将是今晚七点四十！","t":[14138,17488]},{"fr":"Et tu verras comme je suis bien obéi.","zh":"你会看到我多么守规矩。","t":[17488,19350]}]},{"id":"ch10p39","audio":true,"sents":[{"fr":"Le petit prince bâilla.","zh":"小王子打了个哈欠。","t":[100,2175]},{"fr":"Il regrettait son coucher de soleil manqué.","zh":"他后悔错过了日落。","t":[2175,5225]},{"fr":"Et puis il s’ennuyait déjà un peu :","zh":"然后他已经有点无聊了：","t":[5225,7550]}]},{"id":"ch10p40","audio":true,"sents":[{"fr":"— Je n’ai plus rien à faire ici, dit-il au roi.","zh":"——我已经在这里没事可做了，他对国王说。","t":[100,4488]},{"fr":"Je vais repartir !","zh":"我要走了！","t":[4488,6138]}]},{"id":"ch10p41","audio":true,"sents":[{"fr":"— Ne pars pas, répondit le roi qui était si fier d’avoir un sujet.","zh":"——不要离开，国王回答说，他对拥有一个臣民感到非常自豪。","t":[100,5350]},{"fr":"Ne pars pas, je te fais ministre !","zh":"不要离开，我要任命你为部长！","t":[5350,7850]}]},{"id":"ch10p42","audio":true,"sents":[{"fr":"— Ministre de quoi ?","zh":"——部长什么？","t":[100,2925]}]},{"id":"ch10p43","audio":true,"sents":[{"fr":"— De…","zh":"——","t":[100,1588]},{"fr":"de la justice !","zh":"司法部长！","t":[1588,3025]}]},{"id":"ch10p44","audio":true,"sents":[{"fr":"— Mais il n’y a personne à juger !","zh":"——但是没有人要审判啊！","t":[100,3412]}]},{"id":"ch10p45","audio":true,"sents":[{"fr":"— On ne sait pas, lui dit le roi.","zh":"——不知道，国王说。","t":[100,3662]},{"fr":"Je n’ai pas fait encore le tour de mon royaume.","zh":"我还没有巡视过我的王国。","t":[3662,6738]},{"fr":"Je suis très vieux, je n’ai pas de place pour un carrosse, et ça me fatigue de marcher.","zh":"我年纪很大了，没有地方放马车，而且走路也让我很累。","t":[6738,11238]}]},{"id":"ch10p46","audio":true,"sents":[{"fr":"— Oh !","zh":"——哦！","t":[100,3038]},{"fr":"Mais j’ai déjà vu, dit le petit prince qui se pencha pour jeter encore un coup d’œil sur l’autre côté de la planète.","zh":"但是我已经看过了，小王子说着，又低头看了一眼星球的另一面。","t":[3038,9675]},{"fr":"Il n’y a personne là-bas non plus…","zh":"那里也没有人...","t":[9675,11212]}]},{"id":"ch10p47","audio":true,"sents":[{"fr":"— Tu te jugeras donc toi-même, lui répondit le roi.","zh":"——那么你就自己评判自己吧，”国王回答道。","t":[100,4962]},{"fr":"C’est le plus difficile.","zh":"这是最难的。","t":[4962,7112]},{"fr":"Il est bien plus difficile de se juger soi-même que de juger autrui.","zh":"自己评判自己比评判别人要难得多。","t":[7112,11400]},{"fr":"Si tu réussis à bien te juger, c’est que tu es un véritable sage.","zh":"如果你能正确地评判自己，那么你就是一位真正的智者。","t":[11400,15050]}]},{"id":"ch10p48","audio":true,"sents":[{"fr":"— Moi, dit le petit prince, je puis me juger moi-même n’importe où.","zh":"——我，小王子说，我可以在任何地方评判自己。","t":[100,5512]},{"fr":"Je n’ai pas besoin d’habiter ici.","zh":"我不需要住在这里。","t":[5512,7337]}]},{"id":"ch10p49","audio":true,"sents":[{"fr":"— Hem !","zh":"——嗯...","t":[100,2975]},{"fr":"Hem !","zh":"嗯...","t":[2975,4250]},{"fr":"dit le roi, je crois bien que sur ma planète il y a quelque part un vieux rat.","zh":"国王说，我相信在我的星球上某个地方有一只老老鼠。","t":[4250,8700]},{"fr":"Je l’entends la nuit.","zh":"我晚上能听到它的声音。","t":[8700,10712]},{"fr":"Tu pourras juger ce vieux rat.","zh":"你可以审判这只老老鼠。","t":[10712,13100]},{"fr":"Tu le condamneras à mort de temps en temps.","zh":"你时不时地会判处它死刑。","t":[13100,16038]},{"fr":"Ainsi sa vie dépendra de ta justice.","zh":"这样，它的生命就取决于你的正义了。","t":[16038,18912]},{"fr":"Mais tu le gracieras chaque fois pour l’économiser.","zh":"但每次你都会赦免它，以节省它的生命。","t":[18912,22250]},{"fr":"Il n’y en a qu’un.","zh":"只有一个。","t":[22250,23124]}]},{"id":"ch10p50","audio":true,"sents":[{"fr":"— Moi, répondit le petit prince, je n’aime pas condamner à mort, et je crois bien que je m’en vais.","zh":"——我，小王子回答说，我不喜欢判处死刑，我相信我该走了。","t":[100,6275]}]},{"id":"ch10p51","audio":true,"sents":[{"fr":"— Non, dit le roi.","zh":"——不，国王说。","t":[100,2325]}]},{"id":"ch10p52","audio":true,"sents":[{"fr":"Mais le petit prince, ayant achevé ses préparatifs, ne voulut point peiner le vieux monarque :","zh":"但小王子完成了他的准备，不想让这位老君主感到痛苦：","t":[100,5688]}]},{"id":"ch10p53","audio":true,"sents":[{"fr":"— Si Votre Majesté désirait être obéie ponctuellement, elle pourrait me donner un ordre raisonnable.","zh":"如果陛下希望被准时服从，她可以给我一个合理的命令。","t":[100,6962]},{"fr":"Elle pourrait m’ordonner, par exemple, de partir avant une minute.","zh":"她可以命令我，比如说，在一分钟之前离开。","t":[6962,11588]},{"fr":"Il me semble que les conditions sont favorables…","zh":"我觉得条件是有利的……","t":[11588,13876]}]},{"id":"ch10p54","audio":true,"sents":[{"fr":"Le roi n’ayant rien répondu, le petit prince hésita d’abord, puis, avec un soupir, prit le départ.","zh":"国王没有回答，小王子犹豫了一下，然后叹了口气，出发了。","t":[100,6338]}]},{"id":"ch10p55","audio":true,"sents":[{"fr":"— Je te fais mon ambassadeur, se hâta alors de crier le roi.","zh":"我任命你为我的大使，国王急忙喊道。","t":[100,4513]}]},{"id":"ch10p56","audio":true,"sents":[{"fr":"Il avait un grand air d’autorité.","zh":"他看起来很有权威。","t":[100,1850]}]},{"id":"ch10p57","audio":true,"sents":[{"fr":"Les grandes personnes sont bien étranges, se dit le petit prince, en lui-même, durant son voyage.","zh":"大人们真是奇怪，小王子在旅途中自言自语。","t":[100,5663]}]},{"id":"ch10p58","audio":true,"sents":[]}]},{"id":"ch11","title_fr":"Chapitre XI","title_zh":"第 11 章","paras":[{"id":"ch11p00","audio":true,"sents":[{"fr":"La seconde planète était habitée par un vaniteux :","zh":"第二个星球住着一个爱慕虚荣的人：","t":[100,3287]}]},{"id":"ch11p01","audio":true,"sents":[{"fr":"— Ah !","zh":"啊！","t":[100,3038]},{"fr":"Ah !","zh":"啊！","t":[3038,4950]},{"fr":"Voilà la visite d’un admirateur !","zh":"这是位仰慕者来访！","t":[4950,7938]},{"fr":"s’écria de loin le vaniteux dès qu’il aperçut le petit prince.","zh":"爱慕虚荣的人远远地喊道，当他看到小王子。","t":[7938,10974]}]},{"id":"ch11p02","audio":true,"sents":[{"fr":"Car, pour les vaniteux, les autres hommes sont des admirateurs.","zh":"因为，对于爱慕虚荣的人来说，其他人都是仰慕者。","t":[100,3888]}]},{"id":"ch11p03","audio":true,"sents":[{"fr":"— Bonjour, dit le petit prince.","zh":"——你好，小王子说。","t":[100,3938]},{"fr":"Vous avez un drôle de chapeau.","zh":"你戴的帽子真奇怪。","t":[3938,5337]}]},{"id":"ch11p04","audio":true,"sents":[{"fr":"— C’est pour saluer, lui répondit le vaniteux.","zh":"——这是为了致敬，爱慕虚荣的人回答。","t":[100,4400]},{"fr":"C’est pour saluer quand on m’acclame.","zh":"当有人向我致敬时，我就这么做。","t":[4400,6962]},{"fr":"Malheureusement il ne passe jamais personne par ici.","zh":"不幸的是，从来没有人从这里经过。","t":[6962,9588]}]},{"id":"ch11p05","audio":true,"sents":[{"fr":"— Ah oui ?","zh":"——是啊？","t":[100,2562]},{"fr":"dit le petit prince qui ne comprit pas.","zh":"小王子说，他不懂。","t":[2562,4187]}]},{"id":"ch11p06","audio":true,"sents":[{"fr":"— Frappe tes mains l’une contre l’autre, conseilla donc le vaniteux.","zh":"——拍拍你的手，虚荣的人建议。","t":[100,4400]}]},{"id":"ch11p07","audio":true,"sents":[{"fr":"Le petit prince frappa ses mains l’une contre l’autre.","zh":"小王子拍拍他的手。","t":[100,3412]},{"fr":"Le vaniteux salua modestement en soulevant son chapeau.","zh":"虚荣的人谦逊地鞠躬，举起他的帽子。","t":[3412,6338]}]},{"id":"ch11p08","audio":true,"sents":[{"fr":"— Ça c’est plus amusant que la visite au roi, se dit en lui-même le petit prince.","zh":"——这比去看国王更有趣，小王子自言自语。","t":[100,5988]},{"fr":"Et il recommença de frapper ses mains l’une contre l’autre.","zh":"他又开始拍手。","t":[5988,9488]},{"fr":"Le vaniteux recommença de saluer en soulevant son chapeau.","zh":"虚荣的人又开始鞠躬，举起他的帽子。","t":[9488,12400]}]},{"id":"ch11p09","audio":true,"sents":[{"fr":"Après cinq minutes d’exercice le petit prince se fatigua de la monotonie du jeu :","zh":"经过五分钟的练习，小王子因为游戏的单调而感到疲倦：","t":[100,5037]}]},{"id":"ch11p10","audio":true,"sents":[{"fr":"— Et, pour que le chapeau tombe, demanda-t-il, que faut-il faire ?","zh":"——为了让帽子掉下来，他问，应该怎么做？","t":[100,5450]}]},{"id":"ch11p11","audio":true,"sents":[{"fr":"Mais le vaniteux ne l’entendit pas.","zh":"但虚荣的人没有听见。","t":[100,2562]},{"fr":"Les vaniteux n’entendent jamais que les louanges.","zh":"爱慕虚荣的人从来只会听到赞美。","t":[2562,4637]}]},{"id":"ch11p12","audio":true,"sents":[{"fr":"— Est-ce que tu m’admires vraiment beaucoup ?","zh":"——你真的非常崇拜我吗？","t":[100,3850]},{"fr":"demanda-t-il au petit prince.","zh":"他问小王子。","t":[3850,5325]}]},{"id":"ch11p13","audio":true,"sents":[{"fr":"— Qu’est-ce que signifie admirer ?","zh":"——崇拜是什么意思？","t":[100,3376]}]},{"id":"ch11p14","audio":true,"sents":[{"fr":"— Admirer signifie reconnaître que je suis l’homme le plus beau, le mieux habillé, le plus riche et le plus intelligent de la planète.","zh":"——崇拜就是承认我是这个星球上最英俊、最会穿衣打扮、最富有、最聪明的人。","t":[100,7738]}]},{"id":"ch11p15","audio":true,"sents":[{"fr":"— Mais tu es seul sur ta planète !","zh":"——但你一个人在你的星球上啊！","t":[100,3262]}]},{"id":"ch11p16","audio":true,"sents":[{"fr":"— Fais-moi ce plaisir.","zh":"——让我高兴一下。","t":[100,3175]},{"fr":"Admire-moi quand même !","zh":"还是崇拜我一下吧！","t":[3175,4900]}]},{"id":"ch11p17","audio":true,"sents":[{"fr":"— Je t’admire, dit le petit prince, en haussant un peu les épaules, mais en quoi cela peut-il bien t’intéresser ?","zh":"——我崇拜你，小王子说，微微耸了耸肩，但这对你有什么好处呢？","t":[100,7638]}]},{"id":"ch11p18","audio":true,"sents":[{"fr":"Et le petit prince s’en fut.","zh":"小王子于是离开了。","t":[100,1550]}]},{"id":"ch11p19","audio":true,"sents":[{"fr":"Les grandes personnes sont décidément bien bizarres, se dit-il simplement en lui-même durant son voyage.","zh":"大人确实很奇怪，他想，在旅途中自言自语。","t":[100,5487]}]},{"id":"ch11p20","audio":true,"sents":[]}]},{"id":"ch12","title_fr":"Chapitre XII","title_zh":"第 12 章","paras":[{"id":"ch12p00","audio":true,"sents":[]},{"id":"ch12p01","audio":true,"sents":[{"fr":"La planète suivante était habitée par un buveur.","zh":"下一个星球住着一个酒鬼。","t":[100,3650]},{"fr":"Cette visite fut très courte, mais elle plongea le petit prince dans une grande mélancolie :","zh":"这次访问很短暂，但让小王子陷入了深深的忧郁：","t":[3650,8862]}]},{"id":"ch12p02","audio":true,"sents":[{"fr":"— Que fais-tu là ?","zh":"你在那里做什么？","t":[100,2988]},{"fr":"dit-il au buveur, qu’il trouva installé en silence devant une collection de bouteilles vides et une collection de bouteilles pleines.","zh":"他对坐在一堆空瓶子和满瓶前的酒鬼说。","t":[2988,8963]}]},{"id":"ch12p03","audio":true,"sents":[{"fr":"— Je bois, répondit le buveur, d’un air lugubre.","zh":"我喝酒，酒鬼阴郁地回答。","t":[100,4237]}]},{"id":"ch12p04","audio":true,"sents":[{"fr":"— Pourquoi bois-tu ?","zh":"你为什么喝酒？","t":[100,3588]},{"fr":"lui demanda le petit prince.","zh":"小王子问道。","t":[3588,5150]}]},{"id":"ch12p05","audio":true,"sents":[{"fr":"— Pour oublier, répondit le buveur.","zh":"为了忘记，酒鬼回答说。","t":[100,3338]}]},{"id":"ch12p06","audio":true,"sents":[{"fr":"— Pour oublier quoi ?","zh":"为了忘记什么？","t":[100,3762]},{"fr":"s’enquit le petit prince qui déjà le plaignait.","zh":"小王子问道，他已经为它感到惋惜。","t":[3762,5900]}]},{"id":"ch12p07","audio":true,"sents":[{"fr":"— Pour oublier que j’ai honte, avoua le buveur en baissant la tête.","zh":"为了忘记我感到羞耻，酒鬼低下头承认。","t":[100,4625]}]},{"id":"ch12p08","audio":true,"sents":[{"fr":"— Honte de quoi ?","zh":"羞耻什么？","t":[100,3638]},{"fr":"s’informa le petit prince qui désirait le secourir.","zh":"小王子询问，他想要帮助他。","t":[3638,6387]}]},{"id":"ch12p09","audio":true,"sents":[{"fr":"— Honte de boire !","zh":"羞耻喝酒！","t":[100,3488]},{"fr":"acheva le buveur qui s’enferma définitivement dans le silence.","zh":"酒鬼说完，就永远地陷入了沉默。","t":[3488,6750]}]},{"id":"ch12p10","audio":true,"sents":[{"fr":"Et le petit prince s’en fut, perplexe.","zh":"小王子离开了，感到困惑。","t":[100,2450]}]},{"id":"ch12p11","audio":true,"sents":[{"fr":"Les grandes personnes sont décidément très très bizarres, se disait-il en lui-même durant le voyage.","zh":"在旅途中，他自言自语道，大人确实非常非常奇怪。","t":[100,5175]}]},{"id":"ch12p12","audio":true,"sents":[]}]},{"id":"ch13","title_fr":"Chapitre XIII","title_zh":"第 13 章","paras":[{"id":"ch13p00","audio":true,"sents":[{"fr":"La quatrième planète était celle du businessman.","zh":"第四颗星球是商人的星球。","t":[100,3575]},{"fr":"Cet homme était si occupé qu’il ne leva même pas la tête à l’arrivée du petit prince.","zh":"这个人如此忙碌，以至于在小王子到来时连头都没有抬。","t":[3575,7562]}]},{"id":"ch13p01","audio":true,"sents":[{"fr":"— Bonjour, lui dit celui-ci.","zh":"——你好，他对他说。","t":[100,3912]},{"fr":"Votre cigarette est éteinte.","zh":"你的烟灭了。","t":[3912,5537]}]},{"id":"ch13p02","audio":true,"sents":[{"fr":"— Trois et deux font cinq.","zh":"三加二等于五。","t":[100,3362]},{"fr":"Cinq et sept douze.","zh":"五加七十二。","t":[3362,5425]},{"fr":"Douze et trois quinze.","zh":"十二加三十五。","t":[5425,7475]},{"fr":"Bonjour.","zh":"你好。","t":[7475,9050]},{"fr":"Quinze et sept vingt-deux.","zh":"十五加七二十二。","t":[9050,11050]},{"fr":"Vingt-deux et six vingt-huit.","zh":"二十二和六，二十八。","t":[11050,13538]},{"fr":"Pas le temps de la rallumer.","zh":"没时间再点火了。","t":[13538,15688]},{"fr":"Vingt-six et cinq trente et un.","zh":"二十六和五，三十和一。","t":[15688,18200]},{"fr":"Ouf !","zh":"哦！","t":[18200,20125]},{"fr":"Ça fait donc cinq cent un millions six cent vingt-deux mille sept cent trente et un.","zh":"所以是五亿零一百六十二万七千三百三十一。","t":[20125,23513]}]},{"id":"ch13p03","audio":true,"sents":[{"fr":"— Cinq cents millions de quoi ?","zh":"—— 五千万什么？","t":[100,3162]}]},{"id":"ch13p04","audio":true,"sents":[{"fr":"— Hein ?","zh":"—— 嗯？","t":[100,3038]},{"fr":"Tu es toujours là ?","zh":"你还在那里吗？","t":[3038,5512]},{"fr":"Cinq cent un millions de…","zh":"五亿零一百…","t":[5512,6875]},{"fr":"je ne sais plus…","zh":"我不知道了……","t":[6875,8400]},{"fr":"J’ai tellement de travail !","zh":"我有很多工作！","t":[8400,11138]},{"fr":"Je suis sérieux, moi, je ne m’amuse pas à des balivernes !","zh":"我很认真，我可不是在开玩笑！","t":[11138,15862]},{"fr":"Deux et cinq sept…","zh":"二、五、七……","t":[15862,17062]}]},{"id":"ch13p05","audio":true,"sents":[{"fr":"— Cinq cent un millions de quoi, répéta le petit prince qui jamais de sa vie, n’avait renoncé à une question, une fois qu’il l’avait posée.","zh":"——五百零一百万什么，小王子重复道，他一生中从未放弃过一个问题，一旦提出就绝不罢休。","t":[100,8188]}]},{"id":"ch13p06","audio":true,"sents":[{"fr":"Le businessman leva la tête :","zh":"商人抬起头：","t":[100,2362]}]},{"id":"ch13p07","audio":true,"sents":[{"fr":"— Depuis cinquante-quatre ans que j’habite cette planète-ci, je n’ai été dérangé que trois fois.","zh":"——自从我住在这个星球上五十四年以来，我只被打扰过三次。","t":[100,6388]},{"fr":"La première fois ç’a été, il y a vingt-deux ans, par un hanneton qui était tombé Dieu sait d’où.","zh":"第一次是，二十二年前，一只从天而降的甲虫。","t":[6388,11950]},{"fr":"Il répandait un bruit épouvantable, et j’ai fait quatre erreurs dans une addition.","zh":"它发出可怕的噪音，我算加法时犯了四个错误。","t":[11950,16900]},{"fr":"La seconde fois ç’a été, il y a onze ans, par une crise de rhumatisme.","zh":"第二次是，十一年前，一场风湿病发作。","t":[16900,21788]},{"fr":"Je manque d’exercice.","zh":"我缺乏锻炼。","t":[21788,23988]},{"fr":"Je n’ai pas le temps de flâner.","zh":"我没有时间闲逛。","t":[23988,26238]},{"fr":"Je suis sérieux, moi.","zh":"我是认真的。","t":[26238,28688]},{"fr":"La troisième fois…","zh":"第三次...","t":[28688,29912]},{"fr":"la voici !","zh":"它就在这里！","t":[29912,32125]},{"fr":"Je disais donc cinq cent un millions…","zh":"我刚才说的是五亿零一百万...","t":[32125,33862]}]},{"id":"ch13p08","audio":true,"sents":[{"fr":"— Millions de quoi ?","zh":"——几百万什么？","t":[100,2788]}]},{"id":"ch13p09","audio":true,"sents":[{"fr":"Le businessman comprit qu’il n’était point d’espoir de paix :","zh":"商人明白和平的希望已经没有了：","t":[100,3600]}]},{"id":"ch13p10","audio":true,"sents":[{"fr":"— Millions de ces petites choses que l’on voit quelquefois dans le ciel.","zh":"——几百万这些我们在天空中偶尔看到的小东西。","t":[100,4126]}]},{"id":"ch13p11","audio":true,"sents":[{"fr":"— Des mouches ?","zh":"——苍蝇？","t":[100,2400]}]},{"id":"ch13p12","audio":true,"sents":[{"fr":"— Mais non, des petites choses qui brillent.","zh":"——不，是一些发光的小东西。","t":[100,3162]}]},{"id":"ch13p13","audio":true,"sents":[{"fr":"— Des abeilles ?","zh":"—— 蜜蜂？","t":[100,2537]}]},{"id":"ch13p14","audio":true,"sents":[{"fr":"— Mais non.","zh":"—— 不。","t":[100,2462]},{"fr":"Des petites choses dorées qui font rêvasser les fainéants.","zh":"一些金色的小东西，能让懒惰的人做梦。","t":[2462,5812]},{"fr":"Mais je suis sérieux, moi !","zh":"—— 但我是认真的，我！","t":[5812,8862]},{"fr":"Je n’ai pas le temps de rêvasser.","zh":"我没有时间做梦。","t":[8862,10362]}]},{"id":"ch13p15","audio":true,"sents":[{"fr":"— Ah !","zh":"—— 哎！","t":[100,3038]},{"fr":"des étoiles ?","zh":"星星？","t":[3038,4426]}]},{"id":"ch13p16","audio":true,"sents":[{"fr":"— C’est bien ça.","zh":"—— 是的。","t":[100,2800]},{"fr":"Des étoiles.","zh":"星星。","t":[2800,3663]}]},{"id":"ch13p17","audio":true,"sents":[{"fr":"— Et que fais-tu de cinq cents millions d’étoiles ?","zh":"—— 你怎么处理五亿颗星星呢？","t":[100,3650]}]},{"id":"ch13p18","audio":true,"sents":[{"fr":"— Cinq cent un millions six cent vingt-deux mille sept cent trente et un.","zh":"五千零一百万六千二百二十万七千三百零一。","t":[100,4862]},{"fr":"Je suis sérieux, moi, je suis précis.","zh":"我是认真的，我是精确的。","t":[4862,7450]}]},{"id":"ch13p19","audio":true,"sents":[{"fr":"— Et que fais-tu de ces étoiles ?","zh":"那么，你对这些星星有什么看法？","t":[100,3150]}]},{"id":"ch13p20","audio":true,"sents":[{"fr":"— Ce que j’en fais ?","zh":"那么，我对它们有什么看法？","t":[100,2650]}]},{"id":"ch13p21","audio":true,"sents":[{"fr":"— Oui.","zh":"是的。","t":[100,1525]}]},{"id":"ch13p22","audio":true,"sents":[{"fr":"— Rien.","zh":"什么也没有。","t":[100,2512]},{"fr":"Je les possède.","zh":"我拥有它们。","t":[2512,3538]}]},{"id":"ch13p23","audio":true,"sents":[{"fr":"— Tu possèdes les étoiles ?","zh":"你拥有星星吗？","t":[100,3013]}]},{"id":"ch13p24","audio":true,"sents":[{"fr":"— Oui.","zh":"是的。","t":[100,1525]}]},{"id":"ch13p25","audio":true,"sents":[{"fr":"— Mais j’ai déjà vu un roi qui…","zh":"但是，我已经见过一个国王……","t":[100,2676]}]},{"id":"ch13p26","audio":true,"sents":[{"fr":"— Les rois ne possèdent pas.","zh":"国王并不拥有。","t":[100,3188]},{"fr":"Ils \"règnent\" sur.","zh":"他们“统治”着。","t":[3188,5238]},{"fr":"C’est très différent.","zh":"这很不同。","t":[5238,6200]}]},{"id":"ch13p27","audio":true,"sents":[{"fr":"— Et à quoi cela te sert-il de posséder les étoiles ?","zh":"那么，拥有星星对你来说有什么用？","t":[100,4275]}]},{"id":"ch13p28","audio":true,"sents":[{"fr":"— Ça me sert à être riche.","zh":"这让我变得富有。","t":[100,2475]}]},{"id":"ch13p29","audio":true,"sents":[{"fr":"— Et à quoi cela te sert-il d’être riche ?","zh":"那么，富有对你来说有什么用？","t":[100,3737]}]},{"id":"ch13p30","audio":true,"sents":[{"fr":"— A acheter d’autres étoiles, si quelqu’un en trouve.","zh":"如果有人找到星星，我可以买下它们。","t":[100,3976]}]},{"id":"ch13p31","audio":true,"sents":[{"fr":"Celui-là, se dit en lui-même le petit prince, il raisonne un peu comme mon ivrogne.","zh":"那个，小王子自言自语，他思考的方式有点像我那个酒鬼。","t":[100,4675]}]},{"id":"ch13p32","audio":true,"sents":[{"fr":"Cependant il posa encore des questions :","zh":"然而，他还是继续提问：","t":[100,2900]}]},{"id":"ch13p33","audio":true,"sents":[{"fr":"— Comment peut-on posséder les étoiles ?","zh":"人们怎么能拥有星星呢？","t":[100,3513]}]},{"id":"ch13p34","audio":true,"sents":[{"fr":"— A qui sont-elles ?","zh":"它们属于谁？","t":[100,3488]},{"fr":"riposta, grincheux, le businessman.","zh":"商人回答，带着一丝不满。","t":[3488,6188]}]},{"id":"ch13p35","audio":true,"sents":[{"fr":"— Je ne sais pas.","zh":"我不知道。","t":[100,2725]},{"fr":"A personne.","zh":"不属于任何人。","t":[2725,3500]}]},{"id":"ch13p36","audio":true,"sents":[{"fr":"— Alors elles sont à moi, car j’y ai pensé le premier.","zh":"那么它们就属于我了，因为我是第一个想到它们的。","t":[100,3937]}]},{"id":"ch13p37","audio":true,"sents":[{"fr":"— Ça suffit ?","zh":"这就足够了吗？","t":[100,2613]}]},{"id":"ch13p38","audio":true,"sents":[{"fr":"— Bien sûr.","zh":"当然。","t":[100,2750]},{"fr":"Quand tu trouves un diamant qui n’est à personne, il est à toi.","zh":"当你找到一个不属于任何人的钻石时，它就属于你。","t":[2750,6675]},{"fr":"Quand tu trouves une île qui n’est à personne, elle est à toi.","zh":"当你找到一个不属于任何人的岛屿时，它就属于你。","t":[6675,10350]},{"fr":"Quand tu as une idée le premier, tu la fais breveter : elle est à toi.","zh":"当你第一个有了一个想法，你就去申请专利：它就属于你。","t":[10350,15512]},{"fr":"Et moi je possède les étoiles, puisque jamais personne avant moi n’a songé à les posséder.","zh":"而且，我拥有星星，因为以前没有人想过要拥有它们。","t":[15512,20138]}]},{"id":"ch13p39","audio":true,"sents":[{"fr":"— Ça c’est vrai, dit le petit prince.","zh":"这是真的，小王子说。","t":[100,4000]},{"fr":"Et qu’en fais-tu ?","zh":"那你怎么办？","t":[4000,5537]}]},{"id":"ch13p40","audio":true,"sents":[{"fr":"— Je les gère.","zh":"我管理它们。","t":[100,2812]},{"fr":"Je les compte et je les recompte, dit le businessman.","zh":"我数它们，然后再数一遍，商人说。","t":[2812,6575]},{"fr":"C’est difficile.","zh":"这很难。","t":[6575,8450]},{"fr":"Mais je suis un homme sérieux !","zh":"但我是个认真的人！","t":[8450,10475]}]},{"id":"ch13p41","audio":true,"sents":[{"fr":"Le petit prince n’était pas satisfait encore.","zh":"小王子还是不满意。","t":[100,2413]}]},{"id":"ch13p42","audio":true,"sents":[{"fr":"— Moi, si je possède un foulard, je puis le mettre autour de mon cou et l’emporter.","zh":"我啊，如果我有一块围巾，我就可以围在脖子上，带走它。","t":[100,6225]},{"fr":"Moi, si je possède une fleur, je puis cueillir ma fleur et l’emporter.","zh":"我啊，如果我有一朵花，我就可以摘下我的花，带走它。","t":[6225,11038]},{"fr":"Mais tu ne peux pas cueillir les étoiles !","zh":"但你不能摘星星！","t":[11038,13374]}]},{"id":"ch13p43","audio":true,"sents":[{"fr":"— Non, mais je puis les placer en banque.","zh":"——不，但我可以把它们存进银行。","t":[100,3162]}]},{"id":"ch13p44","audio":true,"sents":[{"fr":"— Qu’est-ce que ça veut dire ?","zh":"——那是什么意思？","t":[100,2876]}]},{"id":"ch13p45","audio":true,"sents":[{"fr":"— Ça veut dire que j’écris sur un petit papier le nombre de mes étoiles.","zh":"——那意味着我在一张小纸上写下我的星星数量。","t":[100,5275]},{"fr":"Et puis j’enferme à clef ce papier-là dans un tiroir.","zh":"然后我把这张纸锁进抽屉里。","t":[5275,7850]}]},{"id":"ch13p46","audio":true,"sents":[{"fr":"— Et c’est tout ?","zh":"——这就完了？","t":[100,2413]}]},{"id":"ch13p47","audio":true,"sents":[{"fr":"— Ça suffit !","zh":"——这就足够了！","t":[100,2600]}]},{"id":"ch13p48","audio":true,"sents":[{"fr":"C’est amusant, pensa le petit prince.","zh":"这很有趣，小王子想。","t":[100,3250]},{"fr":"C’est assez poétique.","zh":"这很诗意。","t":[3250,5312]},{"fr":"Mais ce n’est pas très sérieux.","zh":"但并不太严肃。","t":[5312,6537]}]},{"id":"ch13p49","audio":true,"sents":[{"fr":"Le petit prince avait sur les choses sérieuses des idées très différentes des idées des grandes personnes.","zh":"小王子对于严肃的事情有着与大人们完全不同的想法。","t":[100,4900]}]},{"id":"ch13p50","audio":true,"sents":[{"fr":"— Moi, dit-il encore, je possède une fleur que j’arrose tous les jours.","zh":"——我呢，他又说，我拥有一朵花，我每天都给它浇水。","t":[100,5712]},{"fr":"Je possède trois volcans que je ramone toutes les semaines.","zh":"我拥有三座火山，我每周都为它们清扫。","t":[5712,9338]},{"fr":"Car je ramone aussi celui qui est éteint.","zh":"因为我连那座已经熄灭的火山也清扫。","t":[9338,12238]},{"fr":"On ne sait jamais.","zh":"谁也说不准。","t":[12238,13900]},{"fr":"C’est utile à mes volcans, et c’est utile à ma fleur, que je les possède.","zh":"拥有它们对我的火山有用，对我的花也有用。","t":[13900,18925]},{"fr":"Mais tu n’es pas utile aux étoiles…","zh":"但是你对星星没有用处……","t":[18925,20650]}]},{"id":"ch13p51","audio":true,"sents":[{"fr":"Le businessman ouvrit la bouche mais ne trouva rien à répondre, et le petit prince s’en fut.","zh":"商人张开了嘴，却找不到什么话来回答，于是小王子就离开了。","t":[100,4888]}]},{"id":"ch13p52","audio":true,"sents":[{"fr":"Les grandes personnes sont décidément tout à fait extraordinaires, se disait-il simplement en lui-même durant le voyage.","zh":"他在旅途中只是对自己说：大人们确实非常特别。","t":[100,6262]}]},{"id":"ch13p53","audio":true,"sents":[]}]},{"id":"ch14","title_fr":"Chapitre XIV","title_zh":"第 14 章","paras":[{"id":"ch14p00","audio":true,"sents":[{"fr":"La cinquième planète était très curieuse.","zh":"第五颗星球非常好奇。","t":[100,3075]},{"fr":"C’était la plus petite de toutes.","zh":"它是所有星球中最小的。","t":[3075,5612]},{"fr":"Il y avait là juste assez de place pour loger un réverbère et un allumeur de réverbères.","zh":"那里刚好有足够的空间容纳一盏路灯和一个点路灯的人。","t":[5612,10875]},{"fr":"Le petit prince ne parvenait pas à s’expliquer à quoi pouvaient servir, quelque part dans le ciel, sur une planète sans maison, ni population, un réverbère et un allumeur de réverbères.","zh":"小王子无法解释为什么在天空中的一个没有房屋和居民的小星球上，会有一个路灯和一个点路灯的人。","t":[10875,21712]},{"fr":"Cependant il se dit en lui-même :","zh":"然而他在心里对自己说：","t":[21712,23938]}]},{"id":"ch14p01","audio":true,"sents":[{"fr":"— Peut-être bien que cet homme est absurde.","zh":"——也许这个人很荒谬。","t":[100,4050]},{"fr":"Cependant il est moins absurde que le roi, que le vaniteux, que le businessman et que le buveur.","zh":"然而，他比国王、爱慕虚荣的人、商人和酒鬼都要少一些荒谬。","t":[4050,9962]},{"fr":"Au moins son travail a-t-il un sens.","zh":"至少他的工作是有意义的。","t":[9962,12675]},{"fr":"Quand il allume son réverbère, c’est comme s’il faisait naître une étoile de plus, ou une fleur.","zh":"当他点亮他的路灯时，就像是他又点亮了一颗星星，或者一朵花。","t":[12675,18525]},{"fr":"Quand il éteint son réverbère ça endort la fleur ou l’étoile.","zh":"当他熄灭他的路灯时，就像是他把花朵或星星送入了梦乡。","t":[18525,22775]},{"fr":"C’est une occupation très jolie.","zh":"这是一项非常美好的职业。","t":[22775,25138]},{"fr":"C’est véritablement utile puisque c’est joli.","zh":"这真的是有用的，因为它是美丽的。","t":[25138,27475]}]},{"id":"ch14p02","audio":true,"sents":[{"fr":"Lorsqu’il aborda la planète il salua respectueusement l’allumeur :","zh":"当他到达这个星球时，他恭敬地问候了点灯人：","t":[100,4138]}]},{"id":"ch14p03","audio":true,"sents":[{"fr":"— Bonjour.","zh":"——你好。","t":[100,2712]},{"fr":"Pourquoi viens-tu d’éteindre ton réverbère ?","zh":"你为什么熄灭了你的路灯？","t":[2712,5388]}]},{"id":"ch14p04","audio":true,"sents":[{"fr":"— C’est la consigne, répondit l’allumeur.","zh":"——这是规定，点灯人回答。","t":[100,4375]},{"fr":"Bonjour.","zh":"你好。","t":[4375,5087]}]},{"id":"ch14p05","audio":true,"sents":[{"fr":"— Qu’est-ce que la consigne ?","zh":"——规定是什么？","t":[100,2900]}]},{"id":"ch14p06","audio":true,"sents":[{"fr":"— C’est d’éteindre mon réverbère.","zh":"——规定是熄灭我的路灯。","t":[100,3675]},{"fr":"Bonsoir.","zh":"晚安。","t":[3675,4500]}]},{"id":"ch14p07","audio":true,"sents":[{"fr":"Et il le ralluma.","zh":"他重新点燃了它。","t":[100,1012]}]},{"id":"ch14p08","audio":true,"sents":[{"fr":"— Mais pourquoi viens-tu de le rallumer ?","zh":"——可你为什么要重新点燃它呢？","t":[100,3675]}]},{"id":"ch14p09","audio":true,"sents":[{"fr":"— C’est la consigne, répondit l’allumeur.","zh":"——这是规定，点灯人回答。","t":[100,3512]}]},{"id":"ch14p10","audio":true,"sents":[{"fr":"— Je ne comprends pas, dit le petit prince.","zh":"——我不懂，小王子说。","t":[100,3424]}]},{"id":"ch14p11","audio":true,"sents":[{"fr":"— Il n’y a rien à comprendre, dit l’allumeur.","zh":"——没有什么好懂的，点灯人说。","t":[100,4375]},{"fr":"La consigne c’est la consigne.","zh":"规定就是规定。","t":[4375,6912]},{"fr":"Bonjour.","zh":"你好。","t":[6912,7624]}]},{"id":"ch14p12","audio":true,"sents":[{"fr":"Et il éteignit son réverbère.","zh":"然后他熄灭了探照灯。","t":[100,1674]}]},{"id":"ch14p13","audio":true,"sents":[{"fr":"Puis il s’épongea le front avec un mouchoir à carreaux rouges.","zh":"接着他用红色的格子手帕擦了擦额头。","t":[100,2938]}]},{"id":"ch14p14","audio":true,"sents":[{"fr":"— Je fais là un métier terrible.","zh":"——我这里的工作真是可怕。","t":[100,3525]},{"fr":"C’était raisonnable autrefois.","zh":"从前这是合理的。","t":[3525,5962]},{"fr":"J’éteignais le matin et j’allumais le soir.","zh":"我早上熄灯，晚上点灯。","t":[5962,9062]},{"fr":"J’avais le reste du jour pour me reposer, et le reste de la nuit pour dormir…","zh":"我剩下的白天可以休息，剩下的夜晚可以睡觉……","t":[9062,13287]}]},{"id":"ch14p15","audio":true,"sents":[{"fr":"— Et, depuis cette époque, la consigne a changé ?","zh":"——&nbsp;从那时起，规定有变吗？","t":[100,4550]}]},{"id":"ch14p16","audio":true,"sents":[{"fr":"— La consigne n’a pas changé, dit l’allumeur.","zh":"——&nbsp;规定没有变，点灯人说。","t":[100,4675]},{"fr":"C’est bien là le drame !","zh":"这正是悲剧所在！","t":[4675,7000]},{"fr":"La planète d’année en année a tourné de plus en plus vite, et la consigne n’a pas changé !","zh":"这个星球一年比一年转得快，但规定没有变！","t":[7000,12188]}]},{"id":"ch14p17","audio":true,"sents":[{"fr":"— Alors ?","zh":"——&nbsp;那么呢？","t":[100,2575]},{"fr":"dit le petit prince.","zh":"小王子说。","t":[2575,3576]}]},{"id":"ch14p18","audio":true,"sents":[{"fr":"— Alors maintenant qu’elle fait un tour par minute, je n’ai plus une seconde de repos.","zh":"——&nbsp;那么现在它每分钟转一圈，我再也没有休息的时间了。","t":[100,5938]},{"fr":"J’allume et j’éteins une fois par minute !","zh":"我每分钟点一次灯，熄一次灯！","t":[5938,8388]}]},{"id":"ch14p19","audio":true,"sents":[{"fr":"— Ça c’est drôle !","zh":"—— 这很有趣！","t":[100,3362]},{"fr":"Les jours chez toi durent une minute !","zh":"在你那里的日子只有一分钟！","t":[3362,5563]}]},{"id":"ch14p20","audio":true,"sents":[{"fr":"— Ce n’est pas drôle du tout, dit l’allumeur.","zh":"—— 这一点也不好笑，点灯人说。","t":[100,4388]},{"fr":"Ça fait déjà un mois que nous parlons ensemble.","zh":"我们已经开始一起说话一个月了。","t":[4388,6500]}]},{"id":"ch14p21","audio":true,"sents":[{"fr":"— Un mois ?","zh":"—— 一个月？","t":[100,2350]}]},{"id":"ch14p22","audio":true,"sents":[{"fr":"— Oui.","zh":"—— 是的。","t":[100,2400]},{"fr":"Trente minutes.","zh":"三十分钟。","t":[2400,4262]},{"fr":"Trente jours !","zh":"三十天！","t":[4262,6438]},{"fr":"Bonsoir.","zh":"晚上好。","t":[6438,7263]}]},{"id":"ch14p23","audio":true,"sents":[{"fr":"Et il ralluma son réverbère.","zh":"他重新点亮了他的灯笼。","t":[100,1700]}]},{"id":"ch14p24","audio":true,"sents":[{"fr":"Le petit prince le regarda et il aima cet allumeur qui était tellement fidèle à la consigne.","zh":"小王子看着他，喜欢这个如此忠诚于职责的点火人。","t":[100,5662]},{"fr":"Il se souvint des couchers de soleil que lui-même allait autrefois chercher, en tirant sa chaise.","zh":"他想起了自己过去常常拉椅子去找的日落。","t":[5662,11238]},{"fr":"Il voulut aider son ami :","zh":"他想帮助他的朋友：","t":[11238,13325]}]},{"id":"ch14p25","audio":true,"sents":[{"fr":"— Tu sais…","zh":"——你知道……","t":[100,1975]},{"fr":"je connais un moyen de te reposer quand tu voudras…","zh":"我有一个方法，当你想休息的时候……","t":[1975,4238]}]},{"id":"ch14p26","audio":true,"sents":[{"fr":"— Je veux toujours, dit l’allumeur.","zh":"——我总是想，点火人说。","t":[100,3113]}]},{"id":"ch14p27","audio":true,"sents":[{"fr":"Car on peut être, à la fois, fidèle et paresseux.","zh":"因为一个人可以既是忠诚的，又是懒惰的。","t":[100,3074]}]},{"id":"ch14p28","audio":true,"sents":[{"fr":"Le petit prince poursuivit :","zh":"小王子继续说：","t":[100,2287]}]},{"id":"ch14p29","audio":true,"sents":[{"fr":"— Ta planète est tellement petite que tu en fais le tour en trois enjambées.","zh":"——你的星球太小了，你只需要三步就能走完一圈。","t":[100,5262]},{"fr":"Tu n’as qu’à marcher assez lentement pour rester toujours au soleil.","zh":"你只需慢慢地走，以便始终处于阳光下。","t":[5262,9150]},{"fr":"Quand tu voudras te reposer tu marcheras…","zh":"当你想休息时，你就走...","t":[9150,11488]},{"fr":"et le jour durera aussi longtemps que tu voudras.","zh":"而且，白天将持续到你愿意的时间。","t":[11488,13662]}]},{"id":"ch14p30","audio":true,"sents":[{"fr":"— Ça ne m’avance pas à grand’chose, dit l’allumeur.","zh":"——这对我没什么帮助，点灯人说。","t":[100,4600]},{"fr":"Ce que j’aime dans la vie, c’est dormir.","zh":"我生活中喜欢的是睡觉。","t":[4600,6776]}]},{"id":"ch14p31","audio":true,"sents":[{"fr":"— Ce n’est pas de chance, dit le petit prince.","zh":"——这不是运气，小王子说。","t":[100,3475]}]},{"id":"ch14p32","audio":true,"sents":[{"fr":"— Ce n’est pas de chance, dit l’allumeur.","zh":"——这不是运气，点灯人说。","t":[100,4025]},{"fr":"Bonjour.","zh":"你好。","t":[4025,4737]}]},{"id":"ch14p33","audio":true,"sents":[{"fr":"Et il éteignit son réverbère.","zh":"然后他熄灭了探照灯。","t":[100,1674]}]},{"id":"ch14p34","audio":true,"sents":[{"fr":"Celui-là, se dit le petit prince, tandis qu’il poursuivait plus loin son voyage, celui-là serait méprisé par tous les autres, par le roi, par le vaniteux, par le buveur, par le businessman.","zh":"而那个，小王子在继续他的旅途中说，那个会被所有人，包括国王、爱慕虚荣的人、酒鬼、商人所轻视。","t":[100,12112]},{"fr":"Cependant c’est le seul qui ne me paraisse pas ridicule.","zh":"然而，他却是我觉得并不荒谬的。","t":[12112,15725]},{"fr":"C’est, peut-être, parce qu’il s’occupe d’autre chose que de soi-même.","zh":"也许是因为他关心的事情不仅仅是自己。","t":[15725,19300]}]},{"id":"ch14p35","audio":true,"sents":[{"fr":"Il eut un soupir de regret et se dit encore :","zh":"他叹了口气，又说道：","t":[100,2950]}]},{"id":"ch14p36","audio":true,"sents":[{"fr":"— Celui-là est le seul dont j’eusse pu faire mon ami.","zh":"——那个是我本可以成为朋友的。","t":[100,4312]},{"fr":"Mais sa planète est vraiment trop petite.","zh":"但他的星球实在太小了。","t":[4312,7125]},{"fr":"Il n’y a pas de place pour deux…","zh":"这里没有足够的空间容纳两个……","t":[7125,8475]}]},{"id":"ch14p37","audio":true,"sents":[{"fr":"Ce que le petit prince n’osait pas s’avouer, c’est qu’il regrettait cette planète bénie à cause, surtout, des mille quatre cent quarante couchers de soleil par vingt-quatre heures !","zh":"小王子不敢承认的是，他因为，尤其是，因为每天二十四小时有一千四百四十次日落而后悔这个被祝福的星球。","t":[100,9063]}]},{"id":"ch14p38","audio":true,"sents":[]}]},{"id":"ch15","title_fr":"Chapitre XV","title_zh":"第 15 章","paras":[{"id":"ch15p00","audio":true,"sents":[{"fr":"La sixième planète était une planète dix fois plus vaste.","zh":"第六颗星球是一个比它大十倍的星球。","t":[100,4000]},{"fr":"Elle était habitée par un vieux Monsieur qui écrivait d’énormes livres.","zh":"它住着一个写大书的老人。","t":[4000,7125]}]},{"id":"ch15p01","audio":true,"sents":[{"fr":"— Tiens !","zh":"Tiens !","t":[100,3200]},{"fr":"voilà un explorateur !","zh":" voilà un explorateur !","t":[3200,6112]},{"fr":"s’écria-t-il, quand il aperçut le petit prince.","zh":" s’écria-t-il, quand il aperçut le petit prince.","t":[6112,9075]}]},{"id":"ch15p02","audio":true,"sents":[{"fr":"Le petit prince s’assit sur la table et souffla un peu.","zh":"Le petit prince s’assit sur la table et souffla un peu.","t":[100,3600]},{"fr":"Il avait déjà tant voyagé !","zh":"Il avait déjà tant voyagé !","t":[3600,5838]}]},{"id":"ch15p03","audio":true,"sents":[{"fr":"— D’où viens-tu ?","zh":"D’où viens-tu ?","t":[100,3462]},{"fr":"lui dit le vieux Monsieur.","zh":"lui dit le vieux Monsieur.","t":[3462,4562]}]},{"id":"ch15p04","audio":true,"sents":[{"fr":"— Quel est ce gros livre ?","zh":"Quel est ce gros livre ?","t":[100,3188]},{"fr":"dit le petit prince.","zh":"dit le petit prince.","t":[3188,5050]},{"fr":"Que faites-vous ici ?","zh":"Que faites-vous ici ?","t":[5050,6738]}]},{"id":"ch15p05","audio":true,"sents":[{"fr":"— Je suis géographe, dit le vieux Monsieur.","zh":"我是地理学家，老先生说道。","t":[100,3200]}]},{"id":"ch15p06","audio":true,"sents":[{"fr":"— Qu’est-ce qu’un géographe ?","zh":"地理学家是什么？","t":[100,2875]}]},{"id":"ch15p07","audio":true,"sents":[{"fr":"— C’est un savant qui connaît où se trouvent les mers, les fleuves, les villes, les montagnes et les déserts.","zh":"是一位知道大海、河流、城市、山脉和沙漠在哪里的大师。","t":[100,6450]}]},{"id":"ch15p08","audio":true,"sents":[{"fr":"— Ça c’est bien intéressant, dit le petit prince.","zh":"这很有趣，小王子说。","t":[100,4612]},{"fr":"Ça c’est enfin un véritable métier !","zh":"这终于是一项真正的职业！","t":[4612,8212]},{"fr":"Et il jeta un coup d’œil autour de lui sur la planète du géographe.","zh":"然后他环顾四周，看地理学家的星球。","t":[8212,12362]},{"fr":"Il n’avait jamais vu encore une planète aussi majestueuse.","zh":"他从未见过如此庄严的星球。","t":[12362,15288]}]},{"id":"ch15p09","audio":true,"sents":[{"fr":"— Elle est bien belle, votre planète.","zh":"您的星球真美。","t":[100,4112]},{"fr":"Est-ce qu’il y a des océans ?","zh":"有海洋吗？","t":[4112,6100]}]},{"id":"ch15p10","audio":true,"sents":[{"fr":"— Je ne puis pas le savoir, dit le géographe.","zh":"我无法知道，地理学家说。","t":[100,3512]}]},{"id":"ch15p11","audio":true,"sents":[{"fr":"— Ah !","zh":"啊！","t":[100,3038]},{"fr":"(Le petit prince était déçu.) Et des montagnes ?","zh":"(小王子感到失望。)还有山吗？","t":[3038,6962]}]},{"id":"ch15p12","audio":true,"sents":[{"fr":"— Je ne puis pas le savoir, dit le géographe.","zh":"—— 我不知道，地理学家说。","t":[100,3512]}]},{"id":"ch15p13","audio":true,"sents":[{"fr":"— Et des villes et des fleuves et des déserts ?","zh":"—— 还有城市、河流和沙漠吗？","t":[100,3463]}]},{"id":"ch15p14","audio":true,"sents":[{"fr":"— Je ne puis pas le savoir non plus, dit le géographe.","zh":"—— 我也不知道，地理学家说。","t":[100,3838]}]},{"id":"ch15p15","audio":true,"sents":[{"fr":"— Mais vous êtes géographe !","zh":"—— 但你不是地理学家吗？","t":[100,2987]}]},{"id":"ch15p16","audio":true,"sents":[{"fr":"— C’est exact, dit le géographe, mais je ne suis pas explorateur.","zh":"—— 是的，地理学家说，但我不是探险家。","t":[100,5912]},{"fr":"Je manque absolument d’explorateurs.","zh":"我完全缺少探险家。","t":[5912,8875]},{"fr":"Ce n’est pas le géographe qui va faire le compte des villes, des fleuves, des montagnes, des mers, des océans et des déserts.","zh":"不是地理学家去计算城市、河流、山脉、海洋和沙漠的数量。","t":[8875,16612]},{"fr":"Le géographe est trop important pour flâner.","zh":"地理学家太重要了，不能闲逛。","t":[16612,19650]},{"fr":"Il ne quitte pas son bureau.","zh":"他从不离开他的办公室。","t":[19650,21875]},{"fr":"Mais il y reçoit les explorateurs.","zh":"但他会在那里接待探险家。","t":[21875,24612]},{"fr":"Il les interroge, et il prend en note leurs souvenirs.","zh":"他会询问他们，并记录下他们的回忆。","t":[24612,28388]},{"fr":"Et si les souvenirs de l’un d’entre eux lui paraissent intéressants, le géographe fait faire une enquête sur la moralité de l’explorateur.","zh":"如果其中一个人的回忆让他觉得有趣，地理学家就会进行调查，了解探险家的品德。","t":[28388,34763]}]},{"id":"ch15p17","audio":true,"sents":[{"fr":"— Pourquoi ça ?","zh":"——为什么这样？","t":[100,2538]}]},{"id":"ch15p18","audio":true,"sents":[{"fr":"— Parce qu’un explorateur qui mentirait entraînerait des catastrophes dans les livres de géographie.","zh":"——因为一个撒谎的探险家会在地理书中引起灾难。","t":[100,6775]},{"fr":"Et aussi un explorateur qui boirait trop.","zh":"还有喝得太多的探险家。","t":[6775,9025]}]},{"id":"ch15p19","audio":true,"sents":[{"fr":"— Pourquoi ça ?","zh":"——为什么这样？","t":[100,2850]},{"fr":"fit le petit prince.","zh":"小王子说。","t":[2850,3888]}]},{"id":"ch15p20","audio":true,"sents":[{"fr":"— Parce que les ivrognes voient double.","zh":"——因为醉汉会看到双重的东西。","t":[100,3612]},{"fr":"Alors le géographe noterait deux montagnes, là où il n’y en a qu’une seule.","zh":"那么地理学家会记下两座山，而实际上只有一座。","t":[3612,7438]}]},{"id":"ch15p21","audio":true,"sents":[{"fr":"— Je connais quelqu’un, dit le petit prince, qui serait mauvais explorateur.","zh":"——我认识一个，小王子说，他是个糟糕的探险家。","t":[100,5237]}]},{"id":"ch15p22","audio":true,"sents":[{"fr":"— C’est possible.","zh":"——这是可能的。","t":[100,2850]},{"fr":"Donc, quand la moralité de l’explorateur paraît bonne, on fait une enquête sur sa découverte.","zh":"因此，当探险家的道德看起来很好时，我们会对他的发现进行调查。","t":[2850,8074]}]},{"id":"ch15p23","audio":true,"sents":[{"fr":"— On va voir ?","zh":"——我们去看看？","t":[100,2424]}]},{"id":"ch15p24","audio":true,"sents":[{"fr":"— Non.","zh":"——不。","t":[100,2350]},{"fr":"C’est trop compliqué.","zh":"这太复杂了。","t":[2350,4362]},{"fr":"Mais on exige de l’explorateur qu’il fournisse des preuves.","zh":"但是，我们要求探险家提供证据。","t":[4362,8175]},{"fr":"S’il s’agit par exemple de la découverte d’une grosse montagne, on exige qu’il en rapporte de grosses pierres.","zh":"如果比如说他发现了一座大山，我们要求他带来大石头。","t":[8175,13787]}]},{"id":"ch15p25","audio":true,"sents":[{"fr":"Le géographe soudain s’émut.","zh":"地理学家突然激动起来。","t":[100,1662]}]},{"id":"ch15p26","audio":true,"sents":[{"fr":"— Mais toi, tu viens de loin !","zh":"但你，你是从很远的地方来的！","t":[100,4300]},{"fr":"Tu es explorateur !","zh":"你是个探险家！","t":[4300,6975]},{"fr":"Tu vas me décrire ta planète !","zh":"你要给我描述一下你的星球！","t":[6975,9125]}]},{"id":"ch15p27","audio":true,"sents":[{"fr":"Et le géographe, ayant ouvert son registre, tailla son crayon.","zh":"地理学家打开了他的登记册，削了他的铅笔。","t":[100,4675]},{"fr":"On note d’abord au crayon les récits des explorateurs.","zh":"我们首先用铅笔记录探险家的故事。","t":[4675,8388]},{"fr":"On attend, pour noter à l’encre, que l’explorateur ait fourni des preuves.","zh":"我们等待，用墨水记录，直到探险家提供了证据。","t":[8388,12513]}]},{"id":"ch15p28","audio":true,"sents":[{"fr":"— Alors ?","zh":"那么？","t":[100,3162]},{"fr":"interrogea le géographe.","zh":"地理学家问道。","t":[3162,4512]}]},{"id":"ch15p29","audio":true,"sents":[{"fr":"— Oh !","zh":"哦！","t":[100,3038]},{"fr":"chez moi, dit le petit prince, ce n’est pas très intéressant, c’est tout petit.","zh":"在我的星球上，小王子说，那不是很有趣，它很小。","t":[3038,8300]},{"fr":"J’ai trois volcans.","zh":"我有三座火山。","t":[8300,10162]},{"fr":"Deux volcans en activité, et un volcan éteint.","zh":"两座活火山，一座死火山。","t":[10162,13762]},{"fr":"Mais on ne sait jamais.","zh":"但谁又能知道呢？","t":[13762,14787]}]},{"id":"ch15p30","audio":true,"sents":[{"fr":"— On ne sait jamais, dit le géographe.","zh":"——谁又能知道呢，地理学家说。","t":[100,3162]}]},{"id":"ch15p31","audio":true,"sents":[{"fr":"— J’ai aussi une fleur.","zh":"——我还有一朵花。","t":[100,2426]}]},{"id":"ch15p32","audio":true,"sents":[{"fr":"— Nous ne notons pas les fleurs, dit le géographe.","zh":"——我们不会记录花朵，地理学家说。","t":[100,3625]}]},{"id":"ch15p33","audio":true,"sents":[{"fr":"— Pourquoi ça !","zh":"——为什么啊！","t":[100,3388]},{"fr":"c’est le plus joli !","zh":"这是最美的！","t":[3388,5112]}]},{"id":"ch15p34","audio":true,"sents":[{"fr":"— Parce que les fleurs sont éphémères.","zh":"——因为花朵是短暂的。","t":[100,2824]}]},{"id":"ch15p35","audio":true,"sents":[{"fr":"— Qu’est ce que signifie : \"éphémère\" ?","zh":"——‘短暂’是什么意思？","t":[100,4550]}]},{"id":"ch15p36","audio":true,"sents":[{"fr":"— Les géographies, dit le géographe, sont les livres les plus précieux de tous les livres.","zh":"地理学，地理学家说，是所有书籍中最宝贵的。","t":[100,6412]},{"fr":"Elles ne se démodent jamais.","zh":"它们永远不会过时。","t":[6412,8512]},{"fr":"Il est très rare qu’une montagne change de place.","zh":"山改变位置是非常罕见的。","t":[8512,11700]},{"fr":"Il est très rare qu’un océan se vide de son eau.","zh":"海洋的水被排空是非常罕见的。","t":[11700,14750]},{"fr":"Nous écrivons des choses éternelles.","zh":"我们写下永恒的事物。","t":[14750,16663]}]},{"id":"ch15p37","audio":true,"sents":[{"fr":"— Mais les volcans éteints peuvent se réveiller, interrompit le petit prince.","zh":"但是熄灭的火山可以苏醒，小王子打断说。","t":[100,5738]},{"fr":"Qu’est-ce que signifie \"éphémère\" ?","zh":"‘短暂’是什么意思？","t":[5738,8088]}]},{"id":"ch15p38","audio":true,"sents":[{"fr":"— Que les volcans soient éteints ou soient éveillés, ça revient au même pour nous autres, dit le géographe.","zh":"无论是火山熄灭还是苏醒，对我们来说都一样，地理学家说。","t":[100,6988]},{"fr":"Ce qui compte pour nous, c’est la montagne.","zh":"对我们来说，重要的是山。","t":[6988,10125]},{"fr":"Elle ne change pas.","zh":"它不会改变。","t":[10125,10976]}]},{"id":"ch15p39","audio":true,"sents":[{"fr":"— Mais qu’est-ce que signifie \"éphémère\" ?","zh":"但‘短暂’是什么意思？","t":[100,4550]},{"fr":"répéta le petit prince qui, de sa vie, n’avait renoncé à une question, une fois qu’il l’avait posée.","zh":"小王子重复道，他一生中一旦提出一个问题，就绝不会放弃。","t":[4550,10188]}]},{"id":"ch15p40","audio":true,"sents":[{"fr":"— Ça signifie \"qui est menacé de disparition prochaine\".","zh":"这意味着‘即将消失’。","t":[100,4100]}]},{"id":"ch15p41","audio":true,"sents":[{"fr":"— Ma fleur est menacée de disparition prochaine ?","zh":"我的花即将消失？","t":[100,4013]}]},{"id":"ch15p42","audio":true,"sents":[{"fr":"— Bien sûr.","zh":"当然。","t":[100,1874]}]},{"id":"ch15p43","audio":true,"sents":[{"fr":"Ma fleur est éphémère, se dit le petit prince, et elle n’a que quatre épines pour se défendre contre le monde !","zh":"我的花是短暂的，小王子说，而且它只有四根刺来保护自己免受世界的伤害！","t":[100,7125]},{"fr":"Et je l’ai laissée toute seule chez moi !","zh":"而且我把它留在了家里！","t":[7125,9426]}]},{"id":"ch15p44","audio":true,"sents":[{"fr":"Ce fut là son premier mouvement de regret.","zh":"这是他第一次感到后悔。","t":[100,2900]},{"fr":"Mais il reprit courage :","zh":"但他又振作起来：","t":[2900,4826]}]},{"id":"ch15p45","audio":true,"sents":[{"fr":"— Que me conseillez-vous d’aller visiter ?","zh":"您建议我去参观哪里？","t":[100,3912]},{"fr":"demanda-t-il.","zh":"他问道。","t":[3912,4762]}]},{"id":"ch15p46","audio":true,"sents":[{"fr":"— La planète Terre, lui répondit le géographe.","zh":"——地球，地理学家回答。","t":[100,4762]},{"fr":"Elle a une bonne réputation…","zh":"它有着很好的名声……","t":[4762,6188]}]},{"id":"ch15p47","audio":true,"sents":[{"fr":"Et le petit prince s’en fut, songeant à sa fleur.","zh":"小王子于是离开了，心里想着他的玫瑰。","t":[100,2850]}]},{"id":"ch15p48","audio":true,"sents":[]}]},{"id":"ch16","title_fr":"Chapitre XVI","title_zh":"第 16 章","paras":[{"id":"ch16p00","audio":true,"sents":[]},{"id":"ch16p01","audio":true,"sents":[{"fr":"La septième planète fut donc la Terre.","zh":"第七颗星球因此是地球。","t":[100,2212]}]},{"id":"ch16p02","audio":true,"sents":[{"fr":"La Terre n’est pas une planète quelconque !","zh":"地球不是一颗普通的星球！","t":[100,3525]},{"fr":"On y compte cent onze rois (en n’oubliant pas, bien sûr, les rois nègres), sept mille géographes, neuf cent mille businessmen, sept millions et demi d’ivrognes, trois cent onze millions de vaniteux, c’est-à-dire environ deux milliards de grandes personnes.","zh":"在那里，有111个国王（当然，别忘了黑人国王），7000个地理学家，900000个商人，7500000个酒鬼，310000000个爱慕虚荣的人，也就是说大约有20亿的大人。","t":[3525,17075]}]},{"id":"ch16p03","audio":true,"sents":[{"fr":"Pour vous donner une idée des dimensions de la Terre je vous dirai qu’avant l’invention de l’électricité on y devait entretenir, sur l’ensemble des six continents, une véritable armée de quatre cent soixante-deux mille cinq cent onze allumeurs de réverbères.","zh":"为了给您一个地球大小的概念，我会告诉您，在电发明之前，在六大洲上，需要维持一支由4602115个路灯点亮者的真正军队。","t":[100,11913]}]},{"id":"ch16p04","audio":true,"sents":[{"fr":"Vu d’un peu loin ça faisait un effet splendide.","zh":"从远处看，这景象非常壮观。","t":[100,3375]},{"fr":"Les mouvements de cette armée étaient réglés comme ceux d’un ballet d’opéra.","zh":"这支军队的动作就像歌剧芭蕾舞团的舞蹈一样整齐。","t":[3375,7925]},{"fr":"D’abord venait le tour des allumeurs de réverbères de Nouvelle-Zélande et d’Australie.","zh":"首先上场的是新西兰和澳大利亚的路灯点亮者。","t":[7925,12500]},{"fr":"Puis ceux-ci, ayant allumé leurs lampions, s’en allaient dormir.","zh":"他们点亮了灯笼后，就去睡觉了。","t":[12500,16788]},{"fr":"Alors entraient à leur tour dans la danse les allumeurs de réverbères de Chine et de Sibérie.","zh":"接着是中国的和西伯利亚的路灯点亮者加入舞蹈。","t":[16788,21875]},{"fr":"Puis eux aussi s’escamotaient dans les coulisses.","zh":"然后他们也悄悄地躲进了后台。","t":[21875,24862]},{"fr":"Alors venait le tour des allumeurs de réverbères de Russie et des Indes.","zh":"接下来是俄罗斯和印度的路灯点亮者。","t":[24862,29375]},{"fr":"Puis de ceux d’Afrique et d’Europe.","zh":"然后是非洲和欧洲的。","t":[29375,31750]},{"fr":"Puis de ceux d’Amérique du Sud.","zh":"接着是南美洲的。","t":[31750,34212]},{"fr":"Puis de ceux d’Amérique du Nord.","zh":"最后是北美洲的。","t":[34212,36612]},{"fr":"Et jamais ils ne se trompaient dans leur ordre d’entrée en scène.","zh":"他们从未在出场顺序上出错。","t":[36612,40138]},{"fr":"C’était grandiose.","zh":"这是宏伟的。","t":[40138,41200]}]},{"id":"ch16p05","audio":true,"sents":[{"fr":"Seuls, l’allumeur de l’unique réverbère du pôle Nord, et son confrère de l’unique réverbère du pôle Sud, menaient des vies d’oisiveté et de nonchalance : ils travaillaient deux fois par an.","zh":"只有北极唯一灯塔的守灯人和南极唯一灯塔的同行，过着悠闲和懒散的生活：他们一年只工作两次。","t":[100,10625]}]},{"id":"ch16p06","audio":true,"sents":[]},{"id":"ch16p07","audio":true,"sents":[]}]},{"id":"ch17","title_fr":"Chapitre XVII","title_zh":"第 17 章","paras":[{"id":"ch17p00","audio":true,"sents":[{"fr":"Quand on veut faire de l’esprit, il arrive que l’on mente un peu.","zh":"当人们想要显示机智时，有时会稍微撒个小谎。","t":[100,4012]},{"fr":"Je n’ai pas été très honnête en vous parlant des allumeurs de réverbères.","zh":"我在跟你们谈论灯塔守灯人时并不诚实。","t":[4012,8375]},{"fr":"Je risque de donner une fausse idée de notre planète à ceux qui ne la connaissent pas.","zh":"我可能会给那些不了解我们星球的人一个错误的印象。","t":[8375,13000]},{"fr":"Les hommes occupent très peu de place sur la terre.","zh":"人类在地球上占据的空间非常小。","t":[13000,16312]},{"fr":"Si les deux milliards d’habitants qui peuplent la terre se tenaient debout et un peu serrés, comme pour un meeting, ils logeraient aisément sur une place publique de vingt milles de long sur vingt milles de large.","zh":"如果地球上二十亿居民站得紧凑一些，就像开大会一样，他们可以轻松地住在二十英里长、二十英里宽的公共场所。","t":[16312,26325]},{"fr":"On pourrait entasser l’humanité sur le moindre petit îlot du Pacifique.","zh":"人们可以把整个人类挤在太平洋上最小的岛屿上。","t":[26325,29912]}]},{"id":"ch17p01","audio":true,"sents":[{"fr":"Les grandes personnes, bien sûr, ne vous croiront pas.","zh":"当然，大人们是不会相信你们的。","t":[100,4038]},{"fr":"Elles s’imaginent tenir beaucoup de place.","zh":"他们想象自己占据了很大的空间。","t":[4038,7025]},{"fr":"Elles se voient importantes comme des baobabs.","zh":"他们把自己看得像猴面包树一样重要。","t":[7025,10050]},{"fr":"Vous leur conseillerez donc de faire le calcul.","zh":"所以你们就建议他们计算一下。","t":[10050,13312]},{"fr":"Elles adorent les chiffres : ça leur plaira.","zh":"他们喜欢数字：这会让他们很高兴。","t":[13312,16950]},{"fr":"Mais ne perdez pas votre temps à ce pensum.","zh":"但不要浪费时间去想这些。","t":[16950,19962]},{"fr":"C’est inutile.","zh":"这是没有用的。","t":[19962,21825]},{"fr":"Vous avez confiance en moi.","zh":"你相信我。","t":[21825,23200]}]},{"id":"ch17p02","audio":true,"sents":[{"fr":"Le petit prince, une fois sur terre, fut donc bien surpris de ne voir personne.","zh":"小王子一踏上地球，就惊讶地发现这里没有人。","t":[100,5662]},{"fr":"Il avait déjà peur de s’être trompé de planète, quand un anneau couleur de lune remua dans le sable.","zh":"他已经害怕自己选错了星球，就在这时，一个像月亮一样颜色的光环在沙子里动了起来。","t":[5662,10800]}]},{"id":"ch17p03","audio":true,"sents":[{"fr":"— Bonne nuit, fit le petit prince à tout hasard.","zh":"——晚安，小王子随便地说。","t":[100,3637]}]},{"id":"ch17p04","audio":true,"sents":[{"fr":"— Bonne nuit, fit le serpent.","zh":"——晚安，蛇说。","t":[100,2650]}]},{"id":"ch17p05","audio":true,"sents":[{"fr":"— Sur quelle planète suis-je tombé ?","zh":"——我落在哪个星球上了？","t":[100,3688]},{"fr":"demanda le petit prince.","zh":"小王子问道。","t":[3688,4963]}]},{"id":"ch17p06","audio":true,"sents":[{"fr":"— Sur la Terre, en Afrique, répondit le serpent.","zh":"——在地球上，在非洲，蛇回答说。","t":[100,4025]}]},{"id":"ch17p07","audio":true,"sents":[{"fr":"— Ah !…","zh":"——啊！……","t":[100,3038]},{"fr":"Il n’y a donc personne sur la Terre ?","zh":"所以地球上没有人吗？","t":[3038,5425]}]},{"id":"ch17p08","audio":true,"sents":[{"fr":"— Ici c’est le désert.","zh":"——这里是一片沙漠。","t":[100,3162]},{"fr":"Il n’y a personne dans les déserts.","zh":"在沙漠里没有人。","t":[3162,5700]},{"fr":"La Terre est grande, dit le serpent.","zh":"地球很大，蛇说。","t":[5700,7563]}]},{"id":"ch17p09","audio":true,"sents":[{"fr":"Le petit prince s’assit sur une pierre et leva les yeux vers le ciel :","zh":"小王子坐在一块石头上，抬头望向天空：","t":[100,3750]}]},{"id":"ch17p10","audio":true,"sents":[{"fr":"— Je me demande, dit-il, si les étoiles sont éclairées afin que chacun puisse un jour retrouver la sienne.","zh":"——我想，他说，星星是否被点亮，以便每个人都能有一天找到自己的那颗。","t":[100,7638]},{"fr":"Regarde ma planète.","zh":"看看我的星球。","t":[7638,9938]},{"fr":"Elle est juste au-dessus de nous…","zh":"它就在我们上方……","t":[9938,12125]},{"fr":"Mais comme elle est loin !","zh":"但它是那么遥远！","t":[12125,13813]}]},{"id":"ch17p11","audio":true,"sents":[{"fr":"— Elle est belle, dit le serpent.","zh":"——它很美，蛇说。","t":[100,3538]},{"fr":"Que viens-tu faire ici ?","zh":"你在这里做什么？","t":[3538,5375]}]},{"id":"ch17p12","audio":true,"sents":[{"fr":"— J’ai des difficultés avec une fleur, dit le petit prince.","zh":"——我遇到了一朵花的麻烦，小王子说。","t":[100,4362]}]},{"id":"ch17p13","audio":true,"sents":[{"fr":"— Ah !","zh":"——啊！","t":[100,2488]},{"fr":"fit le serpent.","zh":"蛇走了。","t":[2488,3224]}]},{"id":"ch17p14","audio":true,"sents":[{"fr":"Et ils se turent.","zh":"他们沉默了。","t":[100,925]}]},{"id":"ch17p15","audio":true,"sents":[{"fr":"— Où sont les hommes ?","zh":"——人在哪里？","t":[100,2862]},{"fr":"reprit enfin le petit prince.","zh":"小王子终于又开口了。","t":[2862,5175]},{"fr":"On est un peu seul dans le désert…","zh":"我们在沙漠里有点孤单……","t":[5175,6876]}]},{"id":"ch17p16","audio":true,"sents":[{"fr":"— On est seul aussi chez les hommes, dit le serpent.","zh":"——人在人类那里也是孤单的，蛇说。","t":[100,3500]}]},{"id":"ch17p17","audio":true,"sents":[{"fr":"Le petit prince le regarda longtemps :","zh":"小王子久久地看了他一眼：","t":[100,2812]}]},{"id":"ch17p18","audio":true,"sents":[{"fr":"— Tu es une drôle de bête, lui dit-il enfin, mince comme un doigt…","zh":"——你真是个奇怪的动物，他终于说，瘦得像根手指……","t":[100,4662]}]},{"id":"ch17p19","audio":true,"sents":[{"fr":"— Mais je suis plus puissant que le doigt d’un roi, dit le serpent.","zh":"——但我比国王的手指更有力量，蛇说。","t":[100,4087]}]},{"id":"ch17p20","audio":true,"sents":[{"fr":"Le petit prince eut un sourire :","zh":"小王子笑了：","t":[100,2288]}]},{"id":"ch17p21","audio":true,"sents":[{"fr":"— Tu n’es pas bien puissant…","zh":"你并不强大……","t":[100,2462]},{"fr":"tu n’as même pas de pattes…","zh":"你甚至没有脚……","t":[2462,3750]},{"fr":"tu ne peux même pas voyager…","zh":"你甚至不能旅行……","t":[3750,5063]}]},{"id":"ch17p22","audio":true,"sents":[{"fr":"— Je puis t’emporter plus loin qu’un navire, dit le serpent.","zh":"我说，我能带你比船更远。","t":[100,4025]}]},{"id":"ch17p23","audio":true,"sents":[{"fr":"Il s’enroula autour de la cheville du petit prince, comme un bracelet d’or :","zh":"它绕着小王子的脚踝缠绕，就像一条金手镯：","t":[100,4587]}]},{"id":"ch17p24","audio":true,"sents":[{"fr":"— Celui que je touche, je le rends à la terre dont il est sorti, dit-il encore.","zh":"我说，我触摸到的，我会让它回到它起源的星球……","t":[100,6125]},{"fr":"Mais tu es pur et tu viens d’une étoile…","zh":"但你纯洁，你来自一颗星星……","t":[6125,8038]}]},{"id":"ch17p25","audio":true,"sents":[{"fr":"Le petit prince ne répondit rien.","zh":"小王子没有回答。","t":[100,1937]}]},{"id":"ch17p26","audio":true,"sents":[{"fr":"— Tu me fais pitié, toi si faible, sur cette Terre de granit.","zh":"你太弱了，在这个花岗岩地球上，真让人同情。","t":[100,5588]},{"fr":"Je puis t’aider un jour si tu regrettes trop ta planète.","zh":"如果你太怀念你的星球，我有一天可以帮你。","t":[5588,9262]},{"fr":"Je puis…","zh":"我能够……","t":[9262,9950]}]},{"id":"ch17p27","audio":true,"sents":[{"fr":"— Oh !","zh":"——哦！","t":[100,3038]},{"fr":"J’ai très bien compris, fit le petit prince, mais pourquoi parles-tu toujours par énigmes ?","zh":"我完全明白了，小王子说，但你为什么总是用谜语来说话？","t":[3038,8362]}]},{"id":"ch17p28","audio":true,"sents":[{"fr":"— Je les résous toutes, dit le serpent.","zh":"——我解决了它们所有，蛇说。","t":[100,3037]}]},{"id":"ch17p29","audio":true,"sents":[{"fr":"Et ils se turent.","zh":"然后他们沉默了。","t":[100,925]}]},{"id":"ch17p30","audio":true,"sents":[]}]},{"id":"ch18","title_fr":"Chapitre XVIII","title_zh":"第 18 章","paras":[{"id":"ch18p00","audio":true,"sents":[{"fr":"Le petit prince traversa le désert et ne rencontra qu'une fleur.","zh":"小王子穿过沙漠，只遇见了一朵花。","t":[100,4300]},{"fr":"Une fleur à trois pétales, une fleur de rien du tout...","zh":"一朵三瓣的花，一朵微不足道的小花……","t":[4300,7150]}]},{"id":"ch18p01","audio":true,"sents":[{"fr":"— Bonjour, dit le petit prince.","zh":"——你好。小王子说。","t":[100,2063]}]},{"id":"ch18p02","audio":true,"sents":[{"fr":"— Bonjour, dit la fleur.","zh":"——你好。花说。","t":[100,1787]}]},{"id":"ch18p03","audio":true,"sents":[{"fr":"— Où sont les hommes ? demanda poliment le petit prince.","zh":"——人在哪里？小王子有礼貌地问道。","t":[100,2837]}]},{"id":"ch18p04","audio":true,"sents":[{"fr":"La fleur, un jour, avait vu passer une caravane :","zh":"花有一天曾看见一支商队经过：","t":[100,3275]}]},{"id":"ch18p05","audio":true,"sents":[{"fr":"— Les hommes ? Il en existe, je crois, six ou sept.","zh":"——人吗？我想，大约有六七个吧。","t":[100,5150]},{"fr":"Je les ai aperçus il y a des années.","zh":"几年前我曾瞅见过他们。","t":[5150,7862]},{"fr":"Mais on ne sait jamais où les trouver.","zh":"可是，从来不知道到什么地方去找他们。","t":[7862,10400]},{"fr":"Le vent les promène.","zh":"风把他们吹得到处飘荡。","t":[10400,12325]},{"fr":"Ils manquent de racines, ça les gêne beaucoup.","zh":"他们没有根，这对他们来说很不方便。","t":[12325,14800]}]},{"id":"ch18p06","audio":true,"sents":[{"fr":"— Adieu, fit le petit prince.","zh":"——再见。小王子说。","t":[100,1825]}]},{"id":"ch18p07","audio":true,"sents":[{"fr":"— Adieu, dit la fleur.","zh":"——再见。花说。","t":[100,1550]}]}]},{"id":"ch19","title_fr":"Chapitre XIX","title_zh":"第 19 章","paras":[{"id":"ch19p00","audio":true,"sents":[]},{"id":"ch19p01","audio":true,"sents":[{"fr":"Le petit prince fit l’ascension d’une haute montagne.","zh":"小王子攀登了一座高山。","t":[100,3425]},{"fr":"Les seules montagnes qu’il eût jamais connues étaient les trois volcans qui lui arrivaient au genou.","zh":"他曾经知道的唯一山峰是那三座火山，它们一直延伸到他的膝盖。","t":[3425,8325]},{"fr":"Et il se servait du volcan éteint comme d’un tabouret.","zh":"他把自己当成了火山喷发时的一把椅子。","t":[8325,11650]},{"fr":"\"D’une montagne haute comme celle-ci, se dit-il donc, j’apercevrai d’un coup toute la planète et tous les hommes…\" Mais il n’aperçut rien que des aiguilles de roc bien aiguisées.","zh":"从这么高的山上，他自言自语道，我一下子就能看到整个星球和所有的人……但他看到的只是一些尖锐的岩石针。","t":[11650,21150]}]},{"id":"ch19p02","audio":true,"sents":[{"fr":"— Bonjour, dit-il à tout hasard.","zh":"——你好，他随便地说。","t":[100,3150]}]},{"id":"ch19p03","audio":true,"sents":[{"fr":"— Bonjour…","zh":"——你好……","t":[100,2700]},{"fr":"Bonjour…","zh":"你好……","t":[2700,4312]},{"fr":"Bonjour…","zh":"你好……","t":[4312,5238]},{"fr":"répondit l’écho.","zh":"回声回答。","t":[5238,6200]}]},{"id":"ch19p04","audio":true,"sents":[{"fr":"— Qui êtes-vous ?","zh":"——你是谁？","t":[100,2812]},{"fr":"dit le petit prince.","zh":"小王子说。","t":[2812,3800]}]},{"id":"ch19p05","audio":true,"sents":[{"fr":"— Qui êtes-vous…","zh":"——你是谁……","t":[100,2088]},{"fr":"qui êtes-vous…","zh":"你是谁……","t":[2088,2888]},{"fr":"qui êtes-vous…","zh":"你是谁……","t":[2888,3762]},{"fr":"répondit l’écho.","zh":"回声回答说。","t":[3762,4687]}]},{"id":"ch19p06","audio":true,"sents":[{"fr":"— Soyez mes amis, je suis seul, dit-il.","zh":"——&nbsp;请成为我的朋友，我是孤独的，他说。","t":[100,3650]}]},{"id":"ch19p07","audio":true,"sents":[{"fr":"— Je suis seul…","zh":"——&nbsp;我是孤独的……","t":[100,2125]},{"fr":"je suis seul…","zh":"我是孤独的……","t":[2125,2988]},{"fr":"je suis seul…","zh":"我是孤独的……","t":[2988,3912]},{"fr":"répondit l’écho.","zh":"回声回答说。","t":[3912,4800]}]},{"id":"ch19p08","audio":true,"sents":[{"fr":"\"Quelle drôle de planète !","zh":"这是个多么奇怪的星球啊！","t":[100,2175]},{"fr":"pensa-t-il alors.","zh":"他想。","t":[2175,4075]},{"fr":"Elle est toute sèche, et toute pointue et toute salée.","zh":"它又干又尖又咸。","t":[4075,7538]},{"fr":"Et les hommes manquent d’imagination.","zh":"人们缺乏想象力。","t":[7538,10100]},{"fr":"Ils répètent ce qu’on leur dit…","zh":"他们重复别人告诉他们的话……","t":[10100,12450]},{"fr":"Chez moi j’avais une fleur : elle parlait toujours la première…\"","zh":"在我家里，我有一朵花：她总是先说话……","t":[12450,16062]}]},{"id":"ch19p09","audio":true,"sents":[]},{"id":"ch19p10","audio":true,"sents":[]}]},{"id":"ch20","title_fr":"Chapitre XX","title_zh":"第 20 章","paras":[{"id":"ch20p00","audio":true,"sents":[{"fr":"Mais il arriva que le petit prince, ayant longtemps marché à travers les sables, les rocs et les neiges, découvrit enfin une route.","zh":"但是，小王子在穿越了沙丘、岩石和冰雪之后，终于发现了一条道路。","t":[100,7800]},{"fr":"Et les routes vont toutes chez les hommes.","zh":"所有的道路都通往人类。","t":[7800,9400]}]},{"id":"ch20p01","audio":true,"sents":[{"fr":"— Bonjour, dit-il.","zh":"——你好，他说。","t":[100,2562]}]},{"id":"ch20p02","audio":true,"sents":[{"fr":"C’était un jardin fleuri de roses.","zh":"那是一个开满玫瑰的花园。","t":[100,1887]}]},{"id":"ch20p03","audio":true,"sents":[{"fr":"— Bonjour, dirent les roses.","zh":"——你好，玫瑰们说。","t":[100,2763]}]},{"id":"ch20p04","audio":true,"sents":[{"fr":"Le petit prince les regarda.","zh":"小王子看着他们。","t":[100,2562]},{"fr":"Elles ressemblaient toutes à sa fleur.","zh":"她们都像他自己的花。","t":[2562,4250]}]},{"id":"ch20p05","audio":true,"sents":[{"fr":"— Qui êtes-vous ?","zh":"——你是谁？","t":[100,3388]},{"fr":"leur demanda-t-il, stupéfait.","zh":"他惊讶地问道。","t":[3388,5488]}]},{"id":"ch20p06","audio":true,"sents":[{"fr":"— Nous sommes des roses, dirent les roses.","zh":"——我们是玫瑰，玫瑰们说。","t":[100,3075]}]},{"id":"ch20p07","audio":true,"sents":[{"fr":"— Ah !","zh":"——啊！","t":[100,2462]},{"fr":"fit le petit prince…","zh":"小王子说道……","t":[2462,3475]}]},{"id":"ch20p08","audio":true,"sents":[{"fr":"Et il se sentit très malheureux.","zh":"他感到非常难过。","t":[100,2375]},{"fr":"Sa fleur lui avait raconté qu’elle était seule de son espèce dans l’univers.","zh":"他的花曾告诉他，她是宇宙中唯一的一种。","t":[2375,6875]},{"fr":"Et voici qu’il en était cinq mille, toutes semblables, dans un seul jardin !","zh":"结果发现，在同一个花园里就有五千朵，都一模一样！","t":[6875,11274]}]},{"id":"ch20p09","audio":true,"sents":[{"fr":"\"Elle serait bien vexée, se dit-il, si elle voyait ça…","zh":"他想，如果她看到这个，她会非常生气的...","t":[100,3612]},{"fr":"elle tousserait énormément et ferait semblant de mourir pour échapper au ridicule.","zh":"她会剧烈咳嗽，并假装死去以避免出丑。","t":[3612,8275]},{"fr":"Et je serais bien obligé de faire semblant de la soigner, car, sinon, pour m’humilier moi aussi, elle se laisserait vraiment mourir…\"","zh":"而我将不得不假装照顾她，因为不然的话，为了羞辱我，她真的会让自己死去...","t":[8275,15462]}]},{"id":"ch20p10","audio":true,"sents":[{"fr":"Puis il se dit encore : \"Je me croyais riche d’une fleur unique, et je ne possède qu’une rose ordinaire.","zh":"然后他又对自己说：\"我曾以为自己拥有一朵独一无二的花，而我只有一朵普通的玫瑰。\"","t":[100,6912]},{"fr":"Ça et mes trois volcans qui m’arrivent au genou, et dont l’un, peut-être, est éteint pour toujours, ça ne fait pas de moi un bien grand prince…\" Et, couché dans l’herbe, il pleura.","zh":"这些和我那三个齐膝高的火山，其中一座也许已经永远熄灭了，这些并不能使我成为一个伟大的王子...\"他躺在草地上，哭了。","t":[6912,16963]}]},{"id":"ch20p11","audio":true,"sents":[]}]},{"id":"ch21","title_fr":"Chapitre XXI","title_zh":"第 21 章","paras":[{"id":"ch21p00","audio":true,"sents":[]},{"id":"ch21p01","audio":true,"sents":[{"fr":"C’est alors qu’apparut le renard :","zh":"就在这时，狐狸出现了：","t":[100,2338]}]},{"id":"ch21p02","audio":true,"sents":[{"fr":"— Bonjour, dit le renard.","zh":"— 你好，\"狐狸说。","t":[100,2837]}]},{"id":"ch21p03","audio":true,"sents":[{"fr":"— Bonjour, répondit poliment le petit prince, qui se retourna mais ne vit rien.","zh":"— 你好，\"小王子礼貌地回答，他转过身却什么也没看见。","t":[100,5600]}]},{"id":"ch21p04","audio":true,"sents":[{"fr":"— Je suis là, dit la voix, sous le pommier.","zh":"我在梨树下，声音说。","t":[100,3450]}]},{"id":"ch21p05","audio":true,"sents":[{"fr":"— Qui es-tu ?","zh":"你是谁？","t":[100,2762]},{"fr":"dit le petit prince.","zh":"小王子说。","t":[2762,4612]},{"fr":"Tu es bien joli…","zh":"你真漂亮……","t":[4612,5587]}]},{"id":"ch21p06","audio":true,"sents":[{"fr":"— Je suis un renard, dit le renard.","zh":"我是只狐狸，狐狸说。","t":[100,3112]}]},{"id":"ch21p07","audio":true,"sents":[{"fr":"— Viens jouer avec moi, lui proposa le petit prince.","zh":"来和我一起玩吧，小王子提议。","t":[100,5025]},{"fr":"Je suis tellement triste…","zh":"我太伤心了……","t":[5025,6313]}]},{"id":"ch21p08","audio":true,"sents":[{"fr":"— Je ne puis pas jouer avec toi, dit le renard.","zh":"我不能和你一起玩，狐狸说。","t":[100,4475]},{"fr":"Je ne suis pas apprivoisé.","zh":"我没有被驯服。","t":[4475,5875]}]},{"id":"ch21p09","audio":true,"sents":[{"fr":"— Ah !","zh":"啊！","t":[100,3038]},{"fr":"pardon, fit le petit prince.","zh":"对不起，小王子说。","t":[3038,4863]}]},{"id":"ch21p10","audio":true,"sents":[{"fr":"Mais, après réflexion, il ajouta :","zh":"但是，经过思考，他又补充道：","t":[100,3263]}]},{"id":"ch21p11","audio":true,"sents":[{"fr":"— Qu’est-ce que signifie \"apprivoiser\" ?","zh":"——什么是‘驯服’的意思？","t":[100,3588]}]},{"id":"ch21p12","audio":true,"sents":[{"fr":"— Tu n’es pas d’ici, dit le renard, que cherches-tu ?","zh":"——你不是这里的，狐狸说，你在找什么？","t":[100,4575]}]},{"id":"ch21p13","audio":true,"sents":[{"fr":"— Je cherche les hommes, dit le petit prince.","zh":"——我在找人类，小王子说。","t":[100,4362]},{"fr":"Qu’est-ce que signifie \"apprivoiser\" ?","zh":"什么是‘驯服’的意思？","t":[4362,6762]}]},{"id":"ch21p14","audio":true,"sents":[{"fr":"— Les hommes, dit le renard, ils ont des fusils et ils chassent.","zh":"——人类，狐狸说，他们有枪，他们会打猎。","t":[100,5225]},{"fr":"C’est bien gênant !","zh":"这真麻烦！","t":[5225,7688]},{"fr":"Ils élèvent aussi des poules.","zh":"他们也养鸡。","t":[7688,10012]},{"fr":"C’est leur seul intérêt.","zh":"这是他们唯一的兴趣。","t":[10012,12000]},{"fr":"Tu cherches des poules ?","zh":"你在找母鸡吗？","t":[12000,13612]}]},{"id":"ch21p15","audio":true,"sents":[{"fr":"— Non, dit le petit prince.","zh":"——不，小王子说。","t":[100,3662]},{"fr":"Je cherche des amis.","zh":"我在找朋友。","t":[3662,5700]},{"fr":"Qu’est-ce que signifie \"apprivoiser\" ?","zh":"‘驯服’是什么意思？","t":[5700,8100]}]},{"id":"ch21p16","audio":true,"sents":[{"fr":"— C’est une chose trop oubliée, dit le renard.","zh":"——这是一个被遗忘得太久的东西，狐狸说。","t":[100,4412]},{"fr":"Ça signifie \"créer des liens…\"","zh":"这意味着‘建立联系……’","t":[4412,6150]}]},{"id":"ch21p17","audio":true,"sents":[{"fr":"— Créer des liens ?","zh":"——建立联系？","t":[100,2750]}]},{"id":"ch21p18","audio":true,"sents":[{"fr":"— Bien sûr, dit le renard.","zh":"——当然，狐狸说。","t":[100,3762]},{"fr":"Tu n’es encore pour moi qu’un petit garçon tout semblable à cent mille petits garçons.","zh":"对你来说，你还是一个和成千上万个男孩一样的小男孩。","t":[3762,8425]},{"fr":"Et je n’ai pas besoin de toi.","zh":"而且我并不需要你。","t":[8425,10675]},{"fr":"Et tu n’as pas besoin de moi non plus.","zh":"你也不再需要我了。","t":[10675,13212]},{"fr":"Je ne suis pour toi qu’un renard semblable à cent mille renards.","zh":"对我来说，你不过是一只像成千上万只狐狸一样的狐狸。","t":[13212,17100]},{"fr":"Mais, si tu m’apprivoises, nous aurons besoin l’un de l’autre.","zh":"但是，如果你驯服了我，我们就会互相需要。","t":[17100,21388]},{"fr":"Tu seras pour moi unique au monde.","zh":"对你来说，你将是我世界上独一无二的存在。","t":[21388,23975]},{"fr":"Je serai pour toi unique au monde…","zh":"对我来说，你也将是我世界上独一无二的存在……","t":[23975,25763]}]},{"id":"ch21p19","audio":true,"sents":[{"fr":"— Je commence à comprendre, dit le petit prince.","zh":"——我开始明白了，小王子说。","t":[100,4688]},{"fr":"Il y a une fleur…","zh":"这里有一朵花……","t":[4688,5838]},{"fr":"je crois qu’elle m’a apprivoisé…","zh":"我相信她已经驯服了我……","t":[5838,7237]}]},{"id":"ch21p20","audio":true,"sents":[{"fr":"— C’est possible, dit le renard.","zh":"——这是可能的，狐狸说。","t":[100,3750]},{"fr":"On voit sur la Terre toutes sortes de choses…","zh":"在地球上，我们看到各种各样的东西……","t":[3750,5738]}]},{"id":"ch21p21","audio":true,"sents":[{"fr":"— Oh !","zh":"哦！","t":[100,3038]},{"fr":"ce n’est pas sur la Terre, dit le petit prince.","zh":"小王子说，这不是在地球上。","t":[3038,5525]}]},{"id":"ch21p22","audio":true,"sents":[{"fr":"Le renard parut très intrigué :","zh":"狐狸显得非常好奇：","t":[100,2575]}]},{"id":"ch21p23","audio":true,"sents":[{"fr":"— Sur une autre planète ?","zh":"在另一个星球上？","t":[100,2900]}]},{"id":"ch21p24","audio":true,"sents":[{"fr":"— Oui.","zh":"是的。","t":[100,1525]}]},{"id":"ch21p25","audio":true,"sents":[{"fr":"— Il y a des chasseurs, sur cette planète-là ?","zh":"在这个星球上，有猎人吗？","t":[100,4163]}]},{"id":"ch21p26","audio":true,"sents":[{"fr":"— Non.","zh":"不。","t":[100,1474]}]},{"id":"ch21p27","audio":true,"sents":[{"fr":"— Ça, c’est intéressant !","zh":"这很有趣！","t":[100,4188]},{"fr":"Et des poules ?","zh":"还有鸡呢？","t":[4188,5474]}]},{"id":"ch21p28","audio":true,"sents":[{"fr":"— Non.","zh":"不。","t":[100,1474]}]},{"id":"ch21p29","audio":true,"sents":[{"fr":"— Rien n’est parfait, soupira le renard.","zh":"没有什么完美，狐狸叹了口气。","t":[100,3500]}]},{"id":"ch21p30","audio":true,"sents":[{"fr":"Mais le renard revint à son idée :","zh":"但狐狸又回到了他的想法：","t":[100,2588]}]},{"id":"ch21p31","audio":true,"sents":[{"fr":"— Ma vie est monotone.","zh":"我的生活很单调。","t":[100,3212]},{"fr":"Je chasse les poules, les hommes me chassent.","zh":"我猎杀鸡，人又来猎杀我。","t":[3212,6350]},{"fr":"Toutes les poules se ressemblent, et tous les hommes se ressemblent.","zh":"所有的鸡都长得一样，所有的人也都长得一样。","t":[6350,10150]},{"fr":"Je m’ennuie donc un peu.","zh":"所以我有点无聊。","t":[10150,12375]},{"fr":"Mais, si tu m’apprivoises, ma vie sera comme ensoleillée.","zh":"但是，如果你驯服了我，我的生活就会像阳光一样明媚。","t":[12375,16600]},{"fr":"Je connaîtrai un bruit de pas qui sera différent de tous les autres.","zh":"我会知道一种不同于其他所有的脚步声。","t":[16600,20550]},{"fr":"Les autres pas me font rentrer sous terre.","zh":"其他的脚步声让我回到地下。","t":[20550,23438]},{"fr":"Le tien m’appellera hors du terrier, comme une musique.","zh":"你的脚步声会像音乐一样，将我叫出洞穴。","t":[23438,27150]},{"fr":"Et puis regarde !","zh":"然后你看！","t":[27150,29550]},{"fr":"Tu vois, là-bas, les champs de blé ?","zh":"你看到了吗，那里的麦田？","t":[29550,33338]},{"fr":"Je ne mange pas de pain.","zh":"我不吃面包。","t":[33338,35438]},{"fr":"Le blé pour moi est inutile.","zh":"对我来说，麦子是没有用的。","t":[35438,37988]},{"fr":"Les champs de blé ne me rappellent rien.","zh":"麦田没有让我想起什么。","t":[37988,40600]},{"fr":"Et ça, c’est triste !","zh":"这很悲哀！","t":[40600,43325]},{"fr":"Mais tu as des cheveux couleur d’or.","zh":"但是你的头发是金色的。","t":[43325,45862]},{"fr":"Alors ce sera merveilleux quand tu m’auras apprivoisé !","zh":"那么当你驯服我的时候，那将会是美妙的！","t":[45862,49950]},{"fr":"Le blé, qui est doré, me fera souvenir de toi.","zh":"金黄色的麦子会让我想起你。","t":[49950,53900]},{"fr":"Et j’aimerai le bruit du vent dans le blé…","zh":"我还喜欢风吹过麦田的声音……","t":[53900,55688]}]},{"id":"ch21p32","audio":true,"sents":[{"fr":"Le renard se tut et regarda longtemps le petit prince :","zh":"狐狸安静下来，长时间地看着小王子：","t":[100,3375]}]},{"id":"ch21p33","audio":true,"sents":[{"fr":"— S’il te plaît…","zh":"—— 请你……","t":[100,2038]},{"fr":"apprivoise-moi !","zh":"驯服我吧！","t":[2038,3725]},{"fr":"dit-il.","zh":"他说。","t":[3725,4250]}]},{"id":"ch21p34","audio":true,"sents":[{"fr":"— Je veux bien, répondit le petit prince, mais je n’ai pas beaucoup de temps.","zh":"—— 我愿意，小王子回答说，但我没有太多时间。","t":[100,5900]},{"fr":"J’ai des amis à découvrir et beaucoup de choses à connaître.","zh":"我还有朋友要发现，还有许多事情要了解。","t":[5900,8775]}]},{"id":"ch21p35","audio":true,"sents":[{"fr":"— On ne connaît que les choses que l’on apprivoise, dit le renard.","zh":"—— 只有人类驯服了的事物才是真正了解的，狐狸说。","t":[100,5088]},{"fr":"Les hommes n’ont plus le temps de rien connaître.","zh":"人们不再有时间去了解任何事物。","t":[5088,8112]},{"fr":"Ils achètent des choses toutes faites chez les marchands.","zh":"他们在商人那里购买现成的东西。","t":[8112,11225]},{"fr":"Mais comme il n’existe point de marchands d’amis, les hommes n’ont plus d’amis.","zh":"但是，因为没有朋友商人，人们再也没有朋友了。","t":[11225,15775]},{"fr":"Si tu veux un ami, apprivoise-moi !","zh":"如果你想有一个朋友，驯服我吧！","t":[15775,18437]}]},{"id":"ch21p36","audio":true,"sents":[{"fr":"— Que faut-il faire ?","zh":"——要做什么？","t":[100,2988]},{"fr":"dit le petit prince.","zh":"小王子说。","t":[2988,3988]}]},{"id":"ch21p37","audio":true,"sents":[{"fr":"— Il faut être très patient, répondit le renard.","zh":"——你必须要有耐心，狐狸回答说。","t":[100,4712]},{"fr":"Tu t’assoiras d’abord un peu loin de moi, comme ça, dans l’herbe.","zh":"你先坐得离我远一点，就像这样，在草地上。","t":[4712,8975]},{"fr":"Je te regarderai du coin de l’œil et tu ne diras rien.","zh":"我会用眼角瞥着你，而你什么也不要说。","t":[8975,12512]},{"fr":"Le langage est source de malentendus.","zh":"语言是误解的源头。","t":[12512,15362]},{"fr":"Mais, chaque jour, tu pourras t’asseoir un peu plus près…","zh":"但是，每天，你都可以坐得离我更近一点……","t":[15362,18450]}]},{"id":"ch21p38","audio":true,"sents":[{"fr":"Le lendemain revint le petit prince.","zh":"第二天，小王子回来了。","t":[100,1925]}]},{"id":"ch21p39","audio":true,"sents":[{"fr":"— Il eût mieux valu revenir à la même heure, dit le renard.","zh":"——你最好在那个时间回来，狐狸说。","t":[100,4988]},{"fr":"Si tu viens, par exemple, à quatre heures de l’après-midi, dès trois heures je commencerai d’être heureux.","zh":"如果你下午四点钟来，那么从三点钟起，我就开始感到幸福。","t":[4988,11162]},{"fr":"Plus l’heure avancera, plus je me sentirai heureux.","zh":"时间越接近四点，我就越感到快乐。","t":[11162,14625]},{"fr":"A quatre heures, déjà, je m’agiterai et m’inquiéterai ; je découvrirai le prix du bonheur !","zh":"到了四点钟，我就会坐立不安，我会发现幸福的代价！","t":[14625,21925]},{"fr":"Mais si tu viens n’importe quand, je ne saurai jamais à quelle heure m’habiller le cœur…","zh":"但是如果你随时来，我就不知道该什么时候让我的心准备好……","t":[21925,26762]},{"fr":"Il faut des rites.","zh":"需要有一些仪式。","t":[26762,27688]}]},{"id":"ch21p40","audio":true,"sents":[{"fr":"— Qu’est-ce qu’un rite ?","zh":"什么是仪式？","t":[100,2862]},{"fr":"dit le petit prince.","zh":"小王子说。","t":[2862,3850]}]},{"id":"ch21p41","audio":true,"sents":[{"fr":"— C’est aussi quelque chose de trop oublié, dit le renard.","zh":"这也是被遗忘的东西，狐狸说。","t":[100,5075]},{"fr":"C’est ce qui fait qu’un jour est différent des autres jours, une heure, des autres heures.","zh":"这是让一天不同于其他日子，一小时不同于其他小时的原因。","t":[5075,10188]},{"fr":"Il y a un rite, par exemple, chez mes chasseurs.","zh":"比如，在我的猎人那里就有一种仪式。","t":[10188,14025]},{"fr":"Ils dansent le jeudi avec les filles du village.","zh":"他们星期四和村里的女孩们跳舞。","t":[14025,17212]},{"fr":"Alors le jeudi est jour merveilleux !","zh":"所以星期四是个美好的日子！","t":[17212,20450]},{"fr":"Je vais me promener jusqu’à la vigne.","zh":"我将去葡萄园散步。","t":[20450,23138]},{"fr":"Si les chasseurs dansaient n’importe quand, les jours se ressembleraient tous, et je n’aurais point de vacances.","zh":"如果猎人随时跳舞，那么每一天都会相似，我就不会有假期了。","t":[23138,28463]}]},{"id":"ch21p42","audio":true,"sents":[{"fr":"Ainsi le petit prince apprivoisa le renard.","zh":"于是小王子驯服了狐狸。","t":[100,3150]},{"fr":"Et quand l’heure du départ fut proche :","zh":"当出发的时间临近时：","t":[3150,5338]}]},{"id":"ch21p43","audio":true,"sents":[{"fr":"— Ah !","zh":"——啊！","t":[100,2400]},{"fr":"dit le renard…","zh":"狐狸说……","t":[2400,4050]},{"fr":"Je pleurerai.","zh":"我会哭的。","t":[4050,4900]}]},{"id":"ch21p44","audio":true,"sents":[{"fr":"— C’est ta faute, dit le petit prince, je ne te souhaitais point de mal, mais tu as voulu que je t’apprivoise…","zh":"——这是你的错，小王子说，我并不希望你遭遇不幸，但你却想让我驯服你……","t":[100,6812]}]},{"id":"ch21p45","audio":true,"sents":[{"fr":"— Bien sûr, dit le renard.","zh":"当然，狐狸说。","t":[100,2900]}]},{"id":"ch21p46","audio":true,"sents":[{"fr":"— Mais tu vas pleurer !","zh":"但你一定会哭的！","t":[100,3212]},{"fr":"dit le petit prince.","zh":"小王子说。","t":[3212,4213]}]},{"id":"ch21p47","audio":true,"sents":[{"fr":"— Bien sûr, dit le renard.","zh":"当然，狐狸说。","t":[100,2900]}]},{"id":"ch21p48","audio":true,"sents":[{"fr":"— Alors tu n’y gagnes rien !","zh":"那么你得不到任何东西！","t":[100,3213]}]},{"id":"ch21p49","audio":true,"sents":[{"fr":"— J’y gagne, dit le renard, à cause de la couleur du blé.","zh":"我得到了，狐狸说，因为麦田的颜色。","t":[100,4437]}]},{"id":"ch21p50","audio":true,"sents":[{"fr":"Puis il ajouta :","zh":"然后他又说：","t":[100,1812]}]},{"id":"ch21p51","audio":true,"sents":[{"fr":"— Va revoir les roses.","zh":"去再看一看那些玫瑰。","t":[100,3150]},{"fr":"Tu comprendras que la tienne est unique au monde.","zh":"你会明白你的玫瑰是世界上独一无二的。","t":[3150,6312]},{"fr":"Tu reviendras me dire adieu, et je te ferai cadeau d’un secret.","zh":"你回来向我告别，我会给你一个秘密作为礼物。","t":[6312,9576]}]},{"id":"ch21p52","audio":true,"sents":[{"fr":"Le petit prince s’en fut revoir les roses :","zh":"小王子又去看他的玫瑰：","t":[100,2737]}]},{"id":"ch21p53","audio":true,"sents":[{"fr":"— Vous n’êtes pas du tout semblables à ma rose, vous n’êtes rien encore, leur dit-il.","zh":"——你们和我那朵玫瑰一点也不像，你们什么也不是，他对它们说。","t":[100,6350]},{"fr":"Personne ne vous a apprivoisé et vous n’avez apprivoisé personne.","zh":"没有人驯服过你们，你们也没有驯服过任何人。","t":[6350,10350]},{"fr":"Vous êtes comme était mon renard.","zh":"你们就像我的狐狸。","t":[10350,12812]},{"fr":"Ce n’était qu’un renard semblable à cent mille autres.","zh":"那只是一只像成千上万只狐狸一样的狐狸。","t":[12812,16100]},{"fr":"Mais j’en ai fait mon ami, et il est maintenant unique au monde.","zh":"但是，我已经把它变成了我的朋友，现在它是世界上独一无二的。","t":[16100,19125]}]},{"id":"ch21p54","audio":true,"sents":[{"fr":"Et les roses étaient bien gênées.","zh":"而那些玫瑰感到非常尴尬。","t":[100,1475]}]},{"id":"ch21p55","audio":true,"sents":[{"fr":"— Vous êtes belles, mais vous êtes vides, leur dit-il encore.","zh":"——你们很美，但是你们是空虚的，他又对它们说。","t":[100,5238]},{"fr":"On ne peut pas mourir pour vous.","zh":"人们不会为你们而死。","t":[5238,7475]},{"fr":"Bien sûr, ma rose à moi, un passant ordinaire croirait qu’elle vous ressemble.","zh":"当然，我的玫瑰，一个普通的路人会认为她和你很像。","t":[7475,12600]},{"fr":"Mais à elle seule elle est plus importante que vous toutes, puisque c’est elle que j’ai arrosée.","zh":"但她对我来说比你们所有人都重要，因为是她，我给她浇过水。","t":[12600,17688]},{"fr":"Puisque c’est elle que j’ai mise sous globe.","zh":"因为是她，我给她罩上了玻璃罩。","t":[17688,20625]},{"fr":"Puisque c’est elle que j’ai abritée par le paravent.","zh":"因为是她，我用屏风保护过她。","t":[20625,23912]},{"fr":"Puisque c’est elle dont j’ai tué les chenilles (sauf les deux ou trois pour les papillons).","zh":"因为是她，我消灭了毛毛虫（除了两三个为了变成蝴蝶的）。","t":[23912,28838]},{"fr":"Puisque c’est elle que j’ai écoutée se plaindre, ou se vanter, ou même quelquefois se taire.","zh":"因为是她，我听她抱怨，或者炫耀，甚至有时听她沉默。","t":[28838,34288]},{"fr":"Puisque c’est ma rose.","zh":"因为是她，是我的玫瑰。","t":[34288,35450]}]},{"id":"ch21p56","audio":true,"sents":[{"fr":"Et il revint vers le renard :","zh":"然后他又回到了狐狸那里：","t":[100,2125]}]},{"id":"ch21p57","audio":true,"sents":[{"fr":"— Adieu, dit-il…","zh":"—— 再见，他说……","t":[100,2262]}]},{"id":"ch21p58","audio":true,"sents":[{"fr":"— Adieu, dit le renard.","zh":"—— 再见，狐狸说。","t":[100,3462]},{"fr":"Voici mon secret.","zh":"这是我的秘密。","t":[3462,5362]},{"fr":"Il est très simple : on ne voit bien qu’avec le cœur.","zh":"它非常简单：用心灵才能看清。","t":[5362,9575]},{"fr":"L’essentiel est invisible pour les yeux.","zh":"最重要的东西对眼睛来说是看不见的。","t":[9575,11450]}]},{"id":"ch21p59","audio":true,"sents":[{"fr":"— L’essentiel est invisible pour les yeux, répéta le petit prince, afin de se souvenir.","zh":"——最重要的东西对眼睛来说是看不见的，小王子重复道，以便记住。","t":[100,6075]}]},{"id":"ch21p60","audio":true,"sents":[{"fr":"— C’est le temps que tu as perdu pour ta rose qui fait ta rose si importante.","zh":"——你为你的玫瑰所浪费的时间，使你的玫瑰变得如此重要。","t":[100,4725]}]},{"id":"ch21p61","audio":true,"sents":[{"fr":"— C’est le temps que j’ai perdu pour ma rose…","zh":"——我为我的玫瑰所浪费的时间……","t":[100,3262]},{"fr":"fit le petit prince, afin de se souvenir.","zh":"小王子说，以便记住。","t":[3262,5687]}]},{"id":"ch21p62","audio":true,"sents":[{"fr":"— Les hommes ont oublié cette vérité, dit le renard.","zh":"——人们已经忘记了这个真理，狐狸说。","t":[100,4775]},{"fr":"Mais tu ne dois pas l’oublier.","zh":"但你不能忘记。","t":[4775,7062]},{"fr":"Tu deviens responsable pour toujours de ce que tu as apprivoisé.","zh":"你将永远对你所驯服的东西负责。","t":[7062,11125]},{"fr":"Tu es responsable de ta rose…","zh":"你对你的玫瑰负责……","t":[11125,12900]}]},{"id":"ch21p63","audio":true,"sents":[{"fr":"— Je suis responsable de ma rose…","zh":"我对我那朵玫瑰负责……","t":[100,3212]},{"fr":"répéta le petit prince, afin de se souvenir.","zh":"小王子重复道，以便记住。","t":[3212,5925]}]},{"id":"ch21p64","audio":true,"sents":[]}]},{"id":"ch22","title_fr":"Chapitre XXII","title_zh":"第 22 章","paras":[{"id":"ch22p00","audio":true,"sents":[]},{"id":"ch22p01","audio":true,"sents":[{"fr":"— Bonjour, dit le petit prince.","zh":"——你好，小王子说。","t":[100,3074]}]},{"id":"ch22p02","audio":true,"sents":[{"fr":"— Bonjour, dit l’aiguilleur.","zh":"——你好，引路人说。","t":[100,2863]}]},{"id":"ch22p03","audio":true,"sents":[{"fr":"— Que fais-tu ici ?","zh":"——你在这里做什么？","t":[100,3100]},{"fr":"dit le petit prince.","zh":"小王子说。","t":[3100,4088]}]},{"id":"ch22p04","audio":true,"sents":[{"fr":"— Je trie les voyageurs, par paquets de mille, dit l’aiguilleur.","zh":"——我整理旅客，每次一千人，引路人说。","t":[100,6125]},{"fr":"J’expédie les trains qui les emportent, tantôt vers la droite, tantôt vers la gauche.","zh":"我发送火车，时而向右，时而向左，将他们带走。","t":[6125,10000]}]},{"id":"ch22p05","audio":true,"sents":[{"fr":"Et un rapide illuminé, grondant comme le tonnerre, fit trembler la cabine d’aiguillage.","zh":"一个狂热的快车，像雷声一样咆哮着，使道岔的驾驶室颤抖。","t":[100,4675]}]},{"id":"ch22p06","audio":true,"sents":[{"fr":"— Ils sont bien pressés, dit le petit prince.","zh":"——他们很急迫，小王子说。","t":[100,4362]},{"fr":"Que cherchent-ils ?","zh":"他们在寻找什么？","t":[4362,5762]}]},{"id":"ch22p07","audio":true,"sents":[{"fr":"— L’homme de la locomotive l’ignore lui-même, dit l’aiguilleur.","zh":"——火车头的人自己也不知道，道岔管理员说。","t":[100,4300]}]},{"id":"ch22p08","audio":true,"sents":[{"fr":"Et gronda, en sens inverse, un second rapide illuminé.","zh":"另一个狂热的快车以相反的方向咆哮着。","t":[100,3550]}]},{"id":"ch22p09","audio":true,"sents":[{"fr":"— Ils reviennent déjà ?","zh":"——他们已经回来了吗？","t":[100,3150]},{"fr":"demanda le petit prince…","zh":"小王子问道……","t":[3150,4413]}]},{"id":"ch22p10","audio":true,"sents":[{"fr":"— Ce ne sont pas les mêmes, dit l’aiguilleur.","zh":"——它们不是同一个，道岔管理员说。","t":[100,4300]},{"fr":"C’est un échange.","zh":"这是一场交易。","t":[4300,5112]}]},{"id":"ch22p11","audio":true,"sents":[{"fr":"— Ils n’étaient pas contents, là où ils étaient ?","zh":"——他们在原来的地方不开心吗？","t":[100,3813]}]},{"id":"ch22p12","audio":true,"sents":[{"fr":"— On n’est jamais content là où l’on est, dit l’aiguilleur.","zh":"我们永远无法满足于现状，列车员说。","t":[100,3813]}]},{"id":"ch22p13","audio":true,"sents":[{"fr":"Et gronda le tonnerre d’un troisième rapide illuminé.","zh":"接着，一道闪电划破了雷鸣。","t":[100,2712]}]},{"id":"ch22p14","audio":true,"sents":[{"fr":"— Ils poursuivent les premiers voyageurs ?","zh":"他们追捕最初的旅行者？","t":[100,3850]},{"fr":"demanda le petit prince.","zh":"小王子问道。","t":[3850,5125]}]},{"id":"ch22p15","audio":true,"sents":[{"fr":"— Ils ne poursuivent rien du tout, dit l’aiguilleur.","zh":"他们根本不追捕任何东西，列车员说。","t":[100,4550]},{"fr":"Ils dorment là-dedans, ou bien ils bâillent.","zh":"他们在里面睡觉，或者打哈欠。","t":[4550,7575]},{"fr":"Les enfants seuls écrasent leur nez contre les vitres.","zh":"只有孩子们才会把鼻子贴在窗户上。","t":[7575,10037]}]},{"id":"ch22p16","audio":true,"sents":[{"fr":"— Les enfants seuls savent ce qu’ils cherchent, fit le petit prince.","zh":"只有孩子们知道他们在寻找什么，小王子说。","t":[100,5275]},{"fr":"Ils perdent du temps pour une poupée de chiffons, et elle devient très importante, et si on la leur enlève, ils pleurent…","zh":"他们会为了一个布娃娃浪费时间，而她变得非常重要，如果你把她拿走，他们会哭……","t":[5275,11287]}]},{"id":"ch22p17","audio":true,"sents":[{"fr":"— Ils ont de la chance, dit l’aiguilleur.","zh":"他们很幸运，列车员说。","t":[100,3200]}]},{"id":"ch22p18","audio":true,"sents":[]}]},{"id":"ch23","title_fr":"Chapitre XXIII","title_zh":"第 23 章","paras":[{"id":"ch23p00","audio":true,"sents":[{"fr":"— Bonjour, dit le petit prince.","zh":"——你好，小王子说。","t":[100,3074]}]},{"id":"ch23p01","audio":true,"sents":[{"fr":"— Bonjour, dit le marchand.","zh":"——你好，商人说。","t":[100,2776]}]},{"id":"ch23p02","audio":true,"sents":[{"fr":"C’était un marchand de pilules perfectionnées qui apaisent la soif.","zh":"那是一位卖完美良药的人，这种药能平息口渴。","t":[100,4162]},{"fr":"On en avale une par semaine et l’on n’éprouve plus le besoin de boire.","zh":"人们一周吃一粒，就不再有喝水的欲望。","t":[4162,7338]}]},{"id":"ch23p03","audio":true,"sents":[{"fr":"— Pourquoi vends-tu ça ?","zh":"——你为什么卖这个？","t":[100,3112]},{"fr":"dit le petit prince.","zh":"小王子说。","t":[3112,4125]}]},{"id":"ch23p04","audio":true,"sents":[{"fr":"— C’est une grosse économie de temps, dit le marchand.","zh":"——这能节省很多时间，商人说。","t":[100,4662]},{"fr":"Les experts ont fait des calculs.","zh":"专家们已经做了计算。","t":[4662,7300]},{"fr":"On épargne cinquante-trois minutes par semaine.","zh":"人们每周能节省五十三分钟。","t":[7300,9513]}]},{"id":"ch23p05","audio":true,"sents":[{"fr":"— Et que fait-on des cinquante-trois minutes ?","zh":"— 那五十三分钟用来做什么呢？","t":[100,3538]}]},{"id":"ch23p06","audio":true,"sents":[{"fr":"— On en fait ce que l’on veut…","zh":"— 人们可以随心所欲地使用它们…","t":[100,2500]}]},{"id":"ch23p07","audio":true,"sents":[{"fr":"\"Moi, se dit le petit prince, si j’avais cinquante-trois minutes à dépenser, je marcherais tout doucement vers une fontaine…\"","zh":"小王子心想：如果我有五十三分钟可以支配，我会慢慢地走向一个泉水…","t":[100,6425]}]},{"id":"ch23p08","audio":true,"sents":[]}]},{"id":"ch24","title_fr":"Chapitre XXIV","title_zh":"第 24 章","paras":[{"id":"ch24p00","audio":true,"sents":[]},{"id":"ch24p01","audio":true,"sents":[{"fr":"Nous en étions au huitième jour de ma panne dans le désert, et j’avais écouté l’histoire du marchand en buvant la dernière goutte de ma provision d’eau :","zh":"那是我沙漠中故障的第八天，我喝完最后一滴水，听了商人的故事：","t":[100,7838]}]},{"id":"ch24p02","audio":true,"sents":[{"fr":"— Ah !","zh":"— 啊！","t":[100,3038]},{"fr":"dis-je au petit prince, ils sont bien jolis, tes souvenirs, mais je n’ai pas encore réparé mon avion, je n’ai plus rien à boire, et je serais heureux, moi aussi, si je pouvais marcher tout doucement vers une fontaine !","zh":"我对小王子说：你的回忆很美好，但我还没修好我的飞机，我什么水都没有了，如果也能慢慢地走向一个泉水，我也会很快乐！","t":[3038,15250]}]},{"id":"ch24p03","audio":true,"sents":[{"fr":"— Mon ami le renard, me dit-il…","zh":"— 我的朋友狐狸，他对我说…","t":[100,3100]}]},{"id":"ch24p04","audio":true,"sents":[{"fr":"— Mon petit bonhomme, il ne s’agit plus du renard !","zh":"— 我的小家伙，现在说的已经不是狐狸了！","t":[100,4375]}]},{"id":"ch24p05","audio":true,"sents":[{"fr":"— Pourquoi ?","zh":"为什么？","t":[100,2462]}]},{"id":"ch24p06","audio":true,"sents":[{"fr":"— Parce qu’on va mourir de soif…","zh":"因为我们会渴死的……","t":[100,2712]}]},{"id":"ch24p07","audio":true,"sents":[{"fr":"Il ne comprit pas mon raisonnement, il me répondit :","zh":"他不理解我的推理，他回答我说：","t":[100,3388]}]},{"id":"ch24p08","audio":true,"sents":[{"fr":"— C’est bien d’avoir eu un ami, même si l’on va mourir.","zh":"有了一个朋友是好事，即使我们即将死去。","t":[100,4900]},{"fr":"Moi, je suis bien content d’avoir eu un ami renard…","zh":"我，我很高兴有了一个狐狸朋友……","t":[4900,7725]}]},{"id":"ch24p09","audio":true,"sents":[{"fr":"Il ne mesure pas le danger, me dis-je.","zh":"他没有衡量危险，我想。","t":[100,3188]},{"fr":"Il n’a jamais ni faim ni soif.","zh":"他既不饿也不渴。","t":[3188,5625]},{"fr":"Un peu de soleil lui suffit…","zh":"一点阳光就足够了……","t":[5625,7138]}]},{"id":"ch24p10","audio":true,"sents":[{"fr":"Mais il me regarda et répondit à ma pensée :","zh":"但他看着我，对我的想法回应说：","t":[100,3225]}]},{"id":"ch24p11","audio":true,"sents":[{"fr":"— J’ai soif aussi…","zh":"我也有渴……","t":[100,2262]},{"fr":"cherchons un puits…","zh":"寻找一口井...","t":[2262,3125]}]},{"id":"ch24p12","audio":true,"sents":[{"fr":"J’eus un geste de lassitude : il est absurde de chercher un puits, au hasard, dans l’immensité du désert.","zh":"我表现出了一丝疲惫：在沙漠的浩瀚中随意寻找一口井是荒谬的。","t":[100,7538]},{"fr":"Cependant nous nous mîmes en marche.","zh":"然而，我们还是开始了旅程。","t":[7538,9112]}]},{"id":"ch24p13","audio":true,"sents":[{"fr":"Quand nous eûmes marché, des heures, en silence, la nuit tomba, et les étoiles commencèrent de s’éclairer.","zh":"当我们走了几个小时，默默无言，夜幕降临，星星开始闪烁。","t":[100,7000]},{"fr":"Je les apercevais comme en rêve, ayant un peu de fièvre, à cause de ma soif.","zh":"我像在梦中一样看到它们，因为口渴而有些发烧。","t":[7000,12175]},{"fr":"Les mots du petit prince dansaient dans ma mémoire :","zh":"小王子的话在我记忆中跳跃：","t":[12175,15000]}]},{"id":"ch24p14","audio":true,"sents":[{"fr":"— Tu as donc soif, toi aussi ?","zh":"——你也渴了吗？","t":[100,4650]},{"fr":"lui demandai-je.","zh":"我问他。","t":[4650,5612]}]},{"id":"ch24p15","audio":true,"sents":[{"fr":"Mais il ne répondit pas à ma question.","zh":"但他没有回答我的问题。","t":[100,2812]},{"fr":"Il me dit simplement :","zh":"他只是简单地告诉我：","t":[2812,4626]}]},{"id":"ch24p16","audio":true,"sents":[{"fr":"— L’eau peut aussi être bonne pour le cœur…","zh":"水对心脏也有好处……","t":[100,3087]}]},{"id":"ch24p17","audio":true,"sents":[{"fr":"Je ne compris pas sa réponse mais je me tus…","zh":"我没有明白他的回答，但我闭上了嘴……","t":[100,3125]},{"fr":"Je savais bien qu’il ne fallait pas l’interroger.","zh":"我清楚不应该问他问题。","t":[3125,5400]}]},{"id":"ch24p18","audio":true,"sents":[{"fr":"Il était fatigué.","zh":"他累了。","t":[100,2000]},{"fr":"Il s’assit.","zh":"他坐了下来。","t":[2000,3625]},{"fr":"Je m’assis auprès de lui.","zh":"我坐在他旁边。","t":[3625,5912]},{"fr":"Et, après un silence, il dit encore :","zh":"沉默了一会儿后，他又说：","t":[5912,8812]}]},{"id":"ch24p19","audio":true,"sents":[{"fr":"— Les étoiles sont belles, à cause d’une fleur que l’on ne voit pas…","zh":"星星之所以美丽，是因为有一朵人们看不见的花……","t":[100,4187]}]},{"id":"ch24p20","audio":true,"sents":[{"fr":"Je répondis \"bien sûr\" et je regardai, sans parler, les plis du sable sous la lune.","zh":"我回答道“当然”然后默默地看着月光下的沙子纹路。","t":[100,4975]}]},{"id":"ch24p21","audio":true,"sents":[{"fr":"— Le désert est beau, ajouta-t-il…","zh":"沙漠很美，他补充道……","t":[100,3024]}]},{"id":"ch24p22","audio":true,"sents":[{"fr":"Et c’était vrai.","zh":"这倒是真的。","t":[100,1688]},{"fr":"J’ai toujours aimé le désert.","zh":"我一直喜欢沙漠。","t":[1688,4150]},{"fr":"On s’assoit sur une dune de sable.","zh":"我们坐在沙丘上。","t":[4150,6700]},{"fr":"On ne voit rien.","zh":"什么也看不见。","t":[6700,8438]},{"fr":"On n’entend rien.","zh":"什么也听不见。","t":[8438,10162]},{"fr":"Et cependant quelque chose rayonne en silence…","zh":"然而，却有一种东西在沉默中闪耀……","t":[10162,12376]}]},{"id":"ch24p23","audio":true,"sents":[{"fr":"— Ce qui embellit le désert, dit le petit prince, c’est qu’il cache un puits quelque part…","zh":"——小王子说，使沙漠变得美丽的是它某个地方隐藏着一口井……","t":[100,5850]}]},{"id":"ch24p24","audio":true,"sents":[{"fr":"Je fus surpris de comprendre soudain ce mystérieux rayonnement du sable.","zh":"我突然明白了沙子的这种神秘的光芒。","t":[100,4612]},{"fr":"Lorsque j’étais petit garçon j’habitais une maison ancienne, et la légende racontait qu’un trésor y était enfoui.","zh":"当我还是个小男孩的时候，我住在一座古老的房子里，传说那里埋藏着一笔宝藏。","t":[4612,11050]},{"fr":"Bien sûr, jamais personne n’a su le découvrir, ni peut-être même ne l’a cherché.","zh":"当然，没有人知道它在哪里，也许甚至没有人去寻找过。","t":[11050,16425]},{"fr":"Mais il enchantait toute cette maison.","zh":"但它使整个房子充满了魔力。","t":[16425,19012]},{"fr":"Ma maison cachait un secret au fond de son cœur…","zh":"我的房子在心底深处隐藏着一个秘密……","t":[19012,21387]}]},{"id":"ch24p25","audio":true,"sents":[{"fr":"— Oui, dis-je au petit prince, qu’il s’agisse de la maison, des étoiles ou du désert, ce qui fait leur beauté est invisible !","zh":"——是的，我对小王子说，无论是房子、星星还是沙漠，使它们美丽的东西都是看不见的！","t":[100,8424]}]},{"id":"ch24p26","audio":true,"sents":[{"fr":"— Je suis content, dit-il, que tu sois d’accord avec mon renard.","zh":"——我很高兴，他说，你同意我的狐狸的观点。","t":[100,4800]}]},{"id":"ch24p27","audio":true,"sents":[{"fr":"Comme le petit prince s’endormait, je le pris dans mes bras, et me remis en route.","zh":"当小王子入睡时，我把他抱在怀里，继续前行。","t":[100,5175]},{"fr":"J’étais ému.","zh":"我感动了。","t":[5175,6900]},{"fr":"Il me semblait porter un trésor fragile.","zh":"我觉得我手里捧着一件脆弱的宝物。","t":[6900,9850]},{"fr":"Il me semblait même qu’il n’y eût rien de plus fragile sur la Terre.","zh":"我觉得甚至地球上没有比这更脆弱的东西了。","t":[9850,13838]},{"fr":"Je regardais, à la lumière de la lune, ce front pâle, ces yeux clos, ces mèches de cheveux qui tremblaient au vent, et je me disais : ce que je vois là n’est qu’une écorce.","zh":"我看着，在月光下，那苍白的额头，紧闭的眼睛，随风摇曳的头发，我想：我所看到的不过是一层外壳。","t":[13838,24575]},{"fr":"Le plus important est invisible…","zh":"最重要的东西是看不见的……","t":[24575,26388]}]},{"id":"ch24p28","audio":true,"sents":[{"fr":"Comme ses lèvres entr’ouvertes ébauchaient un demi-sourire je me dis encore : \"Ce qui m’émeut si fort de ce petit prince endormi, c’est sa fidélité pour une fleur, c’est l’image d’une rose qui rayonne en lui comme la flamme d’une lampe, même quand il dort…\" Et je le devinai plus fragile encore.","zh":"像他的嘴唇微微张开露出半边笑容时，我再次想：'这个小王子睡着的样子让我如此感动，是因为他对一朵花的忠诚，是玫瑰在他心中绽放的形象，就像灯火的火焰，即使在他睡着的时候……'而且我感觉到他更加脆弱了。","t":[100,20700]},{"fr":"Il faut bien protéger les lampes : un coup de vent peut les éteindre…","zh":"必须好好保护灯笼：一阵风就能把它们吹灭……","t":[20700,21200]}]},{"id":"ch24p29","audio":true,"sents":[{"fr":"Et, marchant ainsi, je découvris le puits au lever du jour.","zh":"就这样走着，我在黎明时分发现了那口井。","t":[100,3474]}]},{"id":"ch24p30","audio":true,"sents":[]}]},{"id":"ch25","title_fr":"Chapitre XXV","title_zh":"第 25 章","paras":[{"id":"ch25p00","audio":true,"sents":[]},{"id":"ch25p01","audio":true,"sents":[{"fr":"— Les hommes, dit le petit prince, ils s’enfournent dans les rapides, mais ils ne savent plus ce qu’ils cherchent.","zh":"——人们啊，小王子说，他们一头扎进急流中，却不知道他们在寻找什么。","t":[100,7488]},{"fr":"Alors ils s’agitent et tournent en rond…","zh":"然后他们开始忙乱，团团转……","t":[7488,9162]}]},{"id":"ch25p02","audio":true,"sents":[{"fr":"Et il ajouta :","zh":"他还补充说：","t":[100,1738]}]},{"id":"ch25p03","audio":true,"sents":[{"fr":"— Ce n’est pas la peine…","zh":"——没用的……","t":[100,2125]}]},{"id":"ch25p04","audio":true,"sents":[{"fr":"Le puits que nous avions atteint ne ressemblait pas aux puits sahariens.","zh":"我们到达的那口井并不像撒哈拉沙漠中的井。","t":[100,3888]},{"fr":"Les puits sahariens sont de simples trous creusés dans le sable.","zh":"撒哈拉沙漠的井只是沙子中挖出的简单洞。","t":[3888,7662]},{"fr":"Celui-là ressemblait à un puits de village.","zh":"那个井看起来像是一个村庄的井。","t":[7662,10775]},{"fr":"Mais il n’y avait là aucun village, et je croyais rêver.","zh":"但那里没有村庄，我以为是梦。","t":[10775,13788]}]},{"id":"ch25p05","audio":true,"sents":[{"fr":"— C’est étrange, dis-je au petit prince, tout est prêt : la poulie, le seau et la corde…","zh":"——奇怪，我对小王子说，一切都准备好了：滑轮、水桶和绳子……","t":[100,6788]}]},{"id":"ch25p06","audio":true,"sents":[{"fr":"Il rit, toucha la corde, fit jouer la poulie.","zh":"他笑了，摸了摸绳子，让滑轮转动。","t":[100,3738]},{"fr":"Et la poulie gémit comme gémit une vieille girouette quand le vent a longtemps dormi.","zh":"滑轮发出像老风车长时间停转时的呻吟声。","t":[3738,7424]}]},{"id":"ch25p07","audio":true,"sents":[{"fr":"— Tu entends, dit le petit prince, nous réveillons ce puits et il chante…","zh":"——你听到了吗，小王子说，我们唤醒了这个井，它在唱歌……","t":[100,5025]}]},{"id":"ch25p08","audio":true,"sents":[{"fr":"Je ne voulais pas qu’il fît un effort :","zh":"我不想让他费劲。","t":[100,2450]}]},{"id":"ch25p09","audio":true,"sents":[{"fr":"— Laisse-moi faire, lui dis-je, c’est trop lourd pour toi.","zh":"——让我来吧，我对他说，对你来说太重了。","t":[100,4213]}]},{"id":"ch25p10","audio":true,"sents":[{"fr":"Lentement je hissai le seau jusqu’à la margelle.","zh":"我慢慢地把水桶提到井沿。","t":[100,3388]},{"fr":"Je l’y installai bien d’aplomb.","zh":"我把它稳稳地放好。","t":[3388,5850]},{"fr":"Dans mes oreilles durait le chant de la poulie et, dans l’eau qui tremblait encore, je voyais trembler le soleil.","zh":"我的耳边还回荡着滑轮的歌声，在还微微颤抖的水面上，我看到太阳在颤抖。","t":[5850,11213]}]},{"id":"ch25p11","audio":true,"sents":[{"fr":"— J’ai soif de cette eau-là, dit le petit prince, donne-moi à boire…","zh":"——我对这水渴得要命，小王子说，给我喝点……","t":[100,4838]}]},{"id":"ch25p12","audio":true,"sents":[{"fr":"Et je compris ce qu’il avait cherché !","zh":"我明白了他在寻找什么！","t":[100,2538]}]},{"id":"ch25p13","audio":true,"sents":[{"fr":"Je soulevai le seau jusqu’à ses lèvres.","zh":"我把水桶提到他的嘴唇边。","t":[100,2888]},{"fr":"Il but, les yeux fermés.","zh":"他闭着眼睛喝了。","t":[2888,5288]},{"fr":"C’était doux comme une fête.","zh":"这水像节日一样甜美。","t":[5288,7512]},{"fr":"Cette eau était bien autre chose qu’un aliment.","zh":"这水不仅仅是食物。","t":[7512,10488]},{"fr":"Elle était née de la marche sous les étoiles, du chant de la poulie, de l’effort de mes bras.","zh":"它是从星星下行走、滑轮的歌声、我手臂的劳作中诞生的。","t":[10488,15938]},{"fr":"Elle était bonne pour le cœur, comme un cadeau.","zh":"它对心灵有益，就像一份礼物。","t":[15938,19112]},{"fr":"Lorsque j’étais petit garçon, la lumière de l’arbre de Noël, la musique de la messe de minuit, la douceur des sourires faisaient ainsi tout le rayonnement du cadeau de Noël que je recevais.","zh":"当我是个小男孩时，圣诞树的灯光、午夜弥撒的音乐、微笑的温柔构成了我收到的圣诞礼物的全部光辉。","t":[19112,28500]}]},{"id":"ch25p14","audio":true,"sents":[{"fr":"— Les hommes de chez toi, dit le petit prince, cultivent cinq mille roses dans un même jardin…","zh":"——你们那里的人，小王子说，在同一花园里种植了五千朵玫瑰……","t":[100,6162]},{"fr":"et ils n’y trouvent pas ce qu’ils cherchent.","zh":"但他们找不到他们所寻找的东西。","t":[6162,7600]}]},{"id":"ch25p15","audio":true,"sents":[{"fr":"— Ils ne le trouvent pas, répondis-je…","zh":"——他们找不到，我回答说……","t":[100,2974]}]},{"id":"ch25p16","audio":true,"sents":[{"fr":"— Et cependant ce qu’ils cherchent pourrait être trouvé dans une seule rose ou un peu d’eau…","zh":"——然而他们所寻找的东西可能在一朵玫瑰或一点水中就能找到……","t":[100,4825]}]},{"id":"ch25p17","audio":true,"sents":[{"fr":"— Bien sûr, répondis-je.","zh":"——当然，我回答说。","t":[100,2850]}]},{"id":"ch25p18","audio":true,"sents":[{"fr":"Et le petit prince ajouta :","zh":"小王子接着说：","t":[100,2274]}]},{"id":"ch25p19","audio":true,"sents":[{"fr":"— Mais les yeux sont aveugles.","zh":"——但是眼睛是盲目的。","t":[100,3362]},{"fr":"Il faut chercher avec le cœur.","zh":"必须用心去寻找。","t":[3362,4900]}]},{"id":"ch25p20","audio":true,"sents":[{"fr":"J’avais bu.","zh":"我喝醉了。","t":[100,1688]},{"fr":"Je respirais bien.","zh":"我呼吸得很顺畅。","t":[1688,3688]},{"fr":"Le sable, au lever du jour, est couleur de miel.","zh":"黎明时分，沙子呈现出蜜色。","t":[3688,7562]},{"fr":"J’étais heureux aussi de cette couleur de miel.","zh":"我也为这蜜色感到高兴。","t":[7562,10725]},{"fr":"Pourquoi fallait-il que j’eusse de la peine…","zh":"为什么我会有困难……","t":[10725,12712]}]},{"id":"ch25p21","audio":true,"sents":[{"fr":"— Il faut que tu tiennes ta promesse, me dit doucement le petit prince, qui, de nouveau, s’était assis auprès de moi.","zh":"——你必须遵守你的承诺，小王子轻声对我说，他又一次在我身边坐下。","t":[100,7450]}]},{"id":"ch25p22","audio":true,"sents":[{"fr":"— Quelle promesse ?","zh":"——什么承诺？","t":[100,2563]}]},{"id":"ch25p23","audio":true,"sents":[{"fr":"— Tu sais…","zh":"——你知道……","t":[100,1888]},{"fr":"une muselière pour mon mouton…","zh":"给我的羊带上口套……","t":[1888,3425]},{"fr":"je suis responsable de cette fleur !","zh":"我对这朵花负有责任！","t":[3425,5724]}]},{"id":"ch25p24","audio":true,"sents":[{"fr":"Je sortis de ma poche mes ébauches de dessin.","zh":"我从口袋里掏出了我的草图。","t":[100,3238]},{"fr":"Le petit prince les aperçut et dit en riant :","zh":"小王子看到它们，笑着说道：","t":[3238,6224]}]},{"id":"ch25p25","audio":true,"sents":[{"fr":"— Tes baobabs, ils ressemblent un peu à des choux…","zh":"—— 你的猴面包树，它们有点像卷心菜……","t":[100,3500]}]},{"id":"ch25p26","audio":true,"sents":[{"fr":"— Oh !","zh":"—— 哦！","t":[100,2176]}]},{"id":"ch25p27","audio":true,"sents":[{"fr":"Moi qui était si fier des baobabs !","zh":"我曾经那么自豪我的猴面包树！","t":[100,2437]}]},{"id":"ch25p28","audio":true,"sents":[{"fr":"— Ton renard…","zh":"—— 你的狐狸……","t":[100,2050]},{"fr":"ses oreilles…","zh":"它的耳朵……","t":[2050,2925]},{"fr":"elles ressemblent un peu à des cornes…","zh":"它们有点像角……","t":[2925,4550]},{"fr":"et elles sont trop longues !","zh":"而且太长了！","t":[4550,6188]}]},{"id":"ch25p29","audio":true,"sents":[{"fr":"Et il rit encore.","zh":"他又笑了。","t":[100,1074]}]},{"id":"ch25p30","audio":true,"sents":[{"fr":"— Tu es injuste, petit bonhomme, je ne savais rien dessiner que les boas fermés et les boas ouverts.","zh":"—— 你太不公平了，小家伙，我只会画闭着的蛇和开着的蛇。","t":[100,6562]}]},{"id":"ch25p31","audio":true,"sents":[{"fr":"— Oh !","zh":"哦！","t":[100,3038]},{"fr":"ça ira, dit-il, les enfants savent.","zh":"没关系，他说，孩子们都知道。","t":[3038,5675]}]},{"id":"ch25p32","audio":true,"sents":[{"fr":"Je crayonnai donc une muselière.","zh":"所以我画了一个项圈。","t":[100,2888]},{"fr":"Et j’eus le cœur serré en la lui donnant :","zh":"在给她的时候，我心头一紧：","t":[2888,5375]}]},{"id":"ch25p33","audio":true,"sents":[{"fr":"— Tu as des projets que j’ignore…","zh":"你有什么计划，我不知道……","t":[100,2725]}]},{"id":"ch25p34","audio":true,"sents":[{"fr":"Mais il ne me répondit pas.","zh":"但他没有回答我。","t":[100,2200]},{"fr":"Il me dit :","zh":"他说：","t":[2200,3550]}]},{"id":"ch25p35","audio":true,"sents":[{"fr":"— Tu sais, ma chute sur la Terre…","zh":"你知道，我在地球上坠落……","t":[100,3325]},{"fr":"c’en sera demain l’anniversaire…","zh":"明天就是它的周年纪念日……","t":[3325,4900]}]},{"id":"ch25p36","audio":true,"sents":[{"fr":"Puis, après un silence il dit encore :","zh":"然后，在沉默了一会儿后，他又说：","t":[100,2813]}]},{"id":"ch25p37","audio":true,"sents":[{"fr":"— J’étais tombé tout près d’ici…","zh":"— 我就降落在这附近…","t":[100,2663]}]},{"id":"ch25p38","audio":true,"sents":[{"fr":"Et il rougit.","zh":"他脸红了。","t":[100,900]}]},{"id":"ch25p39","audio":true,"sents":[{"fr":"Et de nouveau, sans comprendre pourquoi, j’éprouvai un chagrin bizarre.","zh":"而且，我不明白为什么，我又感到一种奇怪的忧伤。","t":[100,5038]},{"fr":"Cependant une question me vint :","zh":"然而，一个问题浮现在我脑海：","t":[5038,7263]}]},{"id":"ch25p40","audio":true,"sents":[{"fr":"— Alors ce n’est pas par hasard que, le matin où je t’ai connu, il y a huit jours, tu te promenais comme ça, tout seul, à mille milles de toutes les régions habitées !","zh":"— 那么，八天前我认识你的那个早晨，你独自一人在远离所有有人居住的地方千里之外这样散步，并不是偶然的！","t":[100,10688]},{"fr":"Tu retournais vers le point de ta chute ?","zh":"你是要回到你降落的地方吗？","t":[10688,13138]}]},{"id":"ch25p41","audio":true,"sents":[{"fr":"Le petit prince rougit encore.","zh":"小王子又脸红了。","t":[100,1788]}]},{"id":"ch25p42","audio":true,"sents":[{"fr":"Et j’ajoutai, en hésitant :","zh":"我又犹豫着补充道：","t":[100,2538]}]},{"id":"ch25p43","audio":true,"sents":[{"fr":"— A cause, peut-être, de l’anniversaire ?…","zh":"— 也许是因为，纪念日？…","t":[100,3987]}]},{"id":"ch25p44","audio":true,"sents":[{"fr":"Le petit prince rougit de nouveau.","zh":"小王子又一次脸红了。","t":[100,2675]},{"fr":"Il ne répondait jamais aux questions, mais, quand on rougit, ça signifie \"oui\", n’est-ce pas ?","zh":"他从不回答问题，但是，当你脸红的时候，这就意味着‘是’，不是吗？","t":[2675,8400]}]},{"id":"ch25p45","audio":true,"sents":[{"fr":"— Ah !","zh":"——啊！","t":[100,3038]},{"fr":"lui dis-je, j’ai peur…","zh":"我对他说，我害怕……","t":[3038,4587]}]},{"id":"ch25p46","audio":true,"sents":[{"fr":"Mais il me répondit :","zh":"但是，他回答我说：","t":[100,1988]}]},{"id":"ch25p47","audio":true,"sents":[{"fr":"— Tu dois maintenant travailler.","zh":"——你现在必须工作了。","t":[100,3500]},{"fr":"Tu dois repartir vers ta machine.","zh":"你必须回到你的机器那里。","t":[3500,6250]},{"fr":"Je t’attends ici.","zh":"我在这里等你。","t":[6250,8250]},{"fr":"Reviens demain soir…","zh":"明天晚上回来……","t":[8250,9463]}]},{"id":"ch25p48","audio":true,"sents":[{"fr":"Mais je n’étais pas rassuré.","zh":"但是，我并不感到安心。","t":[100,2312]},{"fr":"Je me souvenais du renard.","zh":"我想起了狐狸。","t":[2312,4638]},{"fr":"On risque de pleurer un peu si l’on s’est laissé apprivoiser…","zh":"如果曾经被驯服，我们可能会有些难过……","t":[4638,7312]}]},{"id":"ch25p49","audio":true,"sents":[]},{"id":"ch25p50","audio":true,"sents":[]}]},{"id":"ch26","title_fr":"Chapitre XXVI","title_zh":"第 26 章","paras":[{"id":"ch26p00","audio":true,"sents":[{"fr":"Il y avait, à côté du puits, une ruine de vieux mur de pierre.","zh":"井边有一座古老的石墙废墟。","t":[100,4588]},{"fr":"Lorsque je revins de mon travail, le lendemain soir, j’aperçus de loin mon petit prince assis là-haut, les jambes pendantes.","zh":"第二天晚上，我从工作回来，远远地看到我的小王子坐在那里，双腿垂着。","t":[4588,12175]},{"fr":"Et je l’entendis qui parlait :","zh":"我听到他在说话：","t":[12175,14312]}]},{"id":"ch26p01","audio":true,"sents":[{"fr":"— Tu ne t’en souviens donc pas ?","zh":"——你真的不记得了吗？","t":[100,3450]},{"fr":"disait-il.","zh":"他说。","t":[3450,5025]},{"fr":"Ce n’est pas tout à fait ici !","zh":"这并不是完全在这里！","t":[5025,7012]}]},{"id":"ch26p02","audio":true,"sents":[{"fr":"Une autre voix lui répondit sans doute, puisqu’il répliqua :","zh":"另一个声音可能回答了他，因为他回答说：","t":[100,3875]}]},{"id":"ch26p03","audio":true,"sents":[{"fr":"— Si !","zh":"——！","t":[100,3025]},{"fr":"Si !","zh":"——！","t":[3025,4988]},{"fr":"c’est bien le jour, mais ce n’est pas ici l’endroit…","zh":"这是白天，但这里并不是合适的地方……","t":[4988,7650]}]},{"id":"ch26p04","audio":true,"sents":[{"fr":"Je poursuivis ma marche vers le mur.","zh":"我继续朝墙走去。","t":[100,2912]},{"fr":"Je ne voyais ni n’entendais toujours personne.","zh":"我既看不见也听不见任何人。","t":[2912,6062]},{"fr":"Pourtant le petit prince répliqua de nouveau :","zh":"然而小王子又回答说：","t":[6062,8924]}]},{"id":"ch26p05","audio":true,"sents":[{"fr":"— …","zh":"——……","t":[100,1850]},{"fr":"Bien sûr.","zh":"当然。","t":[1850,3438]},{"fr":"Tu verras où commence ma trace dans le sable.","zh":"你会看到我的脚印在沙子上的起点在哪里。","t":[3438,6550]},{"fr":"Tu n’as qu’a m’y attendre.","zh":"你只需在那里等待我即可。","t":[6550,9937]},{"fr":"J’y serai cette nuit.","zh":"我会在今晚到达那里。","t":[9937,10437]}]},{"id":"ch26p06","audio":true,"sents":[{"fr":"J’étais à vingt mètres du mur et je ne voyais toujours rien.","zh":"我离墙只有二十米，但我仍然什么也看不见。","t":[100,2824]}]},{"id":"ch26p07","audio":true,"sents":[{"fr":"Le petit prince dit encore, après un silence :","zh":"小王子在沉默之后又说：","t":[100,3325]}]},{"id":"ch26p08","audio":true,"sents":[{"fr":"— Tu as du bon venin ?","zh":"——你有好毒液吗？","t":[100,3825]},{"fr":"Tu es sûr de ne pas me faire souffrir longtemps ?","zh":"你确定不会让我痛苦太久吗？","t":[3825,6687]}]},{"id":"ch26p09","audio":true,"sents":[{"fr":"Je fis halte, le cœur serré, mais je ne comprenais toujours pas.","zh":"我停下脚步，心都揪紧了，但我仍然不明白。","t":[100,3663]}]},{"id":"ch26p10","audio":true,"sents":[{"fr":"— Maintenant va-t’en, dit-il…","zh":"——现在你走吧，他说……","t":[100,2838]},{"fr":"je veux redescendre !","zh":"我想下去！","t":[2838,4400]}]},{"id":"ch26p11","audio":true,"sents":[{"fr":"Alors j’abaissai moi-même les yeux vers le pied du mur, et je fis un bond !","zh":"然后我低头看向墙脚，然后跳了下去！","t":[100,5075]},{"fr":"Il était là, dressé vers le petit prince, un de ces serpents jaunes qui vous exécutent en trente secondes.","zh":"它就在那里，对着小王子伸着，是一条那种三十秒内就能把你处死的黄色蛇。","t":[5075,11362]},{"fr":"Tout en fouillant ma poche pour en tirer mon revolver, je pris le pas de course, mais, au bruit que je fis, le serpent se laissa doucement couler dans le sable, comme un jet d’eau qui meurt, et, sans trop se presser, se faufila entre les pierres avec un léger bruit de métal.","zh":"在掏出我的手枪的同时，我猛地跑了起来，但在我发出的声音中，那条蛇缓缓地滑进了沙子里，就像一条死去的喷泉，然后不慌不忙地穿过石头之间，发出轻微的金属声。","t":[11362,25713]}]},{"id":"ch26p12","audio":true,"sents":[{"fr":"Je parvins au mur juste à temps pour y recevoir dans les bras mon petit bonhomme de prince, pâle comme la neige.","zh":"我及时赶到墙边，将我的小王子抱在怀里，他苍白得像雪。","t":[100,5550]}]},{"id":"ch26p13","audio":true,"sents":[{"fr":"— Quelle est cette histoire-là !","zh":"——那个故事是关于什么的！","t":[100,3875]},{"fr":"Tu parles maintenant avec les serpents !","zh":"你现在能和蛇说话了！","t":[3875,6363]}]},{"id":"ch26p14","audio":true,"sents":[{"fr":"J’avais défait son éternel cache-nez d’or.","zh":"我已经揭下了他那永远戴着的金面具。","t":[100,3138]},{"fr":"Je lui avais mouillé les tempes et l’avais fait boire.","zh":"我给他浇了冷水，让他喝了酒。","t":[3138,6300]},{"fr":"Et maintenant je n’osais plus rien lui demander.","zh":"现在我却不敢再问他任何事情了。","t":[6300,9412]},{"fr":"Il me regarda gravement et m’entoura le cou de ses bras.","zh":"他严肃地看着我，用双臂围住了我的脖子。","t":[9412,13000]},{"fr":"Je sentais battre son cœur comme celui d’un oiseau qui meurt, quand on l’a tiré à la carabine.","zh":"我感觉到他的心跳就像一只被枪打死的鸟的心跳。","t":[13000,18700]},{"fr":"Il me dit :","zh":"他说：","t":[18700,20050]}]},{"id":"ch26p15","audio":true,"sents":[{"fr":"— Je suis content que tu aies trouvé ce qui manquait à ta machine.","zh":"我很高兴你找到了你机器缺少的东西。","t":[100,4925]},{"fr":"Tu vas pouvoir rentrer chez toi…","zh":"你终于可以回家了...","t":[4925,6474]}]},{"id":"ch26p16","audio":true,"sents":[{"fr":"— Comment sais-tu !","zh":"你怎么知道的！","t":[100,2613]}]},{"id":"ch26p17","audio":true,"sents":[{"fr":"Je venais justement lui annoncer que, contre toute espérance, j’avais réussi mon travail !","zh":"我正要告诉他，出乎意料地，我完成了我的工作！","t":[100,5550]}]},{"id":"ch26p18","audio":true,"sents":[{"fr":"Il ne répondit rien à ma question, mais il ajouta :","zh":"他没有回答我的问题，但他接着说：","t":[100,3687]}]},{"id":"ch26p19","audio":true,"sents":[{"fr":"— Moi aussi, aujourd’hui, je rentre chez moi…","zh":"我也是，今天，我要回家了...","t":[100,3763]}]},{"id":"ch26p20","audio":true,"sents":[{"fr":"Puis, mélancolique :","zh":"然后，带着一丝忧郁：","t":[100,2150]}]},{"id":"ch26p21","audio":true,"sents":[{"fr":"— C’est bien plus loin…","zh":"那还要远得多……","t":[100,2312]},{"fr":"c’est bien plus difficile…","zh":"那要难得多……","t":[2312,3600]}]},{"id":"ch26p22","audio":true,"sents":[{"fr":"Je sentais bien qu’il se passait quelque chose d’extraordinaire.","zh":"我感觉到了，正在发生一些非凡的事情。","t":[100,4138]},{"fr":"Je le serrais dans les bras comme un petit enfant, et cependant il me semblait qu’il coulait verticalement dans un abîme sans que je pusse rien pour le retenir…","zh":"我把他紧紧抱在怀里，就像抱一个小孩，然而我却觉得他垂直地坠入一个深渊，我无法阻止他...","t":[4138,11413]}]},{"id":"ch26p23","audio":true,"sents":[{"fr":"Il avait le regard sérieux, perdu très loin :","zh":"他眼神严肃，目光遥远：","t":[100,3263]}]},{"id":"ch26p24","audio":true,"sents":[{"fr":"— J’ai ton mouton.","zh":"—— 我有你的绵羊。","t":[100,2925]},{"fr":"Et j’ai la caisse pour le mouton.","zh":"我还为绵羊准备了干草。","t":[2925,5225]},{"fr":"Et j’ai la muselière…","zh":"我还准备了嚼子……","t":[5225,6412]}]},{"id":"ch26p25","audio":true,"sents":[{"fr":"Et il sourit avec mélancolie.","zh":"他带着一丝忧郁地微笑。","t":[100,1725]}]},{"id":"ch26p26","audio":true,"sents":[{"fr":"J’attendis longtemps.","zh":"我等了很久。","t":[100,2025]},{"fr":"Je sentais qu’il se réchauffait peu à peu :","zh":"我感觉他渐渐暖和起来：","t":[2025,4763]}]},{"id":"ch26p27","audio":true,"sents":[{"fr":"— Petit bonhomme, tu as eu peur…","zh":"—— 小家伙，你害怕了……","t":[100,2987]}]},{"id":"ch26p28","audio":true,"sents":[{"fr":"Il avait eu peur, bien sûr !","zh":"他当然害怕了！","t":[100,3300]},{"fr":"Mais il rit doucement :","zh":"但他轻轻地笑了：","t":[3300,5100]}]},{"id":"ch26p29","audio":true,"sents":[{"fr":"— J’aurai bien plus peur ce soir…","zh":"——今晚我会更害怕……","t":[100,2763]}]},{"id":"ch26p30","audio":true,"sents":[{"fr":"De nouveau je me sentis glacé par le sentiment de l’irréparable.","zh":"我又一次感到自己被无法挽回的感觉冻僵了。","t":[100,4212]},{"fr":"Et je compris que je ne supportais pas l’idée de ne plus jamais entendre ce rire.","zh":"我明白了，我无法忍受永远不再听到这笑声的想法。","t":[4212,8788]},{"fr":"C’était pour moi comme une fontaine dans le désert.","zh":"对我来说，这就像沙漠中的一眼泉。","t":[8788,11187]}]},{"id":"ch26p31","audio":true,"sents":[{"fr":"— Petit bonhomme, je veux encore t’entendre rire…","zh":"——小家伙，我还想再听你笑……","t":[100,3713]}]},{"id":"ch26p32","audio":true,"sents":[{"fr":"Mais il me dit :","zh":"但他对我说：","t":[100,1650]}]},{"id":"ch26p33","audio":true,"sents":[{"fr":"— Cette nuit, ça fera un an.","zh":"——今晚，就满一年了。","t":[100,3775]},{"fr":"Mon étoile se trouvera juste au-dessus de l’endroit où je suis tombé l’année dernière…","zh":"我的星星将正好在我去年掉落的地方上方……","t":[3775,7800]}]},{"id":"ch26p34","audio":true,"sents":[{"fr":"— Petit bonhomme, n’est-ce pas que c’est un mauvais rêve cette histoire de serpent et de rendez-vous et d’étoile…","zh":"——小家伙，难道这蛇、约会和星星的故事不是一场噩梦吗……","t":[100,6100]}]},{"id":"ch26p35","audio":true,"sents":[{"fr":"Mais il ne répondit pas à ma question.","zh":"但他没有回答我的问题。","t":[100,2812]},{"fr":"Il me dit :","zh":"他对我说是：","t":[2812,4162]}]},{"id":"ch26p36","audio":true,"sents":[{"fr":"— Ce qui est important, ça ne se voit pas…","zh":"——重要的是，你看不见的……","t":[100,3213]}]},{"id":"ch26p37","audio":true,"sents":[{"fr":"— Bien sûr…","zh":"——当然……","t":[100,1825]}]},{"id":"ch26p38","audio":true,"sents":[{"fr":"— C’est comme pour la fleur.","zh":"——就像对那朵花一样。","t":[100,3275]},{"fr":"Si tu aimes une fleur qui se trouve dans une étoile, c’est doux, la nuit, de regarder le ciel.","zh":"如果你爱上一朵花儿，它在遥远的星星上，那么夜晚看星星就会变得很甜蜜。","t":[3275,9112]},{"fr":"Toutes les étoiles sont fleuries.","zh":"所有的星星都开满了花。","t":[9112,10576]}]},{"id":"ch26p39","audio":true,"sents":[{"fr":"— Bien sûr…","zh":"——当然……","t":[100,1825]}]},{"id":"ch26p40","audio":true,"sents":[{"fr":"— C’est comme pour l’eau.","zh":"——就像对水一样。","t":[100,2888]},{"fr":"Celle que tu m’as donnée à boire était comme une musique, à cause de la poulie et de la corde…","zh":"你给我喝的那水，因为风车和绳索，就像一首音乐……","t":[2888,7425]},{"fr":"tu te rappelles…","zh":"你还记得……","t":[7425,8425]},{"fr":"elle était bonne.","zh":"她很善良。","t":[8425,9112]}]},{"id":"ch26p41","audio":true,"sents":[{"fr":"— Bien sûr…","zh":"——当然……","t":[100,1825]}]},{"id":"ch26p42","audio":true,"sents":[{"fr":"— Tu regarderas, la nuit, les étoiles.","zh":"——你晚上会看星星吗？","t":[100,4500]},{"fr":"C’est trop petit chez moi pour que je te montre où se trouve la mienne.","zh":"在我这里太小了，我无法给你指我的那颗星星在哪里。","t":[4500,8412]},{"fr":"C’est mieux comme ça.","zh":"这样更好。","t":[8412,10300]},{"fr":"Mon étoile, ça sera pour toi une des étoiles.","zh":"我的星星，对你来说，将是那些星星中的一颗。","t":[10300,14050]},{"fr":"Alors, toutes les étoiles, tu aimeras les regarder…","zh":"那么，所有的星星，你都会喜欢看它们……","t":[14050,18000]},{"fr":"Elles seront toutes tes amies.","zh":"它们都将成为你的朋友。","t":[18000,20175]},{"fr":"Et puis je vais te faire un cadeau…","zh":"然后，我还会给你一个礼物……","t":[20175,21562]}]},{"id":"ch26p43","audio":true,"sents":[{"fr":"Il rit encore.","zh":"他又笑了。","t":[100,1013]}]},{"id":"ch26p44","audio":true,"sents":[{"fr":"— Ah !","zh":"——啊！","t":[100,3038]},{"fr":"petit bonhomme, petit bonhomme j’aime entendre ce rire !","zh":"小家伙，小家伙，我喜欢听你笑！","t":[3038,6374]}]},{"id":"ch26p45","audio":true,"sents":[{"fr":"— Justement ce sera mon cadeau…","zh":"——正好这是我的礼物……","t":[100,2812]},{"fr":"ce sera comme pour l’eau…","zh":"这就像水一样……","t":[2812,3874]}]},{"id":"ch26p46","audio":true,"sents":[{"fr":"— Que veux-tu dire ?","zh":"——你这是什么意思？","t":[100,2587]}]},{"id":"ch26p47","audio":true,"sents":[{"fr":"— Les gens ont des étoiles qui ne sont pas les mêmes.","zh":"——人们有的星星是不一样的。","t":[100,4188]},{"fr":"Pour les uns, qui voyagent, les étoiles sont des guides.","zh":"对于一些人来说，旅行者，星星是向导。","t":[4188,8112]},{"fr":"Pour d’autres elles ne sont rien que de petites lumières.","zh":"对于另一些人来说，它们只是小小的光芒。","t":[8112,11288]},{"fr":"Pour d’autres qui sont savants elles sont des problèmes.","zh":"对于一些学者来说，它们是问题。","t":[11288,14325]},{"fr":"Pour mon businessman elles étaient de l’or.","zh":"对你那位商人来说，它们都是金子。","t":[14325,17150]},{"fr":"Mais toutes ces étoiles-là se taisent.","zh":"但那些星星都沉默了。","t":[17150,19712]},{"fr":"Toi, tu auras des étoiles comme personne n’en a…","zh":"你，你会拥有别人没有的星星……","t":[19712,22338]}]},{"id":"ch26p48","audio":true,"sents":[{"fr":"— Que veux-tu dire ?","zh":"——你想说什么？","t":[100,2587]}]},{"id":"ch26p49","audio":true,"sents":[{"fr":"— Quand tu regarderas le ciel, la nuit, puisque j’habiterai dans l’une d’elles, puisque je rirai dans l’une d’elles, alors ce sera pour toi comme si riaient toutes les étoiles.","zh":"——当你晚上仰望天空时，既然我会住在其中的一颗星星上，既然我会从其中的一颗星星上笑出声来，那么对你来说，就好像所有的星星都在笑。","t":[100,10462]},{"fr":"Tu auras, toi, des étoiles qui savent rire !","zh":"你将会有，你会有的，会笑的星星！","t":[10462,13787]}]},{"id":"ch26p50","audio":true,"sents":[{"fr":"Et il rit encore.","zh":"他又笑了。","t":[100,1074]}]},{"id":"ch26p51","audio":true,"sents":[{"fr":"— Et quand tu seras consolé (on se console toujours) tu seras content de m’avoir connu.","zh":"——等你得到安慰（我们总是得到安慰）的时候，你会因为认识我而感到高兴。","t":[100,6750]},{"fr":"Tu seras toujours mon ami.","zh":"你将永远是我的朋友。","t":[6750,9062]},{"fr":"Tu auras envie de rire avec moi.","zh":"你会有和我一起笑的愿望。","t":[9062,11688]},{"fr":"Et tu ouvriras parfois ta fenêtre, comme ça, pour le plaisir…","zh":"有时，你会为了乐趣而打开窗户，就像这样……","t":[11688,16162]},{"fr":"Et tes amis seront bien étonnés de te voir rire en regardant le ciel.","zh":"你的朋友们会惊讶地看到你在仰望天空时笑出声。","t":[16162,20388]},{"fr":"Alors tu leur diras : \"Oui, les étoiles, ça me fait toujours rire !\" Et ils te croiront fou.","zh":"那时，你会对他们说：'是的，星星，这总是让我发笑！' 他们会认为你疯了。","t":[20388,28450]},{"fr":"Je t’aurai joué un bien vilain tour…","zh":"我给你开了一个很坏的玩笑……","t":[28450,30350]}]},{"id":"ch26p52","audio":true,"sents":[{"fr":"Et il rit encore.","zh":"他又笑了。","t":[100,1074]}]},{"id":"ch26p53","audio":true,"sents":[{"fr":"— Ce sera comme si je t’avais donné, au lieu d’étoiles, des tas de petits grelots qui savent rire…","zh":"——这就像是我给了你，而不是星星，一堆会笑的小铃铛……","t":[100,6050]}]},{"id":"ch26p54","audio":true,"sents":[{"fr":"Et il rit encore.","zh":"他又笑了。","t":[100,1950]},{"fr":"Puis il redevint sérieux :","zh":"然后他又变得严肃起来：","t":[1950,3912]}]},{"id":"ch26p55","audio":true,"sents":[{"fr":"— Cette nuit…","zh":"——就在这个夜晚……","t":[100,2000]},{"fr":"tu sais…","zh":"你知道……","t":[2000,2650]},{"fr":"ne viens pas.","zh":"不要来。","t":[2650,3174]}]},{"id":"ch26p56","audio":true,"sents":[{"fr":"— Je ne te quitterai pas.","zh":"——我不会离开你的。","t":[100,2150]}]},{"id":"ch26p57","audio":true,"sents":[{"fr":"— J’aurai l’air d’avoir mal…","zh":"——我会装作很痛苦……","t":[100,9000]},{"fr":"j’aurai un peu l’air de mourir.","zh":"我会显得有点像要死了。","t":[9000,9500]},{"fr":"C’est comme ça.","zh":"就是这样。","t":[9500,10000]},{"fr":"Ne viens pas voir ça, ce n’est pas la peine…","zh":"不要来看这个，没那个必要……","t":[10000,10500]}]},{"id":"ch26p58","audio":true,"sents":[{"fr":"— Je ne te quitterai pas.","zh":"——我不会离开你的。","t":[100,2150]}]},{"id":"ch26p59","audio":true,"sents":[{"fr":"Mais il était soucieux.","zh":"但他很担心。","t":[100,1225]}]},{"id":"ch26p60","audio":true,"sents":[{"fr":"— Je te dis ça…","zh":"——我告诉你……","t":[100,2100]},{"fr":"c’est à cause aussi du serpent.","zh":"这也是因为那条蛇的缘故。","t":[2100,4375]},{"fr":"Il ne faut pas qu’il te morde…","zh":"它不会咬你的...","t":[4375,6638]},{"fr":"Les serpents, c’est méchant.","zh":"蛇是恶毒的。","t":[6638,9038]},{"fr":"Ça peut mordre pour le plaisir…","zh":"它可能会为了乐趣而咬...","t":[9038,10700]}]},{"id":"ch26p61","audio":true,"sents":[{"fr":"— Je ne te quitterai pas.","zh":"——我不会离开你的。","t":[100,2150]}]},{"id":"ch26p62","audio":true,"sents":[{"fr":"Mais quelque chose le rassura :","zh":"但有什么东西让他安心了：","t":[100,2475]}]},{"id":"ch26p63","audio":true,"sents":[{"fr":"— C’est vrai qu’ils n’ont plus de venin pour la seconde morsure…","zh":"——确实，它们在第二次咬的时候就没有毒了...","t":[100,3800]}]},{"id":"ch26p64","audio":true,"sents":[{"fr":"Cette nuit-là je ne le vis pas se mettre en route.","zh":"那天晚上我没有看到他出发。","t":[100,3238]},{"fr":"Il s’était évadé sans bruit.","zh":"他没有发出任何声音就逃跑了。","t":[3238,5675]},{"fr":"Quand je réussis à le rejoindre il marchait décidé, d’un pas rapide.","zh":"当我成功追上他时，他正坚定地、快速地走着。","t":[5675,10100]},{"fr":"Il me dit seulement :","zh":"他只对我说：","t":[10100,11787]}]},{"id":"ch26p65","audio":true,"sents":[{"fr":"— Ah !","zh":"啊！","t":[100,3038]},{"fr":"tu es là…","zh":"你在这里……","t":[3038,3588]}]},{"id":"ch26p66","audio":true,"sents":[{"fr":"Et il me prit par la main.","zh":"然后他拉起我的手。","t":[100,2125]},{"fr":"Mais il se tourmenta encore :","zh":"但他还在自责：","t":[2125,4326]}]},{"id":"ch26p67","audio":true,"sents":[{"fr":"— Tu as eu tort.","zh":"你错了。","t":[100,2975]},{"fr":"Tu auras de la peine.","zh":"你会受苦的。","t":[2975,4975]},{"fr":"J’aurai l’air d’être mort et ce ne sera pas vrai…","zh":"我会看起来像是死了，但这不是真的……","t":[4975,7263]}]},{"id":"ch26p68","audio":true,"sents":[{"fr":"Moi je me taisais.","zh":"我是在保持沉默。","t":[100,1112]}]},{"id":"ch26p69","audio":true,"sents":[{"fr":"— Tu comprends.","zh":"你懂了。","t":[100,2738]},{"fr":"C’est trop loin.","zh":"太远了。","t":[2738,4425]},{"fr":"Je ne peux pas emporter ce corps-là.","zh":"我不能带走这具尸体。","t":[4425,6938]},{"fr":"C’est trop lourd.","zh":"这太重了。","t":[6938,7825]}]},{"id":"ch26p70","audio":true,"sents":[{"fr":"Moi je me taisais.","zh":"我只是在保持沉默。","t":[100,1112]}]},{"id":"ch26p71","audio":true,"sents":[{"fr":"— Mais ce sera comme une vieille écorce abandonnée.","zh":"——但是这就像一片被遗弃的老树皮。","t":[100,4275]},{"fr":"Ce n’est pas triste les vieilles écorces…","zh":"老树皮并不悲伤……","t":[4275,6088]}]},{"id":"ch26p72","audio":true,"sents":[{"fr":"Moi je me taisais.","zh":"我只是在保持沉默。","t":[100,1112]}]},{"id":"ch26p73","audio":true,"sents":[{"fr":"Il se découragea un peu.","zh":"他有点泄气了。","t":[100,2362]},{"fr":"Mais il fit encore un effort :","zh":"但他还是再试了一次：","t":[2362,4463]}]},{"id":"ch26p74","audio":true,"sents":[{"fr":"— Ce sera gentil, tu sais.","zh":"——这会很棒的，你知道的。","t":[100,3625]},{"fr":"Moi aussi je regarderai les étoiles.","zh":"我也会看星星的。","t":[3625,6475]},{"fr":"Toutes les étoiles seront des puits avec une poulie rouillée.","zh":"所有的星星都将变成有生锈滑轮的井。","t":[6475,10012]},{"fr":"Toutes les étoiles me verseront à boire…","zh":"所有的星星都会给我倒酒……","t":[10012,11987]}]},{"id":"ch26p75","audio":true,"sents":[{"fr":"Moi je me taisais.","zh":"我就这样沉默着。","t":[100,1112]}]},{"id":"ch26p76","audio":true,"sents":[{"fr":"— Ce sera tellement amusant !","zh":"——多么有趣啊！","t":[100,4062]},{"fr":"Tu auras cinq cents millions de grelots, j’aurai cinq cents millions de fontaines…","zh":"你将拥有五亿个铃铛，我将拥有五亿个喷泉……","t":[4062,7650]}]},{"id":"ch26p77","audio":true,"sents":[{"fr":"Et il se tut aussi, parce qu’il pleurait…","zh":"他也沉默了，因为他哭了……","t":[100,2213]}]},{"id":"ch26p78","audio":true,"sents":[{"fr":"— C’est là.","zh":"——就在这里。","t":[100,2462]},{"fr":"Laisse-moi faire un pas tout seul.","zh":"让我自己先迈一步。","t":[2462,4025]}]},{"id":"ch26p79","audio":true,"sents":[{"fr":"Et il s’assit parce qu’il avait peur.","zh":"他因为害怕而坐了下来。","t":[100,1750]}]},{"id":"ch26p80","audio":true,"sents":[{"fr":"Il dit encore :","zh":"他又说：","t":[100,1600]}]},{"id":"ch26p81","audio":true,"sents":[{"fr":"— Tu sais…","zh":"你知道……","t":[100,1900]},{"fr":"ma fleur…","zh":"我的花……","t":[1900,2638]},{"fr":"j’en suis responsable !","zh":"我对此负责！","t":[2638,5200]},{"fr":"Et elle est tellement faible !","zh":"她如此脆弱……","t":[5200,7838]},{"fr":"Et elle est tellement naïve.","zh":"她如此天真。","t":[7838,9888]},{"fr":"Elle a quatre épines de rien du tout pour la protéger contre le monde…","zh":"她只有四根刺，几乎不能保护自己免受世界的伤害……","t":[9888,13063]}]},{"id":"ch26p82","audio":true,"sents":[{"fr":"Moi je m’assis parce que je ne pouvais plus me tenir debout.","zh":"我坐下来是因为我再也站不住了。","t":[100,3712]},{"fr":"Il dit :","zh":"他说：","t":[3712,4962]}]},{"id":"ch26p83","audio":true,"sents":[{"fr":"— Voilà…","zh":"——","t":[100,2450]},{"fr":"C’est tout…","zh":"这就是全部……","t":[2450,2963]}]},{"id":"ch26p84","audio":true,"sents":[{"fr":"Il hésita encore un peu, puis il se releva.","zh":"他犹豫了一下，然后站了起来。","t":[100,3462]},{"fr":"Il fit un pas.","zh":"他迈出了一步。","t":[3462,5038]},{"fr":"Moi je ne pouvais pas bouger.","zh":"我动弹不得。","t":[5038,6487]}]},{"id":"ch26p85","audio":true,"sents":[{"fr":"Il n’y eut rien qu’un éclair jaune près de sa cheville.","zh":"他的脚踝旁只闪过一道黄色的闪电。","t":[100,3375]},{"fr":"Il demeura un instant immobile.","zh":"他停顿了一会儿，一动不动。","t":[3375,6100]},{"fr":"Il ne cria pas.","zh":"他没有喊叫。","t":[6100,7812]},{"fr":"Il tomba doucement comme tombe un arbre.","zh":"他像一棵树倒下一样轻轻地倒了下去。","t":[7812,10688]},{"fr":"Ça ne fit même pas de bruit, à cause du sable.","zh":"因为沙子，这甚至没有发出任何声响。","t":[10688,13288]}]},{"id":"ch26p86","audio":true,"sents":[]},{"id":"ch26p87","audio":true,"sents":[]}]},{"id":"ch27","title_fr":"Chapitre XXVII","title_zh":"第 27 章","paras":[{"id":"ch27p00","audio":true,"sents":[{"fr":"Et maintenant, bien sûr, ça fait six ans déjà…","zh":"现在，当然，已经六年了...","t":[100,3800]},{"fr":"Je n’ai jamais encore raconté cette histoire.","zh":"我从来没有讲过这个故事。","t":[3800,7025]},{"fr":"Les camarades qui m’ont revu ont été bien contents de me revoir vivant.","zh":"看到我活着的同伴们都很高兴。","t":[7025,11412]},{"fr":"J’étais triste mais je leur disais : C’est la fatigue…","zh":"我很伤心，但我告诉他们：这是疲劳...","t":[11412,14850]}]},{"id":"ch27p01","audio":true,"sents":[{"fr":"Maintenant je me suis un peu consolé.","zh":"现在我稍微安慰了一些。","t":[100,2825]},{"fr":"C’est à dire…","zh":"也就是说...","t":[2825,3800]},{"fr":"pas tout à fait.","zh":"并不完全是这样。","t":[3800,5412]},{"fr":"Mais je sais bien qu’il est revenu à sa planète, car, au lever du jour, je n’ai pas retrouvé son corps.","zh":"但我很清楚他回到了他的星球，因为，在日出时，我没有找到他的尸体。","t":[5412,11825]},{"fr":"Ce n’était pas un corps tellement lourd…","zh":"那并不是一个如此沉重的身体...","t":[11825,14400]},{"fr":"Et j’aime la nuit écouter les étoiles.","zh":"我喜欢在夜晚倾听星星。","t":[14400,17062]},{"fr":"C’est comme cinq cent millions de grelots…","zh":"这就像五亿个铃铛声...","t":[17062,18738]}]},{"id":"ch27p02","audio":true,"sents":[{"fr":"Mais voilà qu’il se passe quelque chose d’extraordinaire.","zh":"但是，发生了件不寻常的事。","t":[100,3788]},{"fr":"La muselière que j’ai dessinée pour le petit prince, j’ai oublié d’y ajouter la courroie de cuir !","zh":"我为小王子设计的那个口套，我忘记给它加上皮带扣了！","t":[3788,10112]},{"fr":"Il n’aura jamais pu l’attacher au mouton.","zh":"他永远也没法把它系在羊身上。","t":[10112,13012]},{"fr":"Alors je me demande : \"Que s’est-il passé sur sa planète ?","zh":"于是我就想：\"在他的星球上发生了什么事呢？\"","t":[13012,18138]},{"fr":"Peut-être bien que le mouton a mangé la fleur…\"","zh":"也许羊真的把花给吃了...","t":[18138,20537]}]},{"id":"ch27p03","audio":true,"sents":[{"fr":"Tantôt je me dis : \"Sûrement non !","zh":"有时我又对自己说：\"肯定不会的！\"","t":[100,4162]},{"fr":"Le petit prince enferme sa fleur toutes les nuits sous son globe de verre, et il surveille bien son mouton…\" Alors je suis heureux.","zh":"小王子每晚把他的花放在玻璃罩下，而且他很留心他的羊...于是我就高兴起来。","t":[4162,12050]},{"fr":"Et toutes les étoiles rient doucement.","zh":"所有的星星都轻轻地笑起来。","t":[12050,13575]}]},{"id":"ch27p04","audio":true,"sents":[{"fr":"Tantôt je me dis : \"On est distrait une fois ou l’autre, et ça suffit !","zh":"有时我又对自己说：\"人总会分心的，一次就够了！\"","t":[100,5938]},{"fr":"Il a oublié, un soir, le globe de verre, ou bien le mouton est sorti sans bruit pendant la nuit…\" Alors les grelots se changent tous en larmes !…","zh":"他有一天晚上忘了玻璃球，或者羊在夜幕下悄无声息地溜走了……然后所有的铃铛都变成了眼泪！……","t":[5938,14737]}]},{"id":"ch27p05","audio":true,"sents":[{"fr":"C’est là un bien grand mystère.","zh":"这是一个很大的谜团。","t":[100,2512]},{"fr":"Pour vous qui aimez aussi le petit prince, comme pour moi, rien de l’univers n’est semblable si quelque part, on ne sait où, un mouton que nous ne connaissons pas a, oui ou non, mangé une rose…","zh":"对于你们这些也像我一样喜欢小王子的人来说，宇宙中没有任何事物能与之相比，除非在某个我们不知道的地方，有一只我们不认识的羊，是或不是，吃了一朵玫瑰……","t":[2512,12587]}]},{"id":"ch27p06","audio":true,"sents":[{"fr":"Regardez le ciel.","zh":"看看天空。","t":[100,2112]},{"fr":"Demandez-vous : le mouton oui ou non a-t-il mangé la fleur ?","zh":"问问自己：羊是或不是吃了那朵花？","t":[2112,7462]},{"fr":"Et vous verrez comme tout change…","zh":"然后你会发现一切都变了……","t":[7462,8912]}]},{"id":"ch27p07","audio":true,"sents":[{"fr":"Et aucune grande personne ne comprendra jamais que ça a tellement d’importance !","zh":"任何大人物都不可能永远理解这有多么重要！","t":[100,4425]}]},{"id":"ch27p08","audio":true,"sents":[{"fr":"Ça c’est, pour moi, le plus beau et le plus triste paysage du monde.","zh":"对我来说，这就是世界上最美丽和最悲伤的风景。","t":[100,4912]},{"fr":"C’est le même paysage que celui de la page précédente, mais je l’ai dessiné une fois encore pour bien vous le montrer.","zh":"这是与上一页相同的风景，但我又画了一次，以便更好地展示给你。","t":[4912,11600]},{"fr":"C’est ici que le petit prince a apparu sur terre, puis disparu.","zh":"这就是小王子出现在地球上，然后消失的地方。","t":[11600,14937]}]},{"id":"ch27p09","audio":true,"sents":[{"fr":"Regardez attentivement ce paysage afin d’être sûrs de le reconnaître, si vous voyagez un jour en Afrique, dans le désert.","zh":"仔细看看这片风景，以便在你们有一天去非洲沙漠旅行时能认出它。","t":[100,7700]},{"fr":"Et, s’il vous arrive de passer par là, je vous en supplie, ne vous pressez pas, attendez un peu juste sous l’étoile !","zh":"如果你们路过这里，我恳求你们，不要着急，就在星星下稍作等待！","t":[7700,15300]},{"fr":"Si alors un enfant vient à vous, s’il rit, s’il a des cheveux d’or, s’il ne répond pas quand on l’interroge, vous devinerez bien qui il est.","zh":"如果那时有个孩子来到你们身边，如果他笑了，如果他有一头金发，如果他回答问题时总是沉默，你们就能猜出他是谁了。","t":[15300,23350]},{"fr":"Alors soyez gentils !","zh":"那么，请你们行个方便！","t":[23350,26050]},{"fr":"Ne me laissez pas tellement triste : écrivez-moi vite qu’il est revenu…","zh":"不要让我如此伤心：快点写信告诉我他回来了……","t":[26050,29900]}]},{"id":"ch27p10","audio":true,"sents":[]}]}]};